    var title: String {
        switch self {
        case .firstBites: "First bites"
        case .graspAndMouth: "Grasp and mouth"
        case .textureExplorer: "Texture explorer"
        case .pincerPractice: "Pincer practice"
        case .familyTable: "Family table"
        }
