    static let recipes: [SolidsReferenceRecipe] = {
        var results = coreRecipes
        var seen = Set(results.map(\.id))
        let proteins = ["Lentil", "Black bean", "Chickpea", "Chicken", "Turkey", "Beef", "Salmon", "Egg", "Tofu", "Plain whole-milk yogurt", "Ricotta", "Cod"]
        let produce = ["Sweet potato", "Avocado", "Broccoli", "Carrot", "Zucchini", "Pear", "Apple", "Pea", "Spinach", "Cauliflower", "Pumpkin", "Mango"]
        let bases = ["Oatmeal", "Quinoa", "Rice", "Polenta", "Pasta", "Couscous", "Potato", "Corn tortilla"]

        outer: for (proteinIndex, protein) in proteins.enumerated() {
            for (produceIndex, fruitOrVegetable) in produce.enumerated() {
                for (baseIndex, base) in bases.enumerated() {
                    let id = "meal-\(slug(protein))-\(slug(fruitOrVegetable))-\(slug(base))"
                    guard seen.insert(id).inserted else { continue }
                    let index = proteinIndex + produceIndex + baseIndex
                    let age = base == "Pasta" || base == "Couscous" || base == "Corn tortilla" ? 9 : 6
                    let mealType = SolidsMealType.allCases[index % SolidsMealType.allCases.count]
                    results.append(recipe(
                        id,
                        generatedRecipeTitle(
                            protein: protein,
                            produce: fruitOrVegetable,
                            base: base,
                            styleIndex: index
                        ),
                        [protein, fruitOrVegetable, base],
                        age,
                        generatedRecipeInstructions(
                            protein: protein,
                            produce: fruitOrVegetable,
                            base: base,
                            age: age,
                            styleIndex: index
                        ),
                        mealType: mealType
                    ))
                    if results.count >= 424 { break outer }
                }
            }
        }
        return results
    }()

    private static let recipesByID: [String: SolidsReferenceRecipe] =
        Dictionary(uniqueKeysWithValues: recipes.map { ($0.id, $0) })

    private static let recipesByFoodID: [String: [SolidsReferenceRecipe]] = {
        var result: [String: [SolidsReferenceRecipe]] = [:]
        for recipe in recipes {
            var includedFoodIDs = Set<String>()
            for name in recipe.foodNames {
                guard let foodID = food(named: name)?.id,
                      includedFoodIDs.insert(foodID).inserted else { continue }
                result[foodID, default: []].append(recipe)
            }
        }
        return result
    }()

    private static let recipesByAllergenID: [String: [SolidsReferenceRecipe]] = {
        var result: [String: [SolidsReferenceRecipe]] = [:]
        for recipe in recipes {
            for allergenID in recipe.allergenIDs {
                result[allergenID, default: []].append(recipe)
            }
        }
        return result
    }()

    private static let recipeSearchEntries: [RecipeSearchEntry] = recipes.map { recipe in
        RecipeSearchEntry(
            recipe: recipe,
            normalizedText: normalized(([recipe.title] + recipe.foodNames).joined(separator: " "))
        )
    }

    private static func generatedRecipeTitle(
        protein: String,
        produce: String,
        base: String,
        styleIndex: Int
    ) -> String {
        switch styleIndex % 6 {
        case 0: return "Creamy \(protein) and \(produce) \(base) bowl"
        case 1: return "Soft \(protein), \(produce) and \(base) patties"
        case 2: return "\(produce) \(base) with tender \(protein)"
        case 3: return "One-pot \(protein) and \(produce) \(base)"
        case 4: return "Scoopable \(protein), \(produce) and \(base) mash"
        default: return "Family-style \(protein) with \(produce) and \(base)"
        }
    }

    private static func generatedRecipeInstructions(
        protein: String,
        produce: String,
        base: String,
        age: Int,
        styleIndex: Int
    ) -> String {
        let finish = age < 9
            ? "Mash or load onto a spoon; offer a soft graspable piece only when it squishes easily."
            : "Keep it moist and serve as soft pieces, a scoopable mixture, or a tender patty for current skills."
        switch styleIndex % 6 {
        case 0:
            return "Cook \(base.lowercased()) until very soft. Prepare \(protein.lowercased()) fully and cook \(produce.lowercased()) until tender. Stir together with water as needed for a creamy bowl. \(finish)"
        case 1:
            return "Cook \(protein.lowercased()), \(produce.lowercased()), and \(base.lowercased()) until fully done. Mash, shape into soft patties, and cook until the center is set without forming a hard crust. \(finish)"
        case 2:
            return "Make \(base.lowercased()) soft and moist. Fold in tender \(produce.lowercased()), then add fully cooked \(protein.lowercased()) in a texture appropriate for the child. \(finish)"
        case 3:
            return "Simmer \(protein.lowercased()) and \(produce.lowercased()) with \(base.lowercased()) until every component is soft and fully cooked. Add water during cooking so the mixture does not become dry or sticky. \(finish)"
        case 4:
            return "Prepare \(protein.lowercased()) safely, cook \(produce.lowercased()) until it crushes easily, and soften \(base.lowercased()). Mash together but leave gradually more texture as skills develop. \(finish)"
        default:
            return "Cook \(protein.lowercased()) completely and prepare \(produce.lowercased()) and \(base.lowercased()) without added salt. Set aside the child's portion, then modify its shape and texture before seasoning the family meal. \(finish)"
        }
    }

    static let guidedFoods: [SolidsReferenceFood] = {
        let preferredNames = [
            "Avocado", "Oatmeal", "Lentil", "Banana", "Egg", "Sweet potato", "Plain whole-milk yogurt",
            "Broccoli", "Peanut butter", "Chicken", "Pear", "Tofu", "Salmon", "Apple", "Tahini",
            "Black bean", "Mango", "Ricotta", "Quinoa", "Carrot", "Shrimp", "Beef", "Pea", "Cod"
        ]
        var selected = preferredNames.compactMap(food(named:))
        var seen = Set(selected.map(\.id))
        let remainder = foods.filter(\.isEligibleForGuidedPath).sorted { lhs, rhs in
            let lhsScore = (lhs.isIronRich ? 3 : 0) + (!lhs.allergenIDs.isEmpty ? 2 : 0)
            let rhsScore = (rhs.isIronRich ? 3 : 0) + (!rhs.allergenIDs.isEmpty ? 2 : 0)
            if lhsScore != rhsScore { return lhsScore > rhsScore }
            return lhs.name.localizedStandardCompare(rhs.name) == .orderedAscending
        }
        for food in remainder where selected.count < 100 && seen.insert(food.id).inserted {
            selected.append(food)
        }
        return selected
    }()

    static let guidedCandidateFoods: [SolidsReferenceFood] = {
        let preferredIDs = Set(guidedFoods.map(\.id))
        return guidedFoods + foods.filter { !preferredIDs.contains($0.id) }
    }()

    static func allergenGuidance(_ allergen: SolidsAllergen) -> SolidsAllergenGuidance {
        let form: String
        let portion: String
        switch allergen {
        case .milk:
            form = "Pasteurized plain yogurt or another dairy food already appropriate for the child's skills; not cow's milk as the main drink before 12 months."
            portion = "Example routine portion after tolerance: about 2 tablespoons plain yogurt."
        case .egg:
            form = "Egg cooked until the white and yolk are firm, mashed or cut for current skills."
            portion = "Example routine portion after tolerance: about one-third of a well-cooked egg."
        case .fish:
            form = "Fully cooked, carefully deboned fish served as moist flakes or a soft patty."
            portion = "Example routine portion after tolerance: about 2 tablespoons cooked flakes."
        case .crustaceanShellfish:
            form = "Fully cooked shellfish, shell and tail removed, then minced finely into a familiar food."
            portion = "Example routine portion after tolerance: about 1–2 tablespoons minced shellfish."
        case .treeNuts:
            form = "Smooth tree-nut butter thinned into a familiar food, or nuts ground to a fine powder—never whole nuts."
            portion = "Example routine portion after tolerance: up to 2 teaspoons smooth nut butter, well thinned."
        case .peanuts:
            form = "Smooth peanut butter thinned with warm water or mixed into a familiar soft food—never whole peanuts or thick spoonfuls."
            portion = "NIAID example: 2 teaspoons smooth peanut butter provides about 2 g peanut protein; thin before serving."
        case .wheat:
            form = "A soft wheat food such as well-cooked pasta, wheat cereal, or lightly toasted bread modified for current skills."
            portion = "Example routine portion after tolerance: about 2 tablespoons cooked wheat cereal or pasta."
        case .soy:
            form = "Soft tofu, mashed edamame, or another cooked soy food modified for current skills."
            portion = "Example routine portion after tolerance: about 2 tablespoons soft tofu or mashed soy food."
        case .sesame:
            form = "Tahini thinned into a familiar soft food—never a thick spoonful."
            portion = "Example routine portion after tolerance: up to 2 teaspoons tahini, well thinned."
        }
        return SolidsAllergenGuidance(
            allergen: allergen,
            safeForm: form,
            exampleServing: portion,
            steps: [
                SolidsAllergenIntroductionStep(number: 1, title: "Choose one allergen", detail: "Offer it when the child is well, earlier in the day, in an infant-safe form. Use a familiar food alongside it."),
                SolidsAllergenIntroductionStep(number: 2, title: "Start with a small taste", detail: "Offer a small taste, pause for about 10 minutes, and watch closely. Stop if a possible reaction appears."),
                SolidsAllergenIntroductionStep(number: 3, title: "Build the serving", detail: "If no reaction appears, gradually offer more of the prepared portion during the meal without pressuring the child to finish."),
                SolidsAllergenIntroductionStep(number: 4, title: "Keep it in rotation", detail: "After it is tolerated, continue offering an age-appropriate form as a normal part of the weekly meal rotation.")
            ],
            sourceURLs: allergen == .peanuts
                ? [SolidsSourceLibrary.aapAllergenIntroduction, SolidsSourceLibrary.niaidPeanutGuidance]
                : [SolidsSourceLibrary.aapAllergenIntroduction, SolidsSourceLibrary.fdaAllergens]
        )
    }

    static func introductionServingGuidance(
        for allergen: SolidsAllergen,
        step: Int
    ) -> String {
        let guidance = allergenGuidance(allergen)
        if step <= 1 {
            return "Start with a small taste, pause for about 10 minutes, then gradually offer more of the prepared portion if no possible reaction appears. \(guidance.exampleServing)"
        }
        return "Repeat \(guidance.safeForm) \(guidance.exampleServing) The child never has to finish the example portion."
    }

    static func food(id: String) -> SolidsReferenceFood? {
        foodsByID[id]
    }

    static func food(named name: String) -> SolidsReferenceFood? {
        foodsByLookupName[normalized(name)]
    }

    static func foodSummary(id: String) -> SolidsReferenceFoodSummary? {
        foodSummariesByID[id]
    }

    static func foodSummary(named name: String) -> SolidsReferenceFoodSummary? {
        foodSummariesByLookupName[normalized(name)]
    }

    static func recipe(id: String) -> SolidsReferenceRecipe? {
        recipesByID[id]
    }

    static func search(_ query: String, category: SolidsFoodCategory? = nil) -> [SolidsReferenceFood] {
        searchSummaries(query, category: category).compactMap { foodsByID[$0.id] }
    }

    static func searchSummaries(
        _ query: String,
        category: SolidsFoodCategory? = nil,
        in foods: [SolidsReferenceFoodSummary]? = nil
    ) -> [SolidsReferenceFoodSummary] {
        let key = normalized(query)
        return (foods ?? foodSummaries).filter { food in
            guard category == nil || food.category == category,
                  key.isEmpty || food.normalizedSearchTerms.contains(where: { $0.contains(key) }) else {
                return false
            }
            return true
        }
    }

    static func recipes(containingFoodID foodID: String) -> [SolidsReferenceRecipe] {
        recipesByFoodID[foodID] ?? []
    }

    static func recipes(containingAllergenID allergenID: String) -> [SolidsReferenceRecipe] {
        recipesByAllergenID[allergenID] ?? []
    }

    static func searchRecipes(_ query: String) -> [SolidsReferenceRecipe] {
        let key = normalized(query)
        guard !key.isEmpty else { return recipes }
        return recipeSearchEntries.compactMap { entry in
            entry.normalizedText.contains(key) ? entry.recipe : nil
        }
    }

    private static func recipe(
        _ id: String,
        _ title: String,
        _ foodNames: [String],
        _ age: Int,
        _ instructions: String,
        allergens: [String] = [],
        mealType: SolidsMealType = .breakfast
    ) -> SolidsReferenceRecipe {
        let references = foodNames.compactMap(food(named:))
        let resolvedAllergens = Set(allergens + references.flatMap(\.allergenIDs))
        let categories = Set(references.map(\.category))
        var tags = [SolidsDietaryTag]()
        if categories.isDisjoint(with: [.meat, .seafood]) { tags.append(.vegetarian) }
        if categories.isDisjoint(with: [.meat, .seafood, .dairy, .egg]) { tags.append(.vegan) }
        if !resolvedAllergens.contains(SolidsAllergen.milk.rawValue) { tags.append(.dairyFree) }
        if !resolvedAllergens.contains(SolidsAllergen.egg.rawValue) { tags.append(.eggFree) }
        if !resolvedAllergens.contains(SolidsAllergen.wheat.rawValue) { tags.append(.wheatFree) }
        if references.contains(where: \.isIronRich) { tags.append(.ironRich) }
        return SolidsReferenceRecipe(
            id: id,
            title: title,
            ingredients: foodNames.map { name in
                SolidsRecipeIngredient(
                    foodName: name,
                    quantity: ingredientQuantity(for: name),
                    substitutionNames: substitutions(for: name)
                )
            },
            minimumAgeMonths: age,
            instructions: instructions,
            allergenIDs: Array(resolvedAllergens).sorted(),
            mealType: mealType,
            dietaryTags: tags,
            servings: 1
        )
    }

    private static func makeFood(summary: SolidsReferenceFoodSummary) -> SolidsReferenceFood {
        let id = summary.id
        let name = summary.name
        let category = summary.category
        let allergens = summary.allergenIDs
        let possibleAllergens = summary.possibleAllergenIDs
        let minimumAge = summary.minimumAgeMonths
        let isIronRich = summary.isIronRich
        let visuals = servingVisuals(name: name, category: category)
        let preparationStages = preparations(name: name, category: category, minimumAge: minimumAge)
            .enumerated()
            .map { index, stage in
                var stage = stage
                let visual = visuals.indices.contains(index) ? visuals[index] : (visuals.last ?? .spoon)
                stage.servingAmount = servingAmountGuidance(
                    name: name,
                    category: category,
                    ageMonths: stage.minimumAgeMonths,
                    visual: visual
                )
                return stage
            }
        return SolidsReferenceFood(
            id: id,
            name: name,
            category: category,
            aliases: summary.aliases,
            minimumAgeMonths: minimumAge,
            isIronRich: isIronRich,
            allergenIDs: allergens,
            possibleAllergenIDs: possibleAllergens,
            details: foodDetails(
                name: name,
                category: category,
                minimumAge: minimumAge,
                allergens: allergens,
                possibleAllergens: possibleAllergens
            ),
            safetyNote: safetyNote(name: name, category: category),
            chokingGuidance: chokingGuidance(name: name, category: category),
            preparations: preparationStages,
            servingVisuals: visuals,
            sourceURLs: sourceURLs(
                name: name,
                category: category,
                hasAllergens: !allergens.isEmpty || !possibleAllergens.isEmpty
            )
        )
    }

    private static func foodDetails(
        name: String,
        category: SolidsFoodCategory,
        minimumAge: Int,
        allergens: [String],
        possibleAllergens: [String]
    ) -> SolidsFoodDetails {
        let key = normalized(name)
        if key == "acai" {
            return SolidsFoodDetails(
                introductionSummary: "Açaí can be offered once a child is developmentally ready for solids, generally around 6 months. Use commercially prepared seedless pulp, purée, or powder rather than a fresh seeded berry.",
                backgroundSummary: "Açaí is a deep-purple palm fruit native to the Amazon region of South America. Outside growing regions, it is usually sold as frozen deseeded pulp, purée packets, or powder rather than as fresh berries.",
                nutritionContext: "Açaí contains plant pigments called anthocyanins, but research in people is too limited to support many of the health claims used to market açaí products. Choose food products rather than supplements or energy blends, which may contain caffeine or other ingredients intended for adults.",
                allergenSummary: "Açaí is not one of the nine major U.S. food allergens, although any food can cause a reaction. Published reports document allergy to date fruit and a rare anaphylactic reaction to heart of palm, but they do not establish that someone with either allergy will react to açaí. If the child has a known allergy to another palm-family food, discuss introduction with their clinician; otherwise start with a small amount and increase over later meals if tolerated.",
                choosingGuidance: "Look for an unsweetened frozen deseeded pulp or purée, or a plain powder with a short ingredient list. Check bowls and blends for honey, caffeine-containing supplements, added sugar, granola, whole nuts, large seeds, or other ingredients that need separate modification.",
                storageGuidance: "Keep frozen pulp frozen until needed and follow the package's thawing and refrigeration directions. Use thawed product promptly, keep prepared food cold, and discard food left in the child's bowl after the meal.",
                questions: [
                    SolidsFoodQuestion(
                        question: "When can a child have açaí juice?",
                        answer: "Do not offer fruit juice before 12 months. After the first birthday, an occasional small serving of pasteurized juice can be offered, but whole or puréed fruit is usually more useful because it retains fiber. WHO guidance recommends limiting 100% fruit juice during complementary feeding, and raw açaí fruit or juice has a documented contamination risk, so avoid unpasteurized products."
                    )
                ]
            )
        }

        let introductionSummary = ingredientIntroduction(
            name: name,
            category: category,
            minimumAge: minimumAge
        )

        let allergenNames = allergens.compactMap { SolidsAllergen(rawValue: $0)?.displayName }
        let possibleAllergenNames = possibleAllergens.compactMap { SolidsAllergen(rawValue: $0)?.displayName }
        let allergenSummary: String
        if !allergenNames.isEmpty {
            allergenSummary = "\(name) contains \(readableList(allergenNames)), which \(allergenNames.count == 1 ? "is a major food allergen" : "are major food allergens"). When first introducing it, use a developmentally appropriate form, start with a small amount, and avoid combining it with several other new allergens in the same meal."
        } else if !possibleAllergenNames.isEmpty {
            allergenSummary = "\(name) is a prepared food whose recipe may contain \(readableList(possibleAllergenNames)). Check the actual recipe or package label because allergen content varies. Any food can cause an individual reaction even when it is not one of the nine major allergens."
        } else {
            allergenSummary = "\(name) is not one of the nine major U.S. food allergens. An individual reaction is still possible with any food, so begin with a small amount and increase over later meals if it is tolerated."
        }

        let handling = ingredientHandling(name: name, category: category)

        return SolidsFoodDetails(
            introductionSummary: introductionSummary,
            backgroundSummary: ingredientBackground(name: name, category: category),
            nutritionContext: nil,
            allergenSummary: allergenSummary,
            choosingGuidance: handling.choosing,
            storageGuidance: handling.storage,
            questions: []
        )
    }

    private static func readableList(_ values: [String]) -> String {
        switch values.count {
        case 0: return ""
        case 1: return values[0]
        case 2: return "\(values[0]) and \(values[1])"
        default: return "\(values.dropLast().joined(separator: ", ")), and \(values.last ?? "")"
        }
    }

    private static func ingredientIntroduction(
        name: String,
        category: SolidsFoodCategory,
        minimumAge: Int
    ) -> String {
        let key = normalized(name)
        if key == "honey" {
            return "Do not offer honey in any form before 12 months because it can contain spores that cause infant botulism."
        }
        if key == "swordfish" {
            return "Swordfish is not recommended for young children because it is among the fish highest in mercury. Choose a lower-mercury fish from current FDA/EPA advice instead."
        }
        if key.contains("milk in food") || key == "buttermilk in food" {
            return "Pasteurized \(name.lowercased()) can be used as an ingredient once a child is ready for solids, generally around 6 months. It should not replace breast milk or infant formula as the main drink before 12 months."
        }
        if minimumAge >= 12 {
            return "\(name) should not be offered before \(minimumAge) months."
        }
        if category == .herbAndFlavor {
            return "\(name) can be used as a culinary flavoring from the start of solids, generally around 6 months."
        }
        return "\(name) can generally be introduced once a child shows developmental readiness for solids, usually around 6 months."
    }

    private static func retiredIngredientIntroduction(
        name: String,
        category: SolidsFoodCategory,
        minimumAge: Int
    ) -> String {
        let key = normalized(name)
        if key == "honey" {
            return "Do not offer honey in any form before 12 months because it can contain spores that cause infant botulism. After the first birthday, use only a small amount and remember that honey is an added sugar."
        }
        if key == "swordfish" {
            return "Swordfish is not recommended for young children because it is among the fish highest in mercury. Choose a lower-mercury fish from current FDA/EPA advice instead."
        }
        if ["cactus pear", "prickly pear"].contains(key) {
            return "\(name) can generally be introduced once a child shows developmental readiness for solids, usually around 6 months. Use only fruit with every spine and hair-like glochid removed, peel away the outer skin, and serve the ripe soft flesh in a mash or another manageable form."
        }
        if key.contains("milk in food") || key == "buttermilk in food" {
            return "Pasteurized \(name.lowercased()) can be used as an ingredient once a child is ready for solids, generally around 6 months. Cow's milk should not replace breast milk or infant formula as the main drink before 12 months."
        }
        if category == .nutAndSeed {
            let riskGuidance = key == "peanut butter" || key == "peanut"
                ? " If the child has severe eczema or an egg allergy, ask their clinician how and where to introduce peanut."
                : ""
            return "\(name) can generally be introduced once a child is developmentally ready for solids, usually around 6 months. \(nutAndSeedSpecificPreparation(name: name))\(riskGuidance)"
        }
        if category == .herbAndFlavor {
            return "\(name) can season food from the start of solids in a small culinary amount. \(flavorSpecificPreparation(name: name))"
        }
        if category == .preparedFood {
            let profile = preparedFoodEditorialProfile(name: name)
            return "In this catalog, \(name.lowercased()) means \(profile.definition). It can be adapted once the child is developmentally ready for solids and every named ingredient is age-appropriate. \(profile.preparation)"
        }
        if minimumAge >= 12 {
            return "\(name) should not be offered before \(minimumAge) months. When it is introduced, use the ingredient-specific preparation and safety guidance below."
        }

        let lead = "\(name) can generally be introduced once a child shows developmental readiness for solids, usually around 6 months. "
        let guidance: String
        switch category {
        case .fruit:
            let trim = fruitTrimmingGuidance(name: name)
            switch fruitPreparationForm(name: name) {
            case .sauce:
                guidance = "Choose an unsweetened, spoonable sauce and check the ingredient list for honey or added sugar."
            case .smallRoundBerry:
                guidance = "Cook if firm, then mash or flatten every berry so it no longer keeps a small round shape."
            case .aggregateBerry:
                guidance = "\(trim) Mash, flatten, or tear the ripe berry when its size or firmness makes that necessary."
            case .roundOrSlipperyFruit:
                guidance = "\(trim) Mash or cut the ripe flesh lengthwise so it is not served whole and round."
            case .citrus:
                guidance = "Remove peel, seeds, tough membrane, and excess pith, then offer the juicy pulp in a manageable soft form."
            case .firmFruit:
                guidance = "Cook or finely grate the fruit until it is no longer a hard raw chunk, and remove the core and seeds."
            case .stoneFruit:
                guidance = "Remove the pit and use very ripe, soft flesh; cook it first when the fruit is still firm."
            case .melon:
                guidance = "\(trim) Offer soft flesh without forming small slippery balls."
            case .softFruit:
                guidance = "\(trim) Mash the ripe flesh or offer a soft piece that yields to light pressure."
            case .seededPulp:
                guidance = "Scoop the soft pulp from the rind and serve it by spoon, removing any large or unexpectedly hard seed."
            case .arils:
                guidance = "Crush or flatten the arils rather than offering a handful of intact firm, round pieces."
            case .driedStickyFruit:
                guidance = "Remove the pit, soften the dried fruit thoroughly, and mash or mince it into moist food so it cannot form a dense sticky mouthful."
            case .gratedFlesh:
                guidance = "Use finely grated flesh or a smooth coconut product mixed into moist food, not hard chunks or chewy dry strips."
            case .cookBeforeServing:
                guidance = "\(trim) Serve only when the cooked edible flesh is soft throughout."
            }
        case .vegetable:
            let trim = vegetableTrimmingGuidance(name: name)
            switch vegetablePreparationForm(name: name) {
            case .leafy:
                guidance = "Cook the leaves and stems until tender, chop across the fibers, and mix them into moist food rather than offering a wad of leaves."
            case .flower:
                guidance = "Cook the thickest stem and florets until they crush easily, then mash or offer a large soft floret."
            case .compactBud:
                guidance = "Cook through the dense center and halve, quarter, mash, or flatten the round bud rather than serving it whole."
            case .squash:
                guidance = "\(trim) Cook the edible flesh until it crushes easily and avoid firm cubes."
            case .roundKernel:
                guidance = "Cook until soft, then mash or flatten the kernels or peas so they do not remain small and round."
            case .pod:
                guidance = "Trim strings and seams, cook the pod until soft, and split or chop it rather than serving a firm intact pod."
            case .stalk:
                guidance = "Trim woody or stringy sections, cook until tender, and cut across the fibers."
            case .bulb:
                guidance = "Cook it until soft and use it within a moist dish rather than offering firm raw chunks or slippery layers."
            case .swollenStem:
                guidance = "\(trim) Cook the pale interior until it crushes easily, then mash it or offer a broad soft spear."
            case .softFlesh:
                guidance = "\(trim) Use ripe or cooked edible flesh and avoid small slippery cubes."
            case .root:
                guidance = "Cook until the center crushes easily, or use a specifically recommended fine-grated preparation instead of hard raw pieces."
            case .tuber:
                guidance = "Cook it fully and keep the starchy flesh moist rather than serving a dry, dense mouthful."
            case .fibrousSpecialty:
                guidance = "\(trim) Cook the edible portion thoroughly before adapting its texture."
            }
        case .grain:
            switch grainPreparationForm(name: name) {
            case .bread:
                guidance = "Use a soft or lightly toasted piece that tears easily, and avoid dense gummy balls or hard crusts."
            case .pasta:
                guidance = "Cook it past firm until tender, shorten long strands or modify large shapes, and keep it moist."
            case .puffedCereal:
                guidance = "Use only a product that dissolves readily, testing the exact puff before serving and avoiding dry handfuls."
            case .softGrain:
                guidance = "Cook it with enough liquid to make a moist mash or scoopable cereal without hard kernels or sticky clumps."
            }
        case .beanAndPlantProtein:
            switch plantProteinPreparationForm(name: name) {
            case .wholePulse:
                guidance = "Cook until the center mashes easily, then mash or flatten whole beans and peas for an early eater."
            case .softTofu:
                guidance = "Offer the soft curd by spoon or in soft scoops, checking that it has no rubbery surface or firm add-ins."
            case .firmTofu:
                guidance = "Use moist strips, crumbles, or soft pieces that compress and break apart easily."
            case .fermentedCake:
                guidance = formedPlantProteinPreparation(name: name)
            case .spread:
                guidance = plantProteinSpreadPreparation(name: name)
            case .seasoning:
                guidance = plantProteinSeasoningPreparation(name: name)
            case .sprout:
                guidance = "Cook sprouts thoroughly, then chop across their length and mix them into moist food."
            }
        case .meat:
            switch meatPreparationForm(name: name) {
            case .organ:
                guidance = "Cook it fully, keep it moist, and remove membrane, tough ducts, or connective tissue before mashing or mincing it."
            case .ground:
                guidance = "Cook it fully and keep crumbles, a patty, or a meatball tender and moist rather than dry or rubbery."
            case .boneIn:
                guidance = "Cook it fully until tender, take all meat off the bone, and remove loose bone, cartilage, gristle, and tough skin before serving."
            case .tenderCut:
                guidance = "Cook it fully with a moisture-retaining method and use a boneless portion. If the cut was cooked on the bone, take the meat off and inspect it again; remove any gristle or tough connective tissue, then shred across the grain or mince it with sauce."
            }
        case .seafood:
            switch seafoodPreparationForm(name: name) {
            case .crustacean:
                guidance = "Cook it fully, remove shell and tail, and mince or flatten the flesh rather than serving a whole curled piece."
            case .bivalve:
                guidance = "Cook it fully, remove every shell fragment, and mince the chewy flesh finely into moist food."
            case .cephalopod:
                guidance = "Cook until tender and mince very finely; rings, tentacles, and rubbery chunks are not appropriate early forms."
            case .smallFish, .fillet:
                guidance = "Choose the species using current fish advice, cook it fully, check the portion carefully for bones, and serve moist flakes."
            }
        case .dairy:
            guidance = dairySpecificPreparation(name: name)
        case .egg:
            guidance = key == "egg yolk"
                ? "Cook the yolk fully, then mash it with moisture so it is soft rather than dry and crumbly."
                : "Cook the egg fully while keeping it soft, then mash it or cut it into a shape suited to the child's skills."
        case .nutAndSeed, .herbAndFlavor, .preparedFood:
            preconditionFailure("Earlier ingredient-specific introduction branch did not return for \(name)")
        }
        return lead + guidance
    }

    private static func ingredientBackground(
        name: String,
        category: SolidsFoodCategory
    ) -> String {
        let key = normalized(name)
        if key == "banana" {
            return "Banana is a peelable tropical fruit. Its starchy flesh becomes softer and sweeter as it ripens."
        }
        if ["cactus pear", "prickly pear"].contains(key) {
            return "\(name) is the fruit of a cactus. Its soft interior contains numerous hard seeds, while the outer skin can carry obvious spines and tiny hair-like glochids."
        }
        switch category {
        case .fruit:
            switch fruitPreparationForm(name: name) {
            case .sauce:
                return "\(name) is cooked fruit processed into a spoonable sauce; sweetness, ingredients, and thickness vary by product."
            case .smallRoundBerry:
                return "\(name) is a small berry whose skin and firmness vary with ripeness and variety."
            case .aggregateBerry:
                return "\(name) is a berry made of clustered sections; ripe fruit is delicate and usually collapses under light pressure."
            case .roundOrSlipperyFruit:
                return "\(name) has a small round or notably slippery edible portion. Ripeness, skin, and internal pits or seeds vary by this specific fruit."
            case .citrus:
                return "\(name) is a citrus fruit with juicy pulp enclosed by peel, pith, and segment membrane."
            case .firmFruit:
                return "\(name) is a firm-fleshed fruit whose crispness changes with ripeness and cooking."
            case .stoneFruit:
                return "\(name) is a fleshy fruit built around one large central pit; its texture changes substantially as it ripens."
            case .melon:
                return "\(name) is a melon with high-water, slippery flesh inside a rind and seed-bearing interior."
            case .softFruit:
                return "\(name) is a soft-fleshed fruit whose edible portion and ripening pattern are specific to this fruit."
            case .seededPulp:
                return "\(name) is eaten mainly for the spoonable pulp inside its rind rather than as slices of flesh."
            case .arils:
                return "\(name) is eaten as juice-filled arils separated from a tough rind and internal membrane."
            case .driedStickyFruit:
                return "\(name) is commonly sold dried, which concentrates its sweetness and gives it a dense, sticky texture."
            case .gratedFlesh:
                return "\(name) is the firm edible flesh of a coconut; fresh, dried, grated, butter, and milk forms have very different textures."
            case .cookBeforeServing:
                return "\(name) is a starchy or firm fruit that becomes edible and tender through cooking rather than ripening alone."
            }
        case .vegetable:
            switch vegetablePreparationForm(name: name) {
            case .leafy: return "\(name) is a leafy vegetable with thin leaves and stems whose fibrousness varies by maturity."
            case .flower: return "\(name) is an edible flower or flower head with branching florets and a denser stem."
            case .compactBud: return "\(name) is a compact, round bud made of tightly layered leaves around a dense center."
            case .squash: return "\(name) is a squash with a variety-specific rind, seed cavity, and edible flesh."
            case .roundKernel: return "\(name) forms small round kernels or peas whose skin and firmness can persist after cooking."
            case .pod: return "\(name) is a pod vegetable that can contain strings, seams, and small round seeds."
            case .stalk: return "\(name) is a stalk or stem vegetable with fibers that run lengthwise."
            case .bulb: return "\(name) is an aromatic bulb or allium made of layered flesh."
            case .swollenStem: return "\(name) is the swollen stem of the plant, not a root or layered bulb."
            case .softFlesh: return "\(name) has tender edible flesh once ripe or cooked, with variety-specific skin and seeds."
            case .root: return "\(name) is a firm root vegetable whose texture changes substantially with cooking."
            case .tuber: return "\(name) is a starchy underground vegetable that requires cooking before it is eaten."
            case .fibrousSpecialty: return "\(name) has a specialized edible portion surrounded by parts that remain fibrous or inedible."
            }
        case .grain:
            switch grainPreparationForm(name: name) {
            case .bread: return "\(name) is a baked or griddled grain food whose density and moisture vary by recipe."
            case .pasta: return "\(name) is a shaped grain product whose size, strand length, and chewiness depend on its ingredients and cooking."
            case .puffedCereal: return "\(name) is an expanded dry cereal; products vary in hardness and how readily they dissolve."
            case .softGrain: return "\(name) is a grain, pseudograin, or cereal served cooked, with texture determined largely by liquid and cooking time."
            }
        case .beanAndPlantProtein:
            switch plantProteinPreparationForm(name: name) {
            case .wholePulse: return "\(name) is a pulse or legume with an outer skin and a center that softens through cooking."
            case .softTofu: return "\(name) is soybean curd with a soft, custard-like texture."
            case .firmTofu: return "\(name) is soybean curd pressed into a firmer block; firmness varies substantially by product."
            case .fermentedCake: return "\(name) is a formed, fermented plant-protein food with a product-specific structure."
            case .spread: return "\(name) is a mashed plant-protein spread whose thickness and ingredients vary by recipe."
            case .seasoning: return "\(name) is a concentrated fermented soybean seasoning rather than a stand-alone protein portion."
            case .sprout: return "\(name) is a sprouted legume with a crisp stem and small seed head."
            }
        case .meat:
            switch meatPreparationForm(name: name) {
            case .organ: return "\(name) is organ meat with a concentrated micronutrient profile and a texture that changes quickly with cooking."
            case .ground: return "\(name) is minced meat or a ground-meat preparation whose fat, seasoning, and final moisture vary by product."
            case .boneIn: return "\(name) is a bone-in cut that can also include skin, cartilage, gristle, and connective tissue."
            case .tenderCut: return "\(name) is a muscle-meat cut whose tenderness depends on cooking method and the direction of its grain."
            }
        case .seafood:
            switch seafoodPreparationForm(name: name) {
            case .crustacean: return "\(name) is a crustacean shellfish with firm curved flesh inside an external shell."
            case .bivalve: return "\(name) is a bivalve mollusk with compact flesh enclosed by a shell."
            case .cephalopod: return "\(name) is a cephalopod whose flesh can become rubbery with some cooking methods."
            case .smallFish: return "\(name) is a small fish often sold whole, canned, cured, or packed in oil."
            case .fillet: return "\(name) is a finfish generally sold as a fillet; bone pattern and mercury guidance vary by species."
            }
        case .dairy:
            switch dairyPreparationForm(name: name) {
            case .milkIngredient: return "\(name) is dairy used as a recipe ingredient rather than as an infant's primary beverage."
            case .pourableCultured: return "\(name) is a fermented, pourable dairy food."
            case .spoonableDairy: return "\(name) is a soft, spoonable dairy food."
            case .softSpread: return "\(name) is a soft fresh-cheese spread whose density and salt vary by product."
            case .crumblyCheese: return "\(name) is a crumbly cheese whose salt, dryness, and lump size vary by style."
            case .firmCheese: return "\(name) is a sliceable or grateable cheese whose moisture and firmness vary by style."
            case .paneer: return "\(name) is a non-melting fresh cheese with a firm curd structure."
            }
        case .egg:
            return key == "egg yolk" ? "Egg yolk is the yolk portion of an egg, separated from most or all of the white." : "\(name) is an egg or a cooked egg preparation."
        case .nutAndSeed:
            if key.contains("butter") || key == "tahini" { return "\(name) is a smooth paste made from a specific nut or seed; thickness and added ingredients vary by product." }
            if key.contains("ground") { return "\(name) is that specific nut milled into a meal; particle size can vary within and between packages." }
            if key.contains("seed") { return "\(name) is the edible seed named in this entry, sold whole, ground, or processed into a paste." }
            return "\(name) is the edible nut named in this entry, sold whole or processed into ground meal or butter."
        case .herbAndFlavor:
            switch flavorPreparationForm(name: name) {
            case .leafyHerb: return "\(name) is a leafy culinary herb used for its aroma and flavor."
            case .fibrousAromatic: return "\(name) is a fibrous aromatic used to flavor a dish rather than as a stand-alone portion."
            case .groundSpice: return "\(name) is a culinary spice used in a small amount to flavor food."
            case .bayLeaf: return "Bay leaf is a stiff aromatic leaf used to infuse a cooked dish, not an edible leafy-herb portion."
            }
        case .preparedFood:
            return "In this catalog, \(name.lowercased()) means \(preparedFoodEditorialProfile(name: name).definition)."
        }
    }

    private static func retiredIngredientBackground(
        name: String,
        category: SolidsFoodCategory
    ) -> String {
        let key = normalized(name)
        if ["cactus pear", "prickly pear"].contains(key) {
            return "\(name) is the fruit of a cactus. The ripe interior can be soft and juicy, but the outer skin may carry obvious spines and tiny hair-like glochids that must be completely removed before the fruit enters the child's food-preparation area."
        }
        switch category {
        case .fruit:
            let trim = fruitTrimmingGuidance(name: name)
            switch fruitPreparationForm(name: name) {
            case .sauce:
                return "\(name) is cooked fruit processed into a spoonable sauce. The ingredient list and thickness vary by product, so an unsweetened, scoopable version is more useful than a squeeze pouch for learning to self-feed."
            case .smallRoundBerry:
                return "\(name) is a small berry whose skin and firmness vary with ripeness and variety. Its intact round form matters more for serving safety than its small overall size."
            case .aggregateBerry:
                return "\(name) is a delicate berry made of clustered sections. Ripe fruit usually collapses easily, while an underripe berry needs additional flattening or cutting. \(trim)"
            case .roundOrSlipperyFruit:
                return "\(name) has a round or slippery edible portion that must be cut lengthwise rather than served whole. \(trim)"
            case .citrus:
                return "\(name) is a citrus fruit with juicy pulp enclosed by peel, pith, and membrane. Seeds and tough membrane are the parts that most often need removal for a new eater."
            case .firmFruit:
                return "\(name) is a firm-fleshed fruit with a core or seeds. Raw pieces can stay hard and break into airway-sized chunks, while cooking or fine grating changes that texture."
            case .stoneFruit:
                return "\(name) is a fleshy fruit with a large central pit. Ripeness strongly affects texture: ripe flesh can be soft and slippery, while underripe flesh can remain too firm."
            case .melon:
                return "\(name) is a high-water fruit with slippery flesh. \(trim) Use a broad soft piece rather than a melon ball or small cube."
            case .softFruit:
                return "\(name) is served only when its edible flesh is fully ripe and yields to light pressure. \(trim)"
            case .seededPulp:
                return "\(name) is eaten mainly for the soft pulp inside its rind. It is a spoon food rather than a food that naturally progresses to slices, and any large or unexpectedly hard seed should be removed."
            case .arils:
                return "\(name) is eaten as juice-filled arils separated from a tough rind and membrane. Intact arils can remain firm and round, so crushing or flattening is part of early preparation."
            case .driedStickyFruit:
                return "\(name) is commonly sold dried, which concentrates sweetness and creates a dense, sticky texture. Softening and dispersing it through moist food is different from serving the whole dried fruit."
            case .gratedFlesh:
                return "\(name) is the firm edible flesh of a coconut. Fresh chunks and dry strips can be hard or chewy, while finely grated flesh, smooth coconut butter, and coconut milk behave differently in a meal."
            case .cookBeforeServing:
                return "\(name) is not an appropriate raw finger food and is cooked until its edible flesh crushes easily. \(trim)"
            }
        case .vegetable:
            let trim = vegetableTrimmingGuidance(name: name)
            switch vegetablePreparationForm(name: name) {
            case .leafy:
                return "\(name) is a leafy vegetable with thin leaves and potentially fibrous stems. Cooking, chopping across fibers, and mixing it into moist food prevents a stringy or loose mouthful."
            case .flower:
                return "\(name) is an edible flower or flower head with branching florets and a denser stem. Both parts can be served when cooked until they crush easily, but loose firm florets need additional chopping."
            case .compactBud:
                return "\(name) is a compact round bud made of tightly layered leaves. Its round shape and dense center both need modification even after the outside looks cooked."
            case .squash:
                return "\(name) is a squash whose skin, seed cavity, and flesh have a variety-specific preparation. \(trim) Judge doneness by whether the edible flesh crushes easily."
            case .roundKernel:
                return "\(name) forms small round kernels or peas. Even when cooked, each piece should be mashed or flattened for early eaters so it does not retain an airway-sized shape."
            case .pod:
                return "\(name) is a pod vegetable that can contain strings, seams, or small round seeds. Cook it soft, trim fibrous parts, and split or chop it rather than serving a firm intact pod."
            case .stalk:
                return "\(name) is a stalk or stem vegetable with fibers that run lengthwise. Thorough cooking and trimming or chopping across those fibers makes it easier to manage."
            case .bulb:
                return "\(name) is an aromatic bulb or allium used to build flavor. Cooking softens its layers and mellows its intensity; large slippery layers or firm raw chunks are not useful first shapes."
            case .swollenStem:
                return "\(name) is the swollen stem of the plant, not a root or layered bulb. \(trim) Cook the pale interior until tender for an early eater."
            case .softFlesh:
                return "\(name) is a tender-fleshed vegetable or culinary fruit once ripe or cooked. \(trim) Avoid small slippery cubes."
            case .root:
                return "\(name) is a firm root vegetable. Raw pieces can be hard, so it should be cooked until a piece crushes easily or finely grated when an appropriate raw preparation is specifically used."
            case .tuber:
                return "\(name) is a starchy underground vegetable that must be cooked before serving. Keep the cooked flesh moist because a dry, dense mouthful can be difficult to manage."
            case .fibrousSpecialty:
                return "\(name) has a specialized edible portion and requires its own trimming method. \(trim) Use only the fully cooked tender portion."
            }
        case .grain:
            switch grainPreparationForm(name: name) {
            case .bread:
                return "\(name) is a baked or griddled grain food whose texture depends on moisture, density, and toasting. Dense bread can become gummy, so preparation matters more than whether it is labeled soft."
            case .pasta:
                return "\(name) is a shaped grain product that becomes manageable only after thorough cooking. Size, strand length, chewiness, and moisture all affect how it should be served."
            case .puffedCereal:
                return "\(name) is an expanded dry cereal. Some puffs dissolve quickly while others remain hard, so test the exact product and avoid dry handfuls."
            case .softGrain:
                return "\(name) is a grain, pseudograin, or grain cereal generally served cooked. Water and cooking time determine whether it becomes a moist scoopable food or a dry, sticky mouthful."
            }
        case .beanAndPlantProtein:
            switch plantProteinPreparationForm(name: name) {
            case .wholePulse:
                return "\(name) is a pulse or legume that is served cooked. Its skin and round shape can persist after cooking, so softness plus mashing or flattening are important for early eaters."
            case .softTofu:
                return "\(name) is a soft soybean curd with a custard-like texture. It is naturally scoopable and should not be described or served like a firm strip of tofu."
            case .firmTofu:
                return "\(name) is a firmer soybean curd that can be cut into graspable strips, crumbled, or cooked into soft pieces. Firmness varies substantially by brand and style."
            case .fermentedCake:
                return "\(name) is a formed plant-protein food whose exact structure matters. \(formedPlantProteinPreparation(name: name))"
            case .spread:
                return "\(name) is a mashed plant-protein spread. \(plantProteinSpreadPreparation(name: name))"
            case .seasoning:
                return "\(name) is a concentrated fermented soybean seasoning rather than a stand-alone protein portion. \(plantProteinSeasoningPreparation(name: name))"
            case .sprout:
                return "\(name) is a sprouted legume with a crisp stem and small seed head. It should be cooked thoroughly for a young child, then chopped to remove stringy, slippery lengths."
            }
        case .meat:
            switch meatPreparationForm(name: name) {
            case .organ:
                return "\(name) is organ meat with a soft texture when cooked gently and a concentrated micronutrient profile. Use modest portions and avoid drying it into firm, crumbly chunks."
            case .ground:
                return "\(name) is minced meat or a ground-meat preparation. Moist patties, crumbles, or sauce-bound pieces are easier to manage than dry, rubbery balls."
            case .boneIn:
                return "\(name) is a bone-in cut. The meat may become tender with slow cooking, but every loose bone, cartilage fragment, tough skin, and piece of gristle must be removed before serving."
            case .tenderCut:
                return "\(name) is a muscle-meat cut whose tenderness depends on cooking method and direction of the grain. Use a boneless portion for the child's serving, and choose moist shredding or mincing rather than dry cubes."
            }
        case .seafood:
            switch seafoodPreparationForm(name: name) {
            case .crustacean:
                return "\(name) is a crustacean shellfish with firm curved flesh inside a shell. Remove all shell and tail, cook fully, and mince or flatten the flesh because a whole curled piece can be rubbery."
            case .bivalve:
                return "\(name) is a mollusk with chewy flesh enclosed by a shell. Use only fully cooked flesh, discard every shell fragment, and mince finely into moist food."
            case .cephalopod:
                return "\(name) is a cephalopod whose flesh can become rubbery. Cook it fully until tender and mince very finely rather than offering rings, tentacles, or chewy chunks."
            case .smallFish:
                return "\(name) is a small oily fish often sold whole, canned, cured, or packed in oil. Product sodium varies, and bones still require careful checking even when some small bones soften during processing."
            case .fillet:
                return "\(name) is a finfish generally served as a fillet. Species-specific mercury guidance matters, and every serving needs a careful bone check before the cooked flesh is flaked."
            }
        case .dairy:
            switch dairyPreparationForm(name: name) {
            case .milkIngredient:
                return "\(name) is dairy used as a recipe ingredient rather than offered as an infant's primary beverage. \(dairySpecificPreparation(name: name))"
            case .pourableCultured:
                return "\(name) is a fermented pourable dairy food, not a cheese or sliceable food. \(dairySpecificPreparation(name: name))"
            case .spoonableDairy:
                return "\(name) is a soft spoonable dairy food rather than a sliceable cheese progression. \(dairySpecificPreparation(name: name))"
            case .softSpread:
                return "\(name) is a soft fresh-cheese spread whose dense texture must be loosened or spread thinly. \(dairySpecificPreparation(name: name))"
            case .crumblyCheese:
                return "\(name) is a crumbly cheese whose salt, dryness, and lump size matter for serving. \(dairySpecificPreparation(name: name))"
            case .firmCheese:
                return "\(name) is a sliceable or grateable cheese whose moisture and firmness vary by style. \(dairySpecificPreparation(name: name))"
            case .paneer:
                return "\(name) is a non-melting fresh cheese that must be cooked and crumbled rather than treated like melting cheese. \(dairySpecificPreparation(name: name))"
            }
        case .egg:
            return normalized(name) == "egg yolk"
                ? "\(name) is the yolk portion of an egg. Egg is a major allergen, and the yolk should be cooked fully and moistened rather than served as a dry, crumbly ball."
                : "\(name) is an egg or cooked egg preparation. Egg is a major allergen, and the finished food should be cooked through while staying soft rather than rubbery."
        case .nutAndSeed:
            return "\(name) requires a form chosen for its actual structure. \(nutAndSeedSpecificPreparation(name: name))"
        case .herbAndFlavor:
            return "\(name) is a culinary flavoring rather than a stand-alone portion. \(flavorSpecificPreparation(name: name))"
        case .preparedFood:
            let profile = preparedFoodEditorialProfile(name: name)
            return "\(name) is defined here as \(profile.definition). \(profile.preparation)"
        }
    }

    private static func ingredientHandling(
        name: String,
        category: SolidsFoodCategory
    ) -> (choosing: String, storage: String) {
        let key = normalized(name)
        if key == "banana" {
            return (
                "Choose a banana with an intact yellow peel and brown speckles; the flesh should mash without springing back and should not be green, chalky, bruised through, split, or moldy.",
                "Ripen an intact banana at room temperature. Refrigerating a ripe banana can darken its peel while slowing further softening; refrigerate cut flesh promptly and discard the child's served leftovers."
            )
        }
        switch category {
        case .fruit:
            if ["cactus pear", "prickly pear"].contains(key) {
                return (
                    "Choose commercially de-spined \(name.lowercased()) when possible, with intact skin and no mold or leaking damage.",
                    "Keep the intact fruit isolated so loose glochids cannot contact other food. Refrigerate peeled or cut flesh promptly."
                )
            }
            let choosing: String
            let storage: String
            switch fruitPreparationForm(name: name) {
            case .sauce:
                choosing = "Choose unsweetened \(name.lowercased()) with a short ingredient list and no honey for a child under 12 months. A jar or cup lets you assess thickness before serving."
                storage = "Refrigerate the opened product promptly and follow its use-after-opening directions. Portion it with a clean utensil."
            case .smallRoundBerry, .aggregateBerry:
                choosing = "Choose \(name.lowercased()) without mold, leaking juice, or shriveled damage. Fresh and frozen products are both usable."
                storage = "Refrigerate fresh \(name.lowercased()) and wash shortly before use. Keep frozen fruit frozen until needed and refrigerate thawed or cooked portions promptly."
            case .roundOrSlipperyFruit:
                choosing = "Choose intact \(name.lowercased()) without mold, leaking flesh, or a fermented odor, and select fruit whose edible flesh has reached full ripeness."
                storage = "Refrigerate whole \(name.lowercased()) and wash it shortly before use. Refrigerate cut flesh promptly."
            case .citrus:
                choosing = "Choose \(name.lowercased()) that feels heavy for its size and has no mold, split skin, or deep soft spots."
                storage = "Refrigerate whole \(name.lowercased()) for longer storage and chill peeled fruit promptly in a covered container."
            case .firmFruit:
                choosing = "Choose unbroken \(name.lowercased()) without mold, deep bruising, or a mealy collapsed interior. For pears, select the ripeness needed for the intended meal."
                storage = "Refrigerate whole \(name.lowercased()); let a firm pear ripen at room temperature first when needed. Chill cut or cooked portions promptly."
            case .stoneFruit:
                choosing = "Choose \(name.lowercased()) without split skin, mold, or deep bruising; ripe flesh should yield to light pressure without leaking or smelling fermented."
                storage = "Let firm \(name.lowercased()) soften at room temperature, then refrigerate the ripe fruit. Refrigerate cut flesh promptly."
            case .melon:
                choosing = "Choose an intact \(name.lowercased()) without cracks, mold, leaking areas, or a fermented odor."
                storage = "Keep the whole melon clean and dry. Refrigerate it promptly after cutting in a covered container."
            case .softFruit:
                choosing = "Choose \(name.lowercased()) without mold, leaking damage, or a fermented odor; the edible flesh should have the ripeness described for this fruit."
                storage = "Keep whole \(name.lowercased()) under the normal conditions used to ripen that fruit, then refrigerate it if needed. Refrigerate cut flesh promptly."
            case .seededPulp:
                choosing = "Choose an intact, heavy \(name.lowercased()) without mold or leaking damage; the interior pulp should smell fresh rather than fermented."
                storage = "Refrigerate opened pulp promptly in a clean covered container."
            case .arils:
                choosing = "Choose an intact pomegranate without cracks, mold, or leaking juice; separated arils should look bright and smell fresh."
                storage = "Refrigerate removed pomegranate arils promptly in a covered container."
            case .driedStickyFruit:
                choosing = "Choose pitted \(name.lowercased()) without mold or a hard sugar-crusted exterior, and check packaged fruit for added sugar and sulfites."
                storage = "Keep the dried fruit sealed and dry. Refrigerate rehydrated or cooked portions promptly."
            case .gratedFlesh:
                choosing = "Choose coconut flesh with no sour odor, mold, or shell fragment. Packaged grated coconut should be unsweetened."
                storage = "Refrigerate fresh or opened coconut flesh in a covered container and follow the package date for grated products."
            case .cookBeforeServing:
                choosing = "Choose intact \(name.lowercased()) without mold, leaking damage, or deep soft spots."
                storage = "Keep the whole fruit clean and dry, refrigerating it when appropriate for that fruit. Refrigerate cooked flesh promptly."
            }
            return (choosing, storage)
        case .vegetable:
            let choosing: String
            switch vegetablePreparationForm(name: name) {
            case .leafy:
                choosing = "Choose crisp \(name.lowercased()) without slime, yellowed damage, or wilted cut ends."
            case .flower, .compactBud, .stalk:
                choosing = "Choose firm \(name.lowercased()) without slime, mold, dried cut ends, or yellowed edible sections."
            case .squash:
                choosing = "Choose intact \(name.lowercased()) without mold, leaking cuts, or collapsed soft spots; confirm the exact variety when skin and rind differ."
            case .roundKernel:
                choosing = "Choose fresh, frozen, or no-salt-added \(name.lowercased()) without spoilage or severe freezer burn."
            case .pod:
                choosing = "Choose crisp \(name.lowercased()) without slime, brown wet spots, or a dried stem end; older pods are more likely to be stringy."
            case .bulb:
                choosing = "Choose firm \(name.lowercased()) without mold, slime, sprouting damage, or dried edible layers."
            case .swollenStem:
                choosing = "Choose a small, firm kohlrabi without cracks, woody swelling, or wilted attached leaves."
            case .softFlesh:
                choosing = "Choose intact \(name.lowercased()) without mold, slime, leaking cuts, or deep collapsed spots."
            case .root:
                choosing = "Choose firm \(name.lowercased()) without mold, deep cuts, extensive soft spots, or a woody center."
            case .tuber:
                choosing = "Choose firm \(name.lowercased()) without mold, leaking cuts, extensive soft spots, sprouts, or unsafe discoloration specific to that tuber."
            case .fibrousSpecialty:
                choosing = "Choose fresh or properly packaged \(name.lowercased()) without mold, slime, leaking damage, or a dried fibrous cut end."
            }
            let storesDry = category == .vegetable && ["potato", "sweet potato", "yam"].contains(key)
            let storage = storesDry
                ? "Keep whole \(name.lowercased()) cool, dark, dry, and ventilated. Refrigerate cut or cooked portions promptly."
                : "Refrigerate fresh \(name.lowercased()) clean, dry, and appropriately covered. Refrigerate cut or cooked portions promptly."
            return (choosing, storage)
        case .grain:
            let choosing: String
            switch grainPreparationForm(name: name) {
            case .bread: choosing = "Choose plain \(name.lowercased()) with modest sodium, a clear allergen label, no whole nuts or hard seeds, and a texture that is not unusually dense."
            case .pasta: choosing = "Choose plain \(name.lowercased()) with a clear allergen label; size and shape should suit the preparation planned for the child."
            case .puffedCereal: choosing = "Choose unsweetened, lower-sodium \(name.lowercased()) with a clear allergen label and no hard clusters."
            case .softGrain:
                choosing = key.contains("infant")
                    ? "Choose iron-fortified infant \(name.lowercased()) without added sugar and check its milk, soy, and wheat labeling."
                    : "Choose plain \(name.lowercased()) with little or no added sugar, an intact dry package, and a clear allergen label."
            }
            return (choosing, "Keep dry \(name.lowercased()) sealed and dry. Refrigerate cooked portions promptly; cool cooked rice and grains without leaving them at room temperature.")
        case .beanAndPlantProtein:
            let choosing: String
            switch plantProteinPreparationForm(name: name) {
            case .wholePulse: choosing = "Choose dried, frozen, or no-salt-added \(name.lowercased()) when practical; dried pulses should be clean and canned containers intact."
            case .softTofu, .firmTofu: choosing = "Choose plain refrigerated \(name.lowercased()) from an intact package and confirm its firmness, sodium, and soy-allergen label."
            case .fermentedCake: choosing = "Choose plain \(name.lowercased()) with modest sodium and check soy, wheat, or other allergen ingredients."
            case .spread: choosing = "Choose \(name.lowercased()) with modest sodium, a smooth texture, and a complete allergen list."
            case .seasoning: choosing = "Choose commercially packaged \(name.lowercased()) with a clear soy-allergen label and compare sodium between products."
            case .sprout: choosing = "Choose refrigerated \(name.lowercased()) from intact packaging by its use-by date, with no slime or sour odor."
            }
            let storage = plantProteinPreparationForm(name: name) == .wholePulse
                ? "Store dry pulses sealed and dry. Refrigerate cooked, thawed, canned, or opened \(name.lowercased()) promptly."
                : "Keep \(name.lowercased()) refrigerated according to its package directions and use a clean utensil after opening."
            return (choosing, storage)
        case .meat:
            let detail: String
            switch meatPreparationForm(name: name) {
            case .organ: detail = "The surface should be moist but not slimy, and the package should not leak."
            case .ground: detail = "For formed products, compare sodium, seasoning, and added allergens."
            case .boneIn: detail = "Choose a cut with intact bone and no loose fragments visible through the package."
            case .tenderCut: detail = "An unseasoned cut makes sodium and added allergens easier to control."
            }
            return ("Choose fresh or properly frozen \(name.lowercased()) from intact packaging. \(detail)", "Keep raw \(name.lowercased()) cold, contained, and separate from ready-to-eat food. Refrigerate cooked leftovers promptly.")
        case .seafood:
            return (
                "Choose fresh or properly frozen \(name.lowercased()) from a reliable source, with intact packaging and no strong off odor. Check current FDA/EPA advice for the exact species and processed products for sodium and added allergens.",
                "Keep raw \(name.lowercased()) cold, contained, and separate from ready-to-eat food. Refrigerate cooked leftovers promptly."
            )
        case .dairy:
            let choosing: String
            switch dairyPreparationForm(name: name) {
            case .milkIngredient: choosing = "Choose pasteurized \(name.lowercased()) with a clear milk-allergen label and no added sweetener when practical."
            case .pourableCultured: choosing = "Choose pasteurized, plain \(name.lowercased()) and compare added sugar and sodium between products."
            case .spoonableDairy: choosing = "Choose pasteurized, plain, unsweetened \(name.lowercased()) with an age-appropriate fat content and no hard mix-ins."
            case .softSpread: choosing = "Choose pasteurized \(name.lowercased()) with modest sodium, no mold or spoilage, and a clear milk-allergen label."
            case .crumblyCheese, .firmCheese, .paneer: choosing = "Choose pasteurized \(name.lowercased()) with modest sodium, no mold or dried damage, and a clear milk-allergen label."
            }
            return (choosing, "Keep \(name.lowercased()) refrigerated and follow its package date and use-after-opening directions.")
        case .egg:
            return ("Choose clean, uncracked eggs or an intact pasteurized egg product for \(name.lowercased()). For prepared versions, check the complete ingredient list.", "Keep eggs and prepared \(name.lowercased()) refrigerated; chill cooked leftovers promptly.")
        case .nutAndSeed:
            let choosing: String
            if key.contains("butter") || key == "tahini" {
                choosing = "Choose plain, unsalted, smooth \(name.lowercased()) with no crunchy pieces and confirm the exact nut or seed allergen on the label."
            } else if key.contains("ground") {
                choosing = "Choose plain, finely milled \(name.lowercased()) with no coarse fragments and confirm the exact nut allergen on the label."
            } else {
                choosing = "Choose plain, unsalted \(name.lowercased()) without rancid odor or visible mold and confirm the exact nut or seed allergen on the label."
            }
            return (choosing, "Seal \(name.lowercased()) tightly and follow the package's room-temperature or refrigeration directions.")
        case .herbAndFlavor:
            let choosing: String
            switch flavorPreparationForm(name: name) {
            case .leafyHerb: choosing = "Choose fresh \(name.lowercased()) with clean, aromatic leaves and no slime, mold, or severely wilted sections."
            case .fibrousAromatic: choosing = "Choose firm, aromatic \(name.lowercased()) without mold, wet decay, or a dried hollow interior."
            case .groundSpice: choosing = "Choose culinary \(name.lowercased()) with a clear ingredient list and no added salt or stimulant ingredients."
            case .bayLeaf: choosing = "Choose whole culinary bay leaves that are dry, aromatic, and easy to count before and after cooking."
            }
            return (choosing, "Keep dried \(name.lowercased()) sealed, cool, and dry. Refrigerate fresh herbs or cut aromatics as appropriate.")
        case .preparedFood:
            let profile = preparedFoodEditorialProfile(name: name)
            return ("Choose or make \(name.lowercased()) that matches this entry—\(profile.definition)—then verify the full ingredient and allergen list and compare sodium when relevant.", "Refrigerate prepared \(name.lowercased()) within two hours, or within one hour above 90°F. Use the shortest safe leftover window among its ingredients.")
        }
    }

    private static func retiredIngredientHandling(
        name: String,
        category: SolidsFoodCategory
    ) -> (choosing: String, storage: String) {
        let key = normalized(name)
        switch category {
        case .fruit:
            if ["cactus pear", "prickly pear"].contains(key) {
                return (
                    "Choose commercially de-spined \(name.lowercased()) when possible. The fruit should be intact and free of mold, and every visible or hair-like spine must be treated as still present until the peel is removed safely.",
                    "Keep the intact \(name.lowercased()) in a container that prevents loose glochids from contacting other food. Refrigerate peeled or cut flesh promptly and discard the child's served portion."
                )
            }
            if key == "banana" {
                return (
                    "Choose a banana with an intact yellow peel and brown speckles; the flesh should mash without springing back and should not be green, chalky, bruised through, split, or moldy.",
                    "Ripen an intact banana at room temperature. Refrigerating a ripe banana can darken its peel while slowing further softening; refrigerate cut flesh promptly and discard the child's served leftovers."
                )
            }
            switch fruitPreparationForm(name: name) {
            case .sauce:
                return (
                    "Choose unsweetened \(name.lowercased()) with a short ingredient list and no honey for a child under 12 months. A jar or cup makes thickness easier to assess than a pouch.",
                    "Refrigerate opened \(name.lowercased()) promptly, follow the product's use-after-opening directions, and portion it into a clean bowl rather than feeding from and saving the same container."
                )
            case .driedStickyFruit:
                return (
                    "Choose pitted \(name.lowercased()) without a hard, sugar-crusted exterior. Check for sulfites or added sugar when buying packaged dried fruit.",
                    "Keep dried \(name.lowercased()) sealed and dry. Refrigerate rehydrated or cooked portions promptly and discard the child's served leftovers."
                )
            case .smallRoundBerry, .aggregateBerry:
                return (
                    "Choose \(name.lowercased()) without mold or leaking packages. Fresh or frozen fruit is usable; thaw or cook firm frozen berries and assess every berry's softness before serving.",
                    "Refrigerate fresh \(name.lowercased()), wash shortly before use, and refrigerate cut, thawed, or cooked portions promptly."
                )
            case .citrus:
                return (
                    "Choose \(name.lowercased()) that feels heavy for its size and has no mold or deep soft spots. Seedless does not guarantee every segment is seed-free, so inspect after peeling.",
                    "Refrigerate whole \(name.lowercased()) for longer storage. Refrigerate peeled segments promptly in a covered container and discard pieces left in the child's bowl."
                )
            case .roundOrSlipperyFruit:
                return (
                    "Choose intact \(name.lowercased()) without mold, leaking flesh, or fermentation odor. Select flesh that can become soft enough for the named lengthwise preparation; do not rely on small size to make a whole fruit safe.",
                    "Refrigerate whole \(name.lowercased()) and wash it shortly before use. Refrigerate cut flesh promptly and discard the child's served pieces."
                )
            case .firmFruit:
                return (
                    "Choose firm, unbroken \(name.lowercased()) without mold or deep bruising. Plan to cook or finely grate it unless the prepared flesh is already soft enough for the child's chewing skill.",
                    "Refrigerate whole \(name.lowercased()); if a pear needs to soften first, let it ripen at room temperature and then refrigerate it. Chill cut or cooked portions promptly."
                )
            case .stoneFruit:
                return (
                    "Choose \(name.lowercased()) without split skin, mold, or deep bruising and use it only when the flesh yields to light pressure. The complete pit-removal check still applies even to packaged pieces.",
                    "Let firm \(name.lowercased()) soften at room temperature, then refrigerate the ripe fruit. Refrigerate cut flesh promptly and discard the child's served pieces."
                )
            case .melon:
                return (
                    "Choose an intact \(name.lowercased()) without cracks, mold, or leaking areas and wash the rind before the knife passes through it. Use flesh that is soft rather than crisp.",
                    "Keep whole \(name.lowercased()) clean and dry. Refrigerate it after cutting in a covered container and discard any cut melon left unrefrigerated for an unsafe interval."
                )
            case .softFruit:
                return (
                    "Choose \(name.lowercased()) without mold, leaking damage, or fermented odor and use only flesh that yields to light pressure after the named peel, seed, pit, or core removal.",
                    "Keep whole \(name.lowercased()) clean and dry while it reaches serving ripeness, then refrigerate it if it will not be used promptly. Refrigerate cut flesh and discard the child's served leftovers."
                )
            case .seededPulp:
                return (
                    "Choose an intact, heavy \(name.lowercased()) without mold or leaking damage. Open it only on a clean surface and inspect the spoonable pulp for the hard seeds identified in its preparation guidance.",
                    "Refrigerate opened \(name.lowercased()) pulp promptly in a covered container and discard pulp that has contacted the child's spoon."
                )
            case .arils:
                return (
                    "Choose an intact pomegranate without cracks, mold, or leaking juice. After opening, use only bright arils separated completely from the bitter membrane and leathery rind.",
                    "Refrigerate removed pomegranate arils promptly in a covered container and discard crushed arils left in the child's bowl."
                )
            case .gratedFlesh:
                return (
                    "Choose coconut flesh with no sour odor, mold, or shell fragment. Packaged grated coconut should be unsweetened and fine enough to mix completely into moist food.",
                    "Refrigerate fresh or opened coconut flesh in a covered container, follow the package date for grated products, and discard the child's served portion."
                )
            case .cookBeforeServing:
                return (
                    "Choose intact \(name.lowercased()) without mold, leaking damage, or deep soft spots and confirm that the complete trimming and cooking method can be followed before serving.",
                    "Keep whole \(name.lowercased()) clean and dry and refrigerate it if it will not be cooked promptly. Refrigerate cooked flesh promptly and discard the child's served portion."
                )
            }
        case .vegetable:
            let form = vegetablePreparationForm(name: name)
            switch form {
            case .leafy:
                return (
                    "Choose crisp \(name.lowercased()) without slime or yellowed, damaged leaves. Wash between leaves and trim thick or woody stems before cooking.",
                    "Refrigerate fresh \(name.lowercased()) dry and loosely covered. Chill cooked portions promptly and use a clean utensil when taking out the child's portion."
                )
            case .flower, .compactBud, .stalk:
                return (
                    "Choose firm \(name.lowercased()) without slime, mold, dried cut ends, or yellowed edible sections. Confirm that the thickest edible section can be trimmed and cooked until tender.",
                    "Refrigerate fresh \(name.lowercased()) dry and loosely covered. Refrigerate cooked portions promptly and discard the child's served leftovers."
                )
            case .squash:
                let isSummerSquash = ["yellow squash", "zucchini"].contains(key)
                return (
                    "Choose intact \(name.lowercased()) without mold, leaking cuts, or a collapsed soft spot. Recheck whether its named variety has edible tender skin or a hard rind that must be removed.",
                    isSummerSquash
                        ? "Refrigerate whole \(name.lowercased()) dry and uncut. Refrigerate cut or cooked portions promptly and discard the child's served leftovers."
                        : "Keep uncut \(name.lowercased()) cool, dry, and ventilated. Refrigerate cut or cooked flesh promptly and discard the child's served leftovers."
                )
            case .roundKernel:
                return (
                    "Choose fresh, frozen, or no-salt-added \(name.lowercased()) without freezer burn or spoilage and confirm every kernel or pea can be cooked soft and flattened.",
                    "Refrigerate fresh or thawed \(name.lowercased()), keep frozen portions frozen until use, and refrigerate cooked portions promptly."
                )
            case .pod:
                return (
                    "Choose crisp \(name.lowercased()) without slime, brown wet spots, or a dried stem end. Bend one pod to check for tough strings before preparing the batch.",
                    "Refrigerate fresh \(name.lowercased()) dry and unwashed until preparation. Refrigerate cooked pieces promptly and discard the child's served leftovers."
                )
            case .bulb:
                let refrigeratesFresh = ["fennel bulb", "green onion", "leek", "scallion"].contains(key)
                return (
                    "Choose firm \(name.lowercased()) without mold, slime, sprouting damage, or dried edible layers and complete the named root, peel, or outer-layer trimming.",
                    refrigeratesFresh
                        ? "Refrigerate fresh \(name.lowercased()) dry and loosely covered. Refrigerate cooked portions promptly and discard the child's served leftovers."
                        : "Keep whole \(name.lowercased()) cool, dry, dark, and ventilated. Refrigerate cut or cooked portions promptly and discard the child's served leftovers."
                )
            case .swollenStem:
                return (
                    "Choose a small, firm kohlrabi without cracks, woody swelling, or wilted attached leaves; a large old bulb is more likely to be fibrous.",
                    "Remove the leaves and refrigerate whole kohlrabi in a covered produce drawer. Refrigerate peeled or cooked pieces promptly."
                )
            case .softFlesh:
                return (
                    "Choose intact \(name.lowercased()) without mold, slime, leaking cuts, or deep soft spots and use the named stem, skin, pith, and seed check rather than a general produce trim.",
                    key == "tomato"
                        ? "Keep an uncut tomato at room temperature until ripe, then refrigerate it if it will not be used promptly. Refrigerate cut or cooked tomato and discard served leftovers."
                        : "Refrigerate whole \(name.lowercased()) dry and uncut. Refrigerate cut or cooked portions promptly and discard the child's served leftovers."
                )
            case .root:
                return (
                    "Choose firm \(name.lowercased()) without mold, deep cuts, extensive soft spots, or a woody center. Complete the named top, tail, peel, or rootlet trimming before cooking.",
                    "Refrigerate whole \(name.lowercased()) dry and uncut. Refrigerate cut or cooked portions promptly and discard the child's served leftovers."
                )
            case .tuber:
                let storesDry = ["potato", "sweet potato", "yam"].contains(key)
                return (
                    "Choose firm \(name.lowercased()) without mold, leaking cuts, extensive soft spots, or unsafe sprouts and discoloration identified in its trimming guidance.",
                    storesDry
                        ? "Keep whole \(name.lowercased()) cool, dark, dry, and ventilated. Refrigerate cooked portions promptly and never leave a foil-wrapped cooked tuber at room temperature."
                        : "Refrigerate fresh \(name.lowercased()) if it will not be cooked promptly. Refrigerate cooked portions and discard the child's served leftovers."
                )
            case .fibrousSpecialty:
                return (
                    "Choose fresh or properly packaged \(name.lowercased()) without mold, slime, leaking damage, or a dried fibrous cut end. Use only the exact edible portion named in its preparation guidance.",
                    "Refrigerate fresh or opened \(name.lowercased()) promptly and keep any canned remainder in a clean covered container. Refrigerate cooked portions and discard the child's served leftovers."
                )
            }
        case .grain:
            let isInfantCereal = key.contains("infant")
            let selection: String
            switch grainPreparationForm(name: name) {
            case .bread:
                selection = "Choose plain \(name.lowercased()) with modest sodium that tears easily. Review allergens and avoid a dense loaf, hard crust, whole nuts, or hard seeds."
            case .pasta:
                selection = "Choose plain \(name.lowercased()) with a clear allergen label and a shape that can be cooked very tender, shortened, or otherwise adapted."
            case .puffedCereal:
                selection = "Choose an unsweetened, lower-sodium \(name.lowercased()), check allergens and hard clusters, and test that the exact puff dissolves readily."
            case .softGrain:
                selection = isInfantCereal
                    ? "Choose an iron-fortified infant cereal without added sugar. Rotate grain types rather than relying only on rice cereal, and check the label for milk, soy, or wheat ingredients."
                    : "Choose plain \(name.lowercased()) with little or no added sugar and review its allergen label. Sort whole dry grains for debris when applicable."
            }
            return (
                selection,
                "Keep dry \(name.lowercased()) sealed and dry. Refrigerate cooked portions promptly, cool rice and other grains without leaving them at room temperature, and reheat only the portion being served."
            )
        case .beanAndPlantProtein:
            let form = plantProteinPreparationForm(name: name)
            switch form {
            case .wholePulse:
                return (
                    "Choose dried, frozen, or no-salt-added \(name.lowercased()) when practical. Drain and rinse canned versions, remove debris from dried pulses, and cook until the center mashes easily.",
                    "Refrigerate cooked or opened \(name.lowercased()) promptly. Store dry pulses sealed and dry, and discard any portion that has contacted the child's mouth or spoon."
                )
            case .sprout:
                return (
                    "Choose refrigerated \(name.lowercased()) from intact packaging by its use-by date. Young children should not eat raw or lightly cooked sprouts, and washing does not remove that risk.",
                    "Keep \(name.lowercased()) refrigerated and separate from ready-to-eat food, cook thoroughly until steaming hot, and discard served leftovers."
                )
            case .softTofu, .firmTofu:
                return (
                    "Choose plain refrigerated \(name.lowercased()) from an intact package and check sodium plus the soy allergen label. Match the stated firmness to the preparation guide.",
                    "Keep unopened and opened \(name.lowercased()) refrigerated according to the package. Use a clean utensil, chill cooked portions promptly, and discard the child's served portion."
                )
            case .fermentedCake:
                return (
                    "Choose plain \(name.lowercased()) with modest sodium and check soy, wheat, or other allergen ingredients. \(formedPlantProteinPreparation(name: name))",
                    "Follow package refrigeration directions, cook the portion fully when required, chill leftovers promptly, and discard the child's served portion."
                )
            case .spread:
                return (
                    "Choose \(name.lowercased()) with modest sodium and review the complete allergen list. \(plantProteinSpreadPreparation(name: name))",
                    "Keep \(name.lowercased()) refrigerated after opening as directed. Portion with a clean utensil and discard thinned spread or food left in the child's bowl."
                )
            case .seasoning:
                return (
                    "Choose commercially packaged \(name.lowercased()) with a clear soy-allergen label and compare sodium. \(plantProteinSeasoningPreparation(name: name))",
                    "Follow package refrigeration directions after opening, use a clean utensil, and do not save food from the child's bowl."
                )
            }
        case .meat:
            let selectionDetail: String
            switch meatPreparationForm(name: name) {
            case .organ:
                selectionDetail = "Choose a small fresh or properly frozen portion and plan to trim membrane, tough ducts, or connective tissue after cooking."
            case .ground:
                selectionDetail = "For ground or formed products, check sodium, seasoning, and allergen ingredients and choose a form that can stay tender and moist."
            case .boneIn:
                selectionDetail = "Choose a cut that can be cooked tender and plan to remove all meat from the bone before the child's portion is prepared."
            case .tenderCut:
                selectionDetail = "Choose an unseasoned cut that can be cooked tender. Use a boneless portion for the child, or plan to remove the cooked meat from the bone and inspect it again before serving."
            }
            return (
                "Choose fresh or properly frozen \(name.lowercased()) from intact packaging. Unseasoned products make sodium and allergens easier to control. \(selectionDetail)",
                "Keep raw \(name.lowercased()) cold and separate from ready-to-eat food. Cook to a safe internal temperature, refrigerate leftovers promptly, and never return the child's served portion to the main container."
            )
        case .seafood:
            let finalCheck: String
            switch seafoodPreparationForm(name: name) {
            case .crustacean:
                finalCheck = "Remove the full shell and tail after cooking and check for fragments."
            case .bivalve:
                finalCheck = "Use only fully cooked flesh and inspect it for shell fragments."
            case .cephalopod:
                finalCheck = "Use only fully cooked tender flesh and discard rubbery or inedible sections."
            case .smallFish, .fillet:
                finalCheck = "Inspect the cooked portion carefully for bones."
            }
            return (
                "Choose fresh or properly frozen \(name.lowercased()) from a reliable source and check current FDA/EPA mercury advice for the exact species. Avoid leaking packages or a strong off odor and inspect processed seafood for sodium and added allergens.",
                "Keep raw \(name.lowercased()) cold and separate, cook it fully, and refrigerate leftovers promptly. \(finalCheck) Discard served leftovers."
            )
        case .dairy:
            return (
                dairySpecificPreparation(name: name),
                "Keep \(name.lowercased()) refrigerated, follow its package date and use-after-opening directions, and discard portions that have been in the child's bowl."
            )
        case .egg:
            return (
                "Choose clean, uncracked eggs or a pasteurized egg product for \(name.lowercased()). Prepared versions may add milk, wheat, soy, or other allergens, so check the full recipe.",
                "Keep eggs refrigerated, cook \(name.lowercased()) until safely done, chill cooked egg promptly, and discard the child's served leftovers."
            )
        case .nutAndSeed:
            return (
                "Choose plain, unsalted \(name.lowercased()) and confirm the exact nut or seed allergen on the label. \(nutAndSeedSpecificPreparation(name: name))",
                "Seal \(name.lowercased()) tightly and follow the package's room-temperature or refrigeration directions. Discard any thinned or mixed portion left in the child's bowl."
            )
        case .herbAndFlavor:
            return (
                "Choose culinary \(name.lowercased()) without added salt or stimulant ingredients. \(flavorSpecificPreparation(name: name))",
                "Keep dried \(name.lowercased()) sealed, cool, and dry. Refrigerate fresh herbs or cut aromatics as appropriate and discard prepared food left in the child's bowl."
            )
        case .preparedFood:
            let profile = preparedFoodEditorialProfile(name: name)
            return (
                "Choose or make \(name.lowercased()) that matches this entry—\(profile.definition)—and check its ingredient list against the allergens named on this page. \(profile.preparation)",
                "Refrigerate prepared \(name.lowercased()) within two hours, or within one hour when the room is above 90°F, and use refrigerated leftovers within the shortest safe window for its ingredients. Reheat only the portion being served, cool it before offering, and discard food from the child's bowl."
            )
        }
    }

    private static func ingredientQuestions(
        name: String,
        category: SolidsFoodCategory,
        firstPreparation: String?
    ) -> [SolidsFoodQuestion] {
        let firstStage = firstPreparation
            ?? chokingGuidance(name: name, category: category)
        let progression = SolidsFoodQuestion(
            question: "What is the safest first preparation of \(name.lowercased())?",
            answer: firstStage
        )
        let practical: SolidsFoodQuestion
        switch category {
        case .fruit:
            if ["cactus pear", "prickly pear"].contains(normalized(name)) {
                practical = SolidsFoodQuestion(
                    question: "How do I prepare \(name.lowercased()) without leaving spines?",
                    answer: "Choose commercially de-spined fruit when possible. Otherwise protect your hands, remove every visible spine and hair-like glochid, wash the fruit, cut off the ends, peel away the whole outer skin, and clean the work area before preparing the soft flesh."
                )
            } else if normalized(name) == "banana" {
                practical = SolidsFoodQuestion(
                    question: "How ripe should banana be before serving?",
                    answer: "Choose a banana whose peel is yellow with brown speckles and whose flesh mashes without springing back. Remove the peel, loose strings, and firm stem end; cook or wait longer if the flesh is still chalky or firm."
                )
            } else {
                switch fruitPreparationForm(name: name) {
                case .sauce:
                    practical = SolidsFoodQuestion(
                        question: "What should I check when buying \(name.lowercased())?",
                        answer: "Choose unsweetened \(name.lowercased()) with a short ingredient list and no honey before 12 months. Serve it from a bowl or preloaded spoon so its thickness can be assessed; a squeeze pouch hides the texture and does not build the same spoon skills."
                    )
                case .driedStickyFruit:
                    practical = SolidsFoodQuestion(
                        question: "Can I serve \(name.lowercased()) straight from the package?",
                        answer: "Not as a whole dense, sticky dried fruit for a baby or young toddler. Confirm the pit is removed, soften it with liquid, and mash or mince it into moist food. Check packaged fruit for added sugar and sulfites."
                    )
                case .seededPulp:
                    practical = SolidsFoodQuestion(
                        question: "How should I serve the pulp from \(name.lowercased())?",
                        answer: "Scoop the pulp away from the rind and offer it by spoon or mixed into another soft food. Remove any large or unexpectedly hard seed; do not turn it into juice for an infant."
                    )
                case .gratedFlesh:
                    practical = SolidsFoodQuestion(
                        question: "Which forms of \(name.lowercased()) work for a young child?",
                        answer: "Use unsweetened finely grated flesh mixed into moist food, smooth coconut butter in a thin layer, or coconut milk as a recipe ingredient. Hard fresh chunks and dry chewy strips are not appropriate early forms."
                    )
                default:
                    practical = SolidsFoodQuestion(
                        question: "Can I use frozen or canned \(name.lowercased())?",
                        answer: "Yes, when the product has no honey before 12 months, little or no added sugar, and can be prepared to the same food-specific shape and texture. Thaw or cook firm frozen fruit and drain canned fruit as needed. Do not offer fruit juice before 12 months."
                    )
                }
            }
        case .vegetable:
            practical = SolidsFoodQuestion(
                question: "Can \(name.lowercased()) be served raw?",
                answer: vegetableRawAnswer(name: name)
            )
        case .grain:
            let texture: String
            switch grainPreparationForm(name: name) {
            case .bread:
                texture = "It should tear easily without forming a dense gummy ball. Light toasting can reduce gumminess, but avoid hard crusts, whole seeds, nut pieces, and thick sticky toppings."
            case .pasta:
                texture = "Cook it past al dente until it squashes easily. Shorten long strands, cut or mash large shapes, and add moisture if the surface becomes sticky or dry."
            case .puffedCereal:
                texture = "Test the exact product with saliva or warm water: it should dissolve readily rather than staying hard. Offer a few pieces at a time while the child is seated, not a dry handful."
            case .softGrain:
                texture = "Cook it until no hard center remains, then keep it moist and separate dense clumps. Whole kernels need mashing or another modification until the child can manage them reliably."
            }
            practical = SolidsFoodQuestion(
                question: "How should \(name.lowercased()) feel before serving?",
                answer: "\(texture) Check the package for wheat and other major allergens."
            )
        case .beanAndPlantProtein:
            let packagedGuidance: String
            switch plantProteinPreparationForm(name: name) {
            case .wholePulse:
                packagedGuidance = "Canned or frozen versions can work. Choose no-salt-added or lower-sodium products when practical, drain and rinse canned pulses, cook until the center mashes easily, and flatten whole beans or peas."
            case .softTofu, .firmTofu:
                packagedGuidance = "Choose plain tofu, check the soy allergen label and sodium, and follow refrigeration directions. Adapt the actual firmness: scoop soft tofu, or use moist strips, crumbles, or pieces of firmer tofu."
            case .fermentedCake:
                packagedGuidance = formedPlantProteinPreparation(name: name)
            case .spread:
                packagedGuidance = plantProteinSpreadPreparation(name: name)
            case .seasoning:
                packagedGuidance = plantProteinSeasoningPreparation(name: name)
            case .sprout:
                packagedGuidance = "Do not rely on rinsing to make raw sprouts safe. Cook them thoroughly until steaming hot, cool them, then chop across the stems before serving."
            }
            practical = SolidsFoodQuestion(
                question: "What should I check when preparing \(name.lowercased())?",
                answer: packagedGuidance
            )
        case .meat:
            let tenderness: String
            switch meatPreparationForm(name: name) {
            case .organ:
                tenderness = "Cook it fully but gently so it stays soft, remove membrane or tough ducts, and mash or mince it with moisture. Keep portions modest because liver is concentrated in preformed vitamin A."
            case .ground:
                tenderness = "Cook it fully and keep patties, meatballs, or crumbles moist. Break apart any rubbery or browned crust and verify that no hard fragment remains."
            case .boneIn:
                tenderness = "Cook until the meat is tender, take it completely off the bone, then check again for loose bone, cartilage, gristle, and tough skin before shredding or mincing."
            case .tenderCut:
                tenderness = "Cook it fully with a moisture-retaining method and use a boneless portion. If the cut was cooked on the bone, take the meat off and inspect it again; remove any gristle or tough connective tissue, then shred across the grain or mince it with sauce rather than serving dry cubes."
            }
            practical = SolidsFoodQuestion(
                question: "How do I keep \(name.lowercased()) tender enough?",
                answer: tenderness
            )
        case .seafood:
            let finalCheck: String
            switch seafoodPreparationForm(name: name) {
            case .crustacean:
                finalCheck = "Cook it fully, remove the entire shell and tail, then mince or flatten the curved flesh and discard rubbery sections."
            case .bivalve:
                finalCheck = "Use only fully cooked flesh, remove every shell fragment, and mince the chewy meat finely into moist food."
            case .cephalopod:
                finalCheck = "Cook it fully until tender and mince very finely. Do not offer rings, tentacles, or pieces that remain rubbery."
            case .smallFish:
                finalCheck = "Use fully cooked \(name.lowercased()), check the exact product for sodium and current fish advice, and inspect every portion for bones even when processing has softened some small bones."
            case .fillet:
                finalCheck = "Confirm the exact species against current fish advice, cook it fully, and inspect the cooked flesh carefully for fine bones before serving moist flakes."
            }
            practical = SolidsFoodQuestion(
                question: "What should I check before serving \(name.lowercased())?",
                answer: finalCheck
            )
        case .dairy:
            practical = SolidsFoodQuestion(
                question: "How does \(name.lowercased()) fit into infant feeding?",
                answer: dairySpecificPreparation(name: name)
            )
        case .egg:
            practical = SolidsFoodQuestion(
                question: "Does \(name.lowercased()) need to be fully cooked?",
                answer: normalized(name) == "egg yolk"
                    ? "Yes. Cook the yolk until safely done, then mash it with moisture so it is not dry or crumbly. Egg is a major allergen even when only the yolk is being served."
                    : "Yes. Cook the egg until safely done while keeping it soft rather than rubbery. Egg is a major allergen, so start with a small amount in an appropriate form."
            )
        case .nutAndSeed:
            practical = SolidsFoodQuestion(
                question: "What is the safe form of \(name.lowercased())?",
                answer: nutAndSeedSpecificPreparation(name: name)
            )
        case .herbAndFlavor:
            practical = SolidsFoodQuestion(
                question: "How much \(name.lowercased()) should I use?",
                answer: flavorSpecificPreparation(name: name)
            )
        case .preparedFood:
            let profile = preparedFoodEditorialProfile(name: name)
            practical = SolidsFoodQuestion(
                question: "What exactly does \(name.lowercased()) mean in this catalog?",
                answer: "It means \(profile.definition). \(profile.preparation)"
            )
        }
        return [progression, practical]
    }

    fileprivate enum VegetablePreparationForm: Equatable {
        case leafy
        case flower
        case compactBud
        case squash
        case roundKernel
        case pod
        case stalk
        case bulb
        case swollenStem
        case softFlesh
        case root
        case tuber
        case fibrousSpecialty
    }

    /// Exact edible-part and trimming rules for all bundled vegetables.
    /// These rules are intentionally separate from texture families: two
    /// vegetables that cook similarly may have very different parts to keep.
    fileprivate static func vegetableTrimmingGuidance(name: String) -> String {
        switch normalized(name) {
        case "acorn squash", "butternut squash", "hubbard squash", "kabocha squash", "pumpkin", "spaghetti squash":
            return "Wash before cutting, then remove the stem, hard rind, stringy seed cavity, and every mature seed."
        case "delicata squash":
            return "Wash the thin edible skin, remove both stem ends, split the squash, and scrape out the stringy seed cavity and mature seeds."
        case "yellow squash", "zucchini":
            return "Wash the tender edible skin and trim the stem and blossom ends; soft immature seeds can remain."
        case "winter melon":
            return "Remove the hard waxy rind and central seed cavity, including every mature seed."
        case "artichoke":
            return "Remove the tough outer leaves and fuzzy choke; use the fully cooked tender heart and soft scraped leaf pulp, not the fibrous leaf."
        case "arugula", "lettuce", "pea shoot", "watercress":
            return "Wash the leaves thoroughly and remove root ends, damaged leaves, and any stem that remains tough after cooking."
        case "beet greens", "collard greens", "kale", "mustard greens", "swiss chard", "turnip greens":
            return "Wash between the leaves and remove the thick central ribs and any woody stem before cooking."
        case "bok choy", "endive", "radicchio":
            return "Separate and wash the leaves, trim the root end, and cut away any damaged or tough base."
        case "cabbage", "green cabbage", "napa cabbage", "purple cabbage", "savoy cabbage":
            return "Remove damaged outer leaves and the dense central core, then wash the separated leaves."
        case "spinach":
            return "Wash the leaves thoroughly and remove only thick or damaged stems; tender baby-spinach stems can remain after cooking."
        case "asparagus":
            return "Snap or cut off the woody lower stalk and peel any thick, fibrous lower section."
        case "bamboo shoot":
            return "Use a properly prepared shoot, remove every tough outer sheath and fibrous base, then cook and cut across the fibers."
        case "beet":
            return "Trim the leaf stalks and long root tail, scrub well, and peel away tough or damaged skin after cooking."
        case "bell pepper", "red bell pepper":
            return "Remove the stem, white central core, pale inner ribs, and every seed; the colored flesh and tender skin are edible."
        case "bitter melon":
            return "Trim both ends, split lengthwise, and scrape out the spongy pith and mature seeds before cooking."
        case "broccoli", "broccoli rabe":
            return "Wash between the florets and leaves, trim the dry base, and peel or discard any woody lower stem."
        case "brussels sprouts":
            return "Trim the dry stem base, remove damaged outer leaves, and halve or quarter each compact bud lengthwise."
        case "cactus pad", "nopales":
            return "Remove every spine and glochid plus the tough perimeter and stem end, then rinse the de-spined pad."
        case "carrot", "daikon", "parsnip", "radish", "rutabaga", "turnip":
            return "Remove the leafy top and thin root tail, scrub well, and peel only tough, waxed, or damaged skin."
        case "cassava", "yucca root":
            return "Cut off both ends and remove the entire thick brown skin and pinkish inner peel before thorough cooking."
        case "celeriac":
            return "Cut away the leafy top, rootlets, and all knobby outer skin, keeping only clean firm interior flesh."
        case "celery":
            return "Trim the base and leafy top, wash between stalks, and peel away coarse strings from the stalk."
        case "chayote":
            return "Trim both ends, peel if the skin is tough, and remove the single flat seed if it remains firm; tender seed is edible when fully cooked."
        case "cauliflower":
            return "Remove the tough outer leaves and dry stem base, then wash between florets; the peeled tender stem is edible."
        case "corn":
            return "Remove the husk and every strand of silk, cook the cob, then cut off and mash the kernels; do not include the cob."
        case "cucumber":
            return "Trim both ends, peel waxed or tough skin, and scrape out large firm seeds; tender seedless flesh can remain raw when it squashes easily."
        case "edible fern", "fiddlehead fern":
            return "Remove papery brown scales and woody stem ends, wash repeatedly, and cook the curled shoots thoroughly."
        case "eggplant":
            return "Remove the leafy cap and stem; peel only tough skin, while the small soft interior seeds can remain after cooking."
        case "fennel bulb":
            return "Trim the root end and tough stalks, remove damaged outer layers, and cut the bulb across its fibers."
        case "french bean", "green bean", "wax bean":
            return "Trim both ends and remove any string along the seam, then split or cut the cooked pod across its fibers."
        case "garlic":
            return "Separate the clove, remove the papery skin and hard root end, and discard any green shoot that is tough."
        case "green onion", "scallion":
            return "Trim the root tuft and any wilted dark-green end, then wash between the white and green layers."
        case "hearts of palm":
            return "Use only the tender inner palm cylinder, discarding every fibrous outer layer and firm end."
        case "jicama":
            return "Remove the entire thick brown skin and fibrous layer beneath it; use only the white root flesh and cook it soft for an early eater."
        case "kohlrabi":
            return "Remove the leaf stems, root end, and thick fibrous peel, keeping only the pale interior of the swollen stem."
        case "leek":
            return "Trim the root and tough dark-green tops, separate the layers, and wash out all trapped grit."
        case "lotus root":
            return "Trim both ends, peel the outer skin, rinse the holes thoroughly, and avoid serving round cross-cut slices."
        case "malanga", "taro":
            return "Cut off the ends, peel the entire hairy or brown skin without tasting it raw, and cook the interior completely."
        case "okra":
            return "Trim the tough stem cap without opening the pod lengthwise; cook until tender, then split or chop the pod so it is not served whole."
        case "onion", "red onion", "shallot":
            return "Remove the papery skin, root plate, and dry stem end, then cook the edible layers until soft."
        case "pea":
            return "Use shelled peas, discarding the pod, and mash or flatten every cooked pea so it is not left round."
        case "potato":
            return "Scrub well, cut away sprouts, green skin, deep eyes, and damaged areas, then cook the flesh completely."
        case "snap pea":
            return "Trim both ends and pull away the tough seam string, then split the cooked pod lengthwise and flatten the peas inside."
        case "sweet potato", "yam":
            return "Scrub well, trim both ends, and peel tough or damaged skin before cooking the flesh completely."
        case "tomatillo":
            return "Remove the papery husk and stem, wash off the sticky residue, and use the cooked flesh with its small soft seeds."
        case "tomato":
            return "Remove the stem and firm stem core; the tender skin and soft seeds can remain when the ripe flesh is cut safely."
        case "water chestnut":
            return "Peel away all dark skin and trim both ends, then cook and mince the crisp white flesh rather than serving a round slice."
        default:
            preconditionFailure("Missing vegetable-specific trimming guidance for \(name)")
        }
    }

    fileprivate static func vegetablePreparationForm(name: String) -> VegetablePreparationForm {
        switch normalized(name) {
        case "arugula", "beet greens", "bok choy", "broccoli rabe", "cabbage", "collard greens", "endive", "green cabbage", "kale", "lettuce", "mustard greens", "napa cabbage", "pea shoot", "purple cabbage", "radicchio", "savoy cabbage", "spinach", "swiss chard", "turnip greens", "watercress":
            return .leafy
        case "broccoli", "cauliflower":
            return .flower
        case "brussels sprouts":
            return .compactBud
        case "acorn squash", "butternut squash", "delicata squash", "hubbard squash", "kabocha squash", "pumpkin", "spaghetti squash", "winter melon", "yellow squash", "zucchini":
            return .squash
        case "corn", "pea":
            return .roundKernel
        case "french bean", "green bean", "okra", "snap pea", "wax bean":
            return .pod
        case "asparagus", "celery":
            return .stalk
        case "fennel bulb", "garlic", "green onion", "leek", "onion", "red onion", "scallion", "shallot":
            return .bulb
        case "kohlrabi":
            return .swollenStem
        case "bell pepper", "bitter melon", "chayote", "cucumber", "eggplant", "red bell pepper", "tomatillo", "tomato":
            return .softFlesh
        case "beet", "carrot", "celeriac", "daikon", "jicama", "parsnip", "radish", "rutabaga", "turnip":
            return .root
        case "cassava", "malanga", "potato", "sweet potato", "taro", "yam", "yucca root":
            return .tuber
        case "artichoke", "bamboo shoot", "cactus pad", "edible fern", "fiddlehead fern", "hearts of palm", "lotus root", "nopales", "water chestnut":
            return .fibrousSpecialty
        default:
            preconditionFailure("Missing vegetable preparation form for \(name)")
        }
    }

    fileprivate enum PlantProteinPreparationForm: Equatable {
        case wholePulse
        case softTofu
        case firmTofu
        case fermentedCake
        case spread
        case seasoning
        case sprout
    }

    fileprivate static func plantProteinPreparationForm(name: String) -> PlantProteinPreparationForm {
        switch normalized(name) {
        case "miso", "fermented tofu":
            return .seasoning
        case "mung bean sprout", "sprouted lentil":
            return .sprout
        case "silken tofu":
            return .softTofu
        case "firm tofu", "tofu":
            return .firmTofu
        case "hummus", "refried bean":
            return .spread
        case "pea protein patty", "seitan", "tempeh":
            return .fermentedCake
        case "adzuki bean", "black bean", "black-eyed pea", "borlotti bean", "broad bean", "butter bean", "cannellini bean", "chickpea", "cranberry bean", "edamame", "fava bean", "french lentil", "garbanzo bean", "great northern bean", "green lentil", "green pea", "kidney bean", "lentil", "lima bean", "lupini bean", "moth bean", "mung bean", "navy bean", "pigeon pea", "pink bean", "pinto bean", "red bean", "red lentil", "soybean", "split pea", "white bean", "yellow lentil", "yellow split pea":
            return .wholePulse
        default:
            preconditionFailure("Missing plant-protein preparation form for \(name)")
        }
    }

    fileprivate static func formedPlantProteinPreparation(name: String) -> String {
        switch normalized(name) {
        case "pea protein patty":
            return "Cook the pea-protein patty through, keep its center moist, discard a hard seared crust, and crumble it or cut a soft strip; check the binder for wheat, soy, egg, or milk."
        case "seitan":
            return "Confirm the wheat allergen, simmer or moisten the seitan until tender, then shred across its elastic grain or mince it finely; do not offer a thick chewy cube."
        case "tempeh":
            return "Cook the tempeh through, slice it thinly across the soybean cake, keep it moist, and crumble any dense or browned edge; confirm the soy allergen and check added marinades."
        default:
            preconditionFailure("Missing formed plant-protein preparation for \(name)")
        }
    }

    fileprivate static func plantProteinSeasoningPreparation(name: String) -> String {
        switch normalized(name) {
        case "fermented tofu":
            return "Mash a very small amount of fermented tofu curd completely through a larger moist dish; do not offer a salty cube, and confirm sodium plus the soy allergen."
        case "miso":
            return "Dissolve a very small amount of miso paste evenly through a larger moist dish; do not offer a spoonful, and confirm sodium plus the soy allergen."
        default:
            preconditionFailure("Missing plant-protein seasoning preparation for \(name)")
        }
    }

    fileprivate static func plantProteinSpreadPreparation(name: String) -> String {
        switch normalized(name) {
        case "hummus":
            return "Blend until no whole chickpea or skin remains, thin any dense paste, and serve by spoon or in a thin layer; check sodium and whether the recipe contains sesame tahini."
        case "refried bean":
            return "Mash until no whole bean or tough skin remains, thin any dense paste, and serve by spoon or in a thin layer; check sodium and whether the recipe contains lard, milk, or another added ingredient."
        default:
            preconditionFailure("Missing plant-protein spread preparation for \(name)")
        }
    }

    fileprivate enum MeatPreparationForm: Equatable {
        case organ
        case ground
        case boneIn
        case tenderCut
    }

    fileprivate static func meatPreparationForm(name: String) -> MeatPreparationForm {
        switch normalized(name) {
        case "beef liver", "chicken liver", "lamb liver":
            return .organ
        case "beef meatball", "chicken meatball", "ground beef", "ground chicken", "ground lamb", "ground pork", "ground turkey", "lamb meatball", "pork meatball", "turkey meatball":
            return .ground
        case "beef short rib", "chicken drumstick", "cornish hen", "duck leg", "lamb chop", "lamb shank", "oxtail", "pork chop", "quail", "turkey leg":
            return .boneIn
        case "beef", "beef brisket", "beef cheek", "bison", "chicken", "chicken breast", "chicken thigh", "duck", "duck breast", "goat", "lamb", "moose", "pork", "pork loin", "pork shoulder", "rabbit", "roast beef", "turkey", "turkey breast", "veal", "venison":
            return .tenderCut
        default:
            preconditionFailure("Missing meat preparation form for \(name)")
        }
    }

    fileprivate enum SeafoodPreparationForm: Equatable {
        case crustacean
        case bivalve
        case cephalopod
        case smallFish
        case fillet
    }

    fileprivate static func seafoodPreparationForm(name: String) -> SeafoodPreparationForm {
        switch normalized(name) {
        case "crab", "crayfish", "langoustine", "lobster", "prawn", "shrimp":
            return .crustacean
        case "clam", "mussel", "oyster", "scallop":
            return .bivalve
        case "octopus", "squid":
            return .cephalopod
        case "anchovy", "herring", "sardine", "smelt":
            return .smallFish
        case "arctic char", "barramundi", "bass", "black cod", "bluefish", "branzino", "catfish", "cod", "croaker", "flounder", "grouper", "haddock", "hake", "halibut", "mackerel", "mahi-mahi", "milkfish", "monkfish", "mullet", "ocean perch", "perch", "pike", "pollock", "pompano", "rainbow trout", "red snapper", "rockfish", "salmon", "sea bass", "sole", "steelhead trout", "swordfish", "tilapia", "trout", "tuna", "turbot", "walleye", "whitefish", "whiting":
            return .fillet
        default:
            preconditionFailure("Missing seafood preparation form for \(name)")
        }
    }

    fileprivate enum PreparedFoodPreparationForm: Equatable {
        case soupOrStew
        case patty
        case spoonable
        case handheld
        case pastaOrRice
        case mixedDish
        case sweetener
    }

    fileprivate struct PreparedFoodEditorialProfile {
        var definition: String
        var preparation: String
    }

    /// Recipe-specific editorial facts for every prepared-food label. These
    /// define what the catalog entry means before universal supervision and
    /// food-safety language is added.
    fileprivate static func preparedFoodEditorialProfile(name: String) -> PreparedFoodEditorialProfile {
        switch normalized(name) {
        case "apple oatmeal":
            return .init(definition: "soft cooked oats with cooked or finely grated apple", preparation: "Cook the oats with enough liquid to stay scoopable, soften the apple completely, and stir the apple through without firm peel or chunks.")
        case "avocado toast":
            return .init(definition: "ripe mashed avocado spread on bread", preparation: "Use soft or lightly toasted bread that tears rather than gums, spread the avocado thinly, and cut a wide strip without hard crust.")
        case "baked potato":
            return .init(definition: "potato baked until the center is fluffy and fully cooked", preparation: "Split the potato, discard foil and any hard skin or crisp edge, moisten the flesh, and mash it or load it onto a spoon.")
        case "bean burger":
            return .init(definition: "a patty made primarily from mashed beans", preparation: "Cook the bean patty through, keep the center moist, avoid a hard seared crust, and verify the binder for wheat, egg, soy, or sesame.")
        case "bean dip":
            return .init(definition: "a smooth or mashed bean spread", preparation: "Blend until no whole bean remains, thin a dense paste, and check the recipe for sesame, dairy, soy, and sodium before serving by spoon or in a thin layer.")
        case "beef stew":
            return .init(definition: "slow-cooked beef with vegetables in a thick broth", preparation: "Cook beef until it shreds easily, remove gristle, soften every vegetable, shred the meat across the grain, and thicken or drain excess broth for spoon feeding.")
        case "broccoli fritter":
            return .init(definition: "finely chopped broccoli held in a cooked fritter", preparation: "Cook broccoli until tender before mixing, cook the fritter center through, discard crisp edges, and check the binder for egg, wheat, and dairy.")
        case "chicken soup":
            return .init(definition: "fully cooked chicken and soft vegetables in broth", preparation: "Use boneless shredded chicken, soften and cut the vegetables, shorten any noodle, check sodium, and serve a thick scoopable mixture rather than a bowl of thin hot broth.")
        case "chicken vegetable stew":
            return .init(definition: "slow-cooked chicken with vegetables in a thickened cooking liquid", preparation: "Use boneless chicken, shred it across the grain, cook each vegetable until crushable, and serve the cooled stew thick enough to stay on a spoon.")
        case "chickpea pasta":
            return .init(definition: "pasta made primarily from chickpea flour", preparation: "Cook past al dente until tender, shorten long or large shapes, add sauce or water to prevent dryness, and check the label for chickpea-only or added wheat and egg.")
        case "corn porridge":
            return .init(definition: "cornmeal cooked with liquid into a spoonable cereal", preparation: "Whisk out dry lumps, cook until the meal is fully hydrated, and thin any sticky mound so the porridge releases easily from a spoon.")
        case "egg fried rice":
            return .init(definition: "cooked rice combined with fully cooked egg and, sometimes, finely cut vegetables", preparation: "Cook the egg fully, soften the rice with moisture, break apart sticky clumps, and mash any round vegetable such as a pea; use modest sodium.")
        case "falafel":
            return .init(definition: "a chickpea or fava-bean patty commonly seasoned with herbs", preparation: "Cook the center through, discard a hard fried crust, moisten and crumble the interior, and check for sesame in tahini plus wheat in any binder or coating.")
        case "fish cake":
            return .init(definition: "a cooked patty of flaked fish with a starch or egg binder", preparation: "Inspect the fish for bones before mixing, cook the patty through, keep it tender, discard crisp edges, and check the binder for egg, wheat, and milk.")
        case "french toast":
            return .init(definition: "bread soaked in egg and usually milk, then cooked", preparation: "Cook the egg coating fully, keep the bread tender rather than crisp, avoid syrup, and cut the toast into a wide strip or soft bite-size pieces.")
        case "fruit smoothie bowl":
            return .init(definition: "blended whole fruit served thick enough to eat with a spoon", preparation: "Blend without juice, honey, or stimulant powders, keep the mixture scoopable, and omit whole fruit, granola, nut pieces, or hard seeds as toppings.")
        case "gnocchi":
            return .init(definition: "soft dumplings usually made from potato and wheat flour", preparation: "Boil until fully cooked, cut or flatten each dumpling so it is not a dense oval plug, add moisture, and check for wheat, egg, and milk.")
        case "green pea soup":
            return .init(definition: "cooked green peas blended into a thick soup", preparation: "Cook peas until soft, blend or mash every pea, choose low-sodium broth, and serve the cooled soup thick enough to stay on a spoon.")
        case "honey":
            return .init(definition: "a concentrated added sweetener that can carry botulism spores", preparation: "Do not offer any honey before 12 months; after the first birthday, mix only a small optional amount into another food.")
        case "lentil soup":
            return .init(definition: "lentils cooked with liquid and often vegetables", preparation: "Cook lentils until their centers collapse, soften every vegetable, choose low-sodium broth, and mash the soup to a thick scoopable texture.")
        case "macaroni and cheese":
            return .init(definition: "wheat macaroni coated in a milk-based cheese sauce", preparation: "Cook macaroni past firm, cut large tubes, keep the sauce moist, cool before serving, and account for the definite wheat and milk allergens.")
        case "mashed potato":
            return .init(definition: "fully cooked potato mashed with liquid and sometimes dairy", preparation: "Remove sprouts, green skin, and hard peel, cook the center fully, then mash with enough liquid to prevent a dense sticky mound; check for milk.")
        case "meat loaf":
            return .init(definition: "ground meat baked in a loaf with a binder", preparation: "Cook the center to a safe temperature, keep the slice moist, crumble or cut it into soft pieces, and check the binder for egg, wheat, milk, or soy.")
        case "millet porridge":
            return .init(definition: "millet cooked with liquid into a soft cereal", preparation: "Cook until every grain is soft, add enough liquid to prevent a dry grainy clump, and serve the porridge scoopable on a spoon.")
        case "minestrone":
            return .init(definition: "an Italian-style vegetable soup commonly containing beans and pasta", preparation: "Cook beans until mashable, soften and cut every vegetable, shorten pasta, choose low-sodium broth, and thicken the cooled serving for a spoon.")
        case "mung dal":
            return .init(definition: "split or hulled mung beans cooked into a soft pulse dish", preparation: "Cook until the mung beans collapse, thin or thicken to a scoopable consistency, and keep salt and hot chile out of the child's portion.")
        case "oat pancake":
            return .init(definition: "a tender pancake made with oats or oat flour", preparation: "Cook the center through without a hard crust, cut a soft strip, and check the recipe for egg, milk, wheat, and nut ingredients.")
        case "pasta with tomato sauce":
            return .init(definition: "cooked pasta coated with tomato sauce", preparation: "Cook pasta past firm, shorten strands or cut large shapes, use a smooth modest-sodium sauce, and keep the finished pasta moist rather than sticky.")
        case "peanut sauce":
            return .init(definition: "a sauce based on peanut butter, often with soy or sesame seasoning", preparation: "Use smooth peanut butter, thin the sauce so it cannot form a sticky mass, use modest sodium, and account for peanut plus any soy, sesame, or wheat on the label.")
        case "pumpkin soup":
            return .init(definition: "cooked pumpkin blended with liquid into a thick soup", preparation: "Remove rind and seeds, cook pumpkin until soft, blend smoothly, choose low-sodium liquid, and serve cooled and thick enough to stay on a spoon.")
        case "quesadilla":
            return .init(definition: "a tortilla folded around melted cheese and optional fillings", preparation: "Melt pasteurized cheese, soften every filling, avoid a crisp or gummy tortilla, and cut the folded quesadilla into soft manageable strips.")
        case "rice and beans":
            return .init(definition: "cooked rice mixed with cooked beans", preparation: "Cook beans until mashable and flatten them, keep rice moist, break up sticky clumps, and combine the two without a dry mouthful.")
        case "rice pudding":
            return .init(definition: "rice cooked in milk into a sweet spoon dessert", preparation: "Cook rice until very soft, keep the pudding loose and scoopable, choose pasteurized milk, omit honey before 12 months, and minimize added sugar.")
        case "risotto":
            return .init(definition: "short-grain rice slowly cooked into a creamy dish", preparation: "Cook until each grain is tender, keep the mixture loose rather than gluey, cool before serving, and check broth, cheese, and butter for sodium and milk.")
        case "salmon cake":
            return .init(definition: "a cooked patty of flaked salmon with a binder", preparation: "Inspect salmon carefully for bones, cook the patty through, keep its center tender, discard crisp edges, and check the binder for egg, wheat, and milk.")
        case "shepherd's pie":
            return .init(definition: "cooked minced meat and vegetables beneath mashed potato", preparation: "Cook meat fully and keep it moist, soften and modify every vegetable, loosen dense mashed potato, cool the center, and check for milk in the topping.")
        case "soft taco":
            return .init(definition: "a soft tortilla holding cooked fillings", preparation: "Use a soft non-gummy tortilla, shred or mash each filling, omit hard raw toppings, and cut the assembled taco into a manageable strip or open-faced pieces.")
        case "spinach pancake":
            return .init(definition: "a tender pancake containing finely chopped cooked spinach", preparation: "Cook and mince spinach, cook the pancake center through, discard a crisp edge, cut a soft strip, and check for egg, milk, and wheat.")
        case "sweet potato fritter":
            return .init(definition: "cooked sweet potato formed into a fritter with a binder", preparation: "Cook sweet potato until mashable, cook the fritter center through, avoid a fried hard crust, and check the binder for egg, wheat, or milk.")
        case "tofu scramble":
            return .init(definition: "crumbled tofu cooked into soft curds, often with vegetables or seasoning", preparation: "Keep tofu curds moist, soften and finely cut any vegetable, avoid browned rubbery pieces, and check seasoning for sodium and the soy allergen.")
        case "tomato soup":
            return .init(definition: "cooked tomato blended into soup", preparation: "Use a smooth low-sodium soup, strain tough skin or seeds when present, keep it thick enough for a spoon, and check packaged versions for milk or wheat.")
        case "turkey chili":
            return .init(definition: "ground turkey simmered with beans, tomato, and mild seasonings", preparation: "Cook turkey fully and keep it moist, mash every bean, use mild seasoning without hot chile, choose modest sodium, and serve thick rather than brothy.")
        case "vegetable curry":
            return .init(definition: "mixed vegetables cooked in a seasoned sauce", preparation: "Cook every named vegetable until soft, cut or mash round and firm pieces, use mild seasoning, and check the sauce for coconut, dairy, nuts, sesame, and sodium.")
        case "vegetable soup":
            return .init(definition: "mixed vegetables cooked in broth", preparation: "Cook each vegetable until crushable, cut or mash every round or firm piece, choose low-sodium broth, and serve a thick scoopable mixture after cooling.")
        case "waffle":
            return .init(definition: "a griddled batter food commonly made with wheat, egg, and milk", preparation: "Cook the center through, soften rather than crisp the waffle, cut a wide strip, omit syrup, and account for wheat, egg, and milk in the batter.")
        case "yogurt parfait":
            return .init(definition: "layers of yogurt and fruit, sometimes with granola", preparation: "Use pasteurized plain yogurt, mash or safely cut the fruit, omit granola and hard toppings, and serve the mixture scoopable with no honey before 12 months.")
        default:
            preconditionFailure("Missing prepared-food editorial profile for \(name)")
        }
    }

    fileprivate static func preparedFoodPreparationForm(name: String) -> PreparedFoodPreparationForm {
        switch normalized(name) {
        case "honey":
            return .sweetener
        case "beef stew", "chicken soup", "chicken vegetable stew", "green pea soup", "lentil soup", "minestrone", "mung dal", "pumpkin soup", "tomato soup", "turkey chili", "vegetable curry", "vegetable soup":
            return .soupOrStew
        case "bean burger", "broccoli fritter", "falafel", "fish cake", "meat loaf", "oat pancake", "salmon cake", "spinach pancake", "sweet potato fritter", "waffle":
            return .patty
        case "apple oatmeal", "bean dip", "corn porridge", "fruit smoothie bowl", "mashed potato", "millet porridge", "peanut sauce", "rice pudding", "yogurt parfait":
            return .spoonable
        case "avocado toast", "french toast", "quesadilla", "soft taco":
            return .handheld
        case "chickpea pasta", "egg fried rice", "gnocchi", "macaroni and cheese", "pasta with tomato sauce", "rice and beans", "risotto":
            return .pastaOrRice
        case "baked potato", "shepherd's pie", "tofu scramble":
            return .mixedDish
        default:
            preconditionFailure("Missing prepared-food serving form for \(name)")
        }
    }

    private static func vegetableRawAnswer(name: String) -> String {
        let form = vegetablePreparationForm(name: name)
        switch form {
        case .softFlesh:
            return "Some ripe \(name.lowercased()) can be served raw after its stem and any tough peel or hard seed are removed. Use a soft slice or manageable piece rather than small slippery cubes, and cook it first if the flesh does not squash easily."
        case .leafy:
            return "Cook \(name.lowercased()) for a new eater, then chop across leaves and stems and mix it into moist food. Large raw leaves and fibrous stems can be difficult to manage."
        case .tuber, .fibrousSpecialty:
            return "No. \(name) requires proper trimming and thorough cooking before it is served to a young child. Do not rely on cutting a raw piece smaller to make a hard or naturally irritating food safe."
        case .bulb:
            return "Cook \(name.lowercased()) until soft for an early eater and mix it into moist food. Firm raw chunks or large slippery layers are difficult to manage and can have an intense flavor."
        case .swollenStem:
            return "Cook \(name.lowercased()) until the trimmed pale interior crushes easily for an early eater. Later, a very thin raw shred can be considered only when the child reliably manages crisp textures."
        case .pod:
            return "Cook \(name.lowercased()) until soft, remove strings or tough seams, and split or chop it. A firm intact raw pod is not an appropriate early shape."
        case .roundKernel, .compactBud:
            return "Cook \(name.lowercased()) until soft, then mash, flatten, halve, or quarter it so it does not retain a small round shape."
        case .stalk:
            return "Cook \(name.lowercased()) until tender, trim woody ends and strings, and cut across the fibers. Raw fibrous sections can remain difficult to break down."
        case .flower, .squash, .root:
            return "Cook \(name.lowercased()) until the thickest part crushes easily for an early eater. Do not serve a hard raw chunk; use a specifically recommended fine-grated preparation only when the ingredient guidance calls for it."
        }
    }

    private static func preparations(
        name: String,
        category: SolidsFoodCategory,
        minimumAge: Int
    ) -> [SolidsPreparationStage] {
        if minimumAge >= 12 {
            return [
                SolidsPreparationStage(minimumAgeMonths: 12, title: "12+ months", instructions: "\(name): use only after 12 months. Mix a small amount into food rather than serving from a spoon or container."),
                SolidsPreparationStage(minimumAgeMonths: 18, title: "18+ months", instructions: "Serve a small amount of \(name.lowercased()) as part of a balanced meal and continue normal tooth-brushing routines.")
            ]
        }

        if normalized(name) == "acai" {
            return preparationStages(
                name: name,
                six: "Use unsweetened commercially prepared frozen pulp or powder rather than a fresh whole berry. Thaw pulp and offer the smooth purée on a preloaded spoon, or stir pulp or powder into porridge or plain yogurt.",
                nine: "Keep serving it as pulp or purée as eating skills develop. Offer a thicker scoopable mixture on a preloaded spoon so the child can practice self-feeding.",
                twelve: "Serve the pulp or purée in a scoopable bowl with a child-size spoon. Skip honey and hard or chewy bowl toppings, and continue to avoid whole fresh açaí berries and their large seeds.",
                eighteen: "Offer pulp or purée in a bowl, frozen into a pop, or blended into a smoothie. Choose unsweetened products and keep toppings soft and appropriately cut."
            )
        }

        if category == .fruit {
            return fruitPreparations(name: name)
        }

        if category == .preparedFood {
            return preparedFoodPreparations(name: name)
        }

        if category == .dairy && normalized(name).contains("in food") {
            return milkIngredientPreparations(name: name)
        }

        if category == .beanAndPlantProtein {
            return plantProteinPreparations(name: name)
        }

        if category == .nutAndSeed {
            return nutAndSeedPreparations(name: name)
        }

        if let scoopable = scoopablePreparations(name: name, category: category) {
            return scoopable
        }

        switch category {
        case .fruit:
            return fruitPreparations(name: name)
        case .vegetable:
            return vegetablePreparations(name: name)
        case .grain:
            return grainPreparations(name: name)
        case .beanAndPlantProtein:
            return plantProteinPreparations(name: name)
        case .meat:
            return meatPreparations(name: name)
        case .seafood:
            return seafoodPreparations(name: name)
        case .dairy:
            return cheesePreparations(name: name)
        case .egg:
            return eggPreparations(name: name)
        case .nutAndSeed:
            return nutAndSeedPreparations(name: name)
        case .herbAndFlavor:
            return flavorPreparations(name: name)
        case .preparedFood:
            return preparedFoodPreparations(name: name)
        }
    }

    private static func preparationStages(
        name: String,
        six: String,
        nine: String,
        twelve: String,
        eighteen: String
    ) -> [SolidsPreparationStage] {
        [
            SolidsPreparationStage(minimumAgeMonths: 6, title: "Around 6 months", instructions: "\(name): \(six)"),
            SolidsPreparationStage(minimumAgeMonths: 9, title: "Around 9 months", instructions: "\(name): \(nine)"),
            SolidsPreparationStage(minimumAgeMonths: 12, title: "12+ months", instructions: "\(name): \(twelve)"),
            SolidsPreparationStage(minimumAgeMonths: 18, title: "18+ months", instructions: "\(name): \(eighteen)")
        ]
    }

    fileprivate enum FruitPreparationForm: Equatable {
        case sauce
        case smallRoundBerry
        case aggregateBerry
        case roundOrSlipperyFruit
        case citrus
        case firmFruit
        case stoneFruit
        case melon
        case softFruit
        case seededPulp
        case arils
        case driedStickyFruit
        case gratedFlesh
        case cookBeforeServing
    }

    /// Exact trimming for every fruit in the bundled catalog. Keeping this
    /// exhaustive prevents a broad fruit template from inventing a core,
    /// pit, seed, rind, or stem that the named food does not have.
    fileprivate static func fruitTrimmingGuidance(name: String) -> String {
        switch normalized(name) {
        case "acai":
            return "Use commercially prepared deseeded pulp, purée, or powder; do not use a whole fresh açaí berry."
        case "apple", "asian pear", "crab apple", "pear":
            return "Remove the stem, blossom end, seed-containing core, and any damaged skin."
        case "applesauce":
            return "No produce trimming is needed; stir the sauce and check that it contains no peel or hard fruit fragment."
        case "apricot", "nectarine", "peach", "plum", "sour cherry":
            return "Remove the stem and the entire central pit; use only the ripe flesh."
        case "cherry":
            return "Remove the stem and the entire cherry pit, then cut the flesh so it is not round."
        case "avocado":
            return "Remove the skin and the single large pit; use only flesh that mashes with light pressure."
        case "banana":
            return "Remove the peel and any loose fibrous strings; trim the firm stem end and use only soft ripe flesh."
        case "black raspberry", "blackberry", "boysenberry", "cloudberry", "huckleberry", "loganberry", "marionberry", "raspberry":
            return "Remove any attached stem or leaf and discard berries that are moldy, underripe, or firm."
        case "strawberry":
            return "Remove the leafy cap and firm white shoulder, then use ripe flesh that crushes easily."
        case "mulberry":
            return "Remove the small attached stem and discard any berry that is underripe or firm."
        case "blueberry", "cranberry":
            return "Discard any attached stem and any berry that is shriveled, split, moldy, or still firm after cooking."
        case "blackcurrant", "currant", "redcurrant", "white currant":
            return "Strip each currant from its stalk and discard any dried blossom debris or damaged berry."
        case "gooseberry":
            return "Remove the stem and dried blossom tail from each gooseberry before cooking or crushing it."
        case "cape gooseberry":
            return "Remove the papery husk and stem, wash the berry, and discard any fruit that remains firm or green."
        case "grape":
            return "Remove the stem, then quarter the grape lengthwise so no whole round shape remains; remove any firm seed."
        case "blood orange", "clementine", "grapefruit", "mandarin", "orange", "pomelo", "satsuma", "tangerine", "ugli fruit":
            return "Remove the peel, excess pith, every seed, and the tough membrane surrounding each segment."
        case "kumquat":
            return "Remove the small stem nub and every seed; slice the washed fruit lengthwise so it is not round."
        case "lemon", "lime":
            return "Remove the peel, pith, membrane, and every seed; use a small amount of pulp or juice within food rather than a whole segment."
        case "finger lime":
            return "Cut open the washed fruit, squeeze out the juice vesicles, and remove every firm seed and all peel."
        case "cactus pear", "prickly pear":
            return "Remove every spine and hair-like glochid, peel away the entire outer skin, then press the flesh through a fine mesh to remove its numerous hard seeds for an early eater."
        case "cantaloupe", "honeydew melon", "watermelon":
            return "Wash the rind before cutting, then remove all rind and every hard seed from the soft flesh."
        case "atemoya", "cherimoya":
            return "Remove the skin, stem, and every glossy dark seed; the seeds are not edible."
        case "breadfruit":
            return "Remove the stem, peel, and firm central core, then cook the starchy flesh completely."
        case "coconut flesh":
            return "Keep every shell fragment and hard brown husk out of the flesh, then grate the white flesh finely."
        case "date":
            return "Open the date and remove its single long pit before softening the sticky flesh."
        case "dragon fruit":
            return "Remove the thick pink or yellow peel; the tiny soft black seeds can remain in the ripe flesh."
        case "durian":
            return "Open the spiny husk away from the serving area and remove every large seed; use only the soft flesh around each seed."
        case "elderberry":
            return "Strip the berries from every stem and cook them thoroughly; do not include leaves, twigs, or green unripe berries."
        case "feijoa":
            return "Remove the stem and blossom ends, then scoop or slice the ripe aromatic flesh; peel if the skin is tough."
        case "fig":
            return "Remove the firm stem and use a fully ripe fig; the tiny interior seeds do not need removal."
        case "guava":
            return "Remove the stem and blossom ends; cook or strain the seed-rich center when its seeds remain hard."
        case "jackfruit":
            return "Remove the spiky rind, sticky fibrous core, and every large seed; use only the ripe edible pods."
        case "jujube":
            return "Remove the stem and single hard stone, then cook firm fresh flesh until soft."
        case "kiwi":
            return "Remove the firm stem end and peel the fuzzy skin for an early eater; the tiny soft black seeds can remain."
        case "longan", "lychee", "rambutan":
            return "Remove the outer shell or peel and the single large seed; cut the slippery translucent flesh lengthwise."
        case "loquat":
            return "Remove the stem, blossom end, peel if tough, and every large brown seed."
        case "mango":
            return "Remove the skin and cut all flesh away from the wide flat stone."
        case "mangosteen":
            return "Remove the thick purple rind and any large firm seed; use only the soft white segments."
        case "papaya":
            return "Remove the skin and scrape out every black seed from the center cavity."
        case "passion fruit":
            return "Keep the rind out of the serving and offer the soft seedy pulp by spoon; strain it if any seed feels unexpectedly hard."
        case "pawpaw":
            return "Remove the skin and every large dark seed; use only soft ripe flesh."
        case "persimmon":
            return "Remove the leafy calyx and any seed; use only fully ripe flesh that is not astringent or firm."
        case "pineapple":
            return "Remove the crown, tough peel, eyes, and fibrous central core; use only tender ripe flesh."
        case "plantain":
            return "Cut away both ends, remove the thick peel, and cook the firm starchy flesh completely."
        case "pomegranate":
            return "Separate the arils completely from the leathery rind and bitter white membrane."
        case "prune":
            return "Confirm the prune is pitted, open it to check again, and soften the dense sticky flesh."
        case "quince":
            return "Remove the stem, fuzzy surface coating, seed-containing core, and any tough peel, then cook the flesh completely."
        case "sapodilla":
            return "Remove the skin and every shiny black seed, including its hooked tip; use only very ripe soft flesh."
        case "star fruit":
            return "Remove the stem end, any browned ridge edges, and every firm seed, then slice across the washed fruit."
        case "tamarillo":
            return "Remove the stem and bitter skin; scoop out or mash the ripe seed-filled pulp."
        default:
            preconditionFailure("Missing fruit-specific trimming guidance for \(name)")
        }
    }

    private static func fruitPreparations(name: String) -> [SolidsPreparationStage] {
        if ["cactus pear", "prickly pear"].contains(normalized(name)) {
            return preparationStages(
                name: name,
                six: "Use commercially de-spined fruit when possible. Remove every spine and hair-like glochid, peel away the entire outer skin, then press the ripe flesh through a fine mesh to remove its numerous hard seeds before offering the pulp by spoon.",
                nine: "After complete de-spining and peeling, strain out the hard seeds and offer the ripe pulp by spoon. Check the work surface and fruit again for hair-like glochids.",
                twelve: "Serve strained ripe pulp by spoon only after every spine, glochid, skin section, and hard seed is removed.",
                eighteen: "Continue removing every spine, glochid, the full outer skin, and the numerous hard seeds before offering the soft pulp."
            )
        }
        let trim = fruitTrimmingGuidance(name: name)
        switch fruitPreparationForm(name: name) {
        case .sauce:
            return preparationStages(
                name: name,
                six: "Choose an unsweetened smooth sauce. Offer it on a preloaded spoon or stir it into porridge; it should be thick enough to stay on the spoon.",
                nine: "Offer a thicker, slightly textured sauce on a preloaded spoon and let the child practice scooping. This remains a spoon food rather than becoming slices or wedges.",
                twelve: "Serve in a small bowl for independent spoon practice. Check the ingredient list for added sugar and keep the texture moist.",
                eighteen: "Offer by spoon, use as a soft dip, or mix into another food. Keep portions scoopable rather than using squeeze pouches as the usual way to eat it."
            )
        case .smallRoundBerry:
            return preparationStages(
                name: name,
                six: "\(trim) Cook if firm, then crush each berry completely so it no longer holds a small round shape; mix the mash into a scoopable food if helpful.",
                nine: "Flatten each ripe berry firmly between your fingers or quarter larger berries lengthwise. Do not serve firm berries whole and round.",
                twelve: "Continue flattening or quartering until chewing skills are reliable. Very soft berries can be offered with a child-size fork or spoon.",
                eighteen: "Serve ripe berries flattened or cut when their round shape or firmness could still block the airway. Progress based on chewing skill, not age alone."
            )
        case .aggregateBerry:
            return preparationStages(
                name: name,
                six: "\(trim) Mash or gently flatten the ripe berry, tearing a large berry into soft sections when needed.",
                nine: "Offer ripe berries flattened or torn into small soft sections for pincer-grasp practice.",
                twelve: "Serve ripe whole berries only when they are soft and collapse easily; otherwise flatten or cut them. A child-size fork can help with slippery fruit.",
                eighteen: "Offer ripe berries whole or cut to match their size and firmness, repeating the named trimming check before serving."
            )
        case .roundOrSlipperyFruit:
            return preparationStages(
                name: name,
                six: "\(trim) Mash the ripe flesh or cut it lengthwise into quarters so no whole round shape remains.",
                nine: "Repeat the trimming check, then quarter the fruit lengthwise or cut the slippery flesh into small soft pieces. Never serve it whole and round.",
                twelve: "Continue cutting the prepared flesh lengthwise and use a fork for slippery pieces if helpful.",
                eighteen: "Cut lengthwise into narrow quarters or smaller pieces until the child can safely manage the fruit's round, slippery form."
            )
        case .citrus:
            return preparationStages(
                name: name,
                six: "\(trim) Offer the juicy pulp on a spoon or as a manageable membrane-free piece, checking again for membrane strands before serving.",
                nine: "Remove peel, seeds, and tough membrane, then cut juicy segments into small soft pieces. A preloaded fork can make slippery pulp easier to manage.",
                twelve: "Offer membrane-free segments or small pieces and model biting and chewing. Continue removing seeds and any tough center pith.",
                eighteen: "Serve peeled segments or bite-size pieces, removing seeds and tough membrane when the child cannot yet manage them."
            )
        case .firmFruit:
            return preparationStages(
                name: name,
                six: "\(trim) Steam or bake until the edible flesh collapses under gentle finger pressure, then mash, finely grate, or offer a large cooked section.",
                nine: "Continue cooking until tender, then offer thin slices or small soft pieces. Raw chunks remain too hard; finely grated raw fruit may be mixed into a moist food.",
                twelve: "Offer thin slices of ripe fruit or cooked bite-size pieces. If the fruit is still crisp or hard, cook or grate it rather than serving chunks.",
                eighteen: "Adjust between thin raw slices, grated fruit, and cooked pieces according to firmness and the child's chewing skills, repeating the complete trimming check."
            )
        case .stoneFruit:
            return preparationStages(
                name: name,
                six: "\(trim) Offer the very ripe flesh mashed or as a large soft wedge that squishes easily.",
                nine: "Remove the pit, then cut ripe flesh into thin soft slices or small pieces. Roll slippery pieces in finely ground food if a little grip is needed.",
                twelve: "Serve ripe slices or bite-size pieces after removing the pit. Cook the fruit first if the flesh is still firm.",
                eighteen: "Offer ripe slices or pieces and continue removing the pit and any tough skin."
            )
        case .melon:
            return preparationStages(
                name: name,
                six: "\(trim) Offer a broad soft slab or mash; the flesh should yield easily and should not be cut into small slippery cubes.",
                nine: "Remove rind and seeds and cut the soft flesh into thin sticks or small pieces for pincer-grasp practice.",
                twelve: "Offer bite-size soft pieces or thin slices with no rind or seeds. Use a fork if the fruit is very slippery.",
                eighteen: "Serve soft pieces or slices, continuing to remove rind and hard seeds."
            )
        case .softFruit:
            return preparationStages(
                name: name,
                six: "\(trim) Offer the very ripe flesh mashed or as a large soft section that squishes easily between two fingers.",
                nine: "Repeat the trimming check, then serve ripe flesh in small soft pieces or thin slices. Add grip to slippery fruit when helpful.",
                twelve: "Offer ripe bite-size pieces with a child-size fork or fingers. Cook first if the flesh is still firm.",
                eighteen: "Serve ripe pieces or slices sized to the child's chewing skills after repeating the complete trimming check."
            )
        case .seededPulp:
            return preparationStages(
                name: name,
                six: "\(trim) Mash the prepared pulp and offer a small amount by spoon or stir it into plain yogurt or porridge.",
                nine: "Serve the soft pulp on a preloaded spoon or mixed into a scoopable food. This is a pulp food, not a sliced finger food.",
                twelve: "Offer the pulp in a bowl with a child-size spoon. Keep the rind out of reach and remove any large, hard, or unexpectedly firm seed.",
                eighteen: "Serve the pulp by spoon, as a soft topping, or mixed into another food; discard the rind and any hard seed."
            )
        case .arils:
            return preparationStages(
                name: name,
                six: "\(trim) Crush the prepared arils thoroughly to release the juice, then stir them into a scoopable food; do not offer intact arils.",
                nine: "Flatten or crush every aril before serving, or press the fruit through a strainer and mix the pulp and juice into food.",
                twelve: "Continue crushing or flattening arils until the child can manage their firm, round shape. Offer with a spoon rather than by the handful.",
                eighteen: "Offer arils only when their firmness has been modified for the child's chewing skills; supervise and avoid large mouthfuls."
            )
        case .driedStickyFruit:
            return preparationStages(
                name: name,
                six: "\(trim) Simmer or soak until very soft, then purée with liquid and offer by spoon or spread a thin layer on soft food; never serve it whole and sticky.",
                nine: "Remove the pit and soften well, then mash or finely mince and mix into a moist food. Avoid dense sticky lumps.",
                twelve: "Serve softened fruit finely chopped in a moist dish or as a thin spread. Continue avoiding whole sticky fruit.",
                eighteen: "Remove the pit and cut softened fruit into small pieces, separating sticky pieces so they cannot form a large mouthful."
            )
        case .gratedFlesh:
            return preparationStages(
                name: name,
                six: "\(trim) Mix the finely grated flesh into a moist food, or use smooth coconut milk in cooking. Do not offer a hard chunk of fresh flesh.",
                nine: "Finely grate or mince the flesh and stir it into a moist food. Avoid dry flakes and hard, chewy strips.",
                twelve: "Offer finely grated flesh in a moist dish or use coconut milk in cooking; hard chunks remain difficult to chew.",
                eighteen: "Serve finely grated or very thin soft pieces according to chewing skill, avoiding hard chunks and dry mouthfuls."
            )
        case .cookBeforeServing:
            return preparationStages(
                name: name,
                six: "\(trim) Cook thoroughly until the edible flesh is very soft, then mash or offer a large soft section; do not serve it raw and firm.",
                nine: "Repeat the trimming check and cook until tender, then offer soft strips or small pieces.",
                twelve: "Serve fully cooked bite-size pieces or mash into a dish. Check each piece for firmness before offering.",
                eighteen: "Use fully cooked pieces suited to the child's chewing skills after repeating the complete trimming check."
            )
        }
    }

    fileprivate static func fruitPreparationForm(name: String) -> FruitPreparationForm {
        switch normalized(name) {
        case "applesauce":
            return .sauce
        case "coconut flesh":
            return .gratedFlesh
        case "pomegranate":
            return .arils
        case "finger lime", "passion fruit":
            return .seededPulp
        case "date", "prune":
            return .driedStickyFruit
        case "breadfruit", "elderberry", "plantain", "quince":
            return .cookBeforeServing
        case "cape gooseberry", "cherry", "grape", "kumquat", "longan", "lychee", "rambutan", "sour cherry":
            return .roundOrSlipperyFruit
        case "blackcurrant", "blueberry", "cranberry", "currant", "gooseberry", "huckleberry", "redcurrant", "white currant":
            return .smallRoundBerry
        case "black raspberry", "blackberry", "boysenberry", "cloudberry", "loganberry", "marionberry", "mulberry", "raspberry", "strawberry":
            return .aggregateBerry
        case "blood orange", "clementine", "grapefruit", "lemon", "lime", "mandarin", "orange", "pomelo", "satsuma", "tangerine", "ugli fruit":
            return .citrus
        case "apple", "asian pear", "crab apple", "pear":
            return .firmFruit
        case "apricot", "avocado", "jujube", "mango", "nectarine", "peach", "plum":
            return .stoneFruit
        case "cantaloupe", "honeydew melon", "watermelon":
            return .melon
        case "acai", "atemoya", "banana", "cactus pear", "cherimoya", "dragon fruit", "durian", "feijoa", "fig", "guava", "jackfruit", "kiwi", "loquat", "mangosteen", "papaya", "pawpaw", "persimmon", "pineapple", "prickly pear", "sapodilla", "star fruit", "tamarillo":
            return .softFruit
        default:
            preconditionFailure("Missing fruit preparation form for \(name)")
        }
    }

    private static func vegetablePreparations(name: String) -> [SolidsPreparationStage] {
        let trim = vegetableTrimmingGuidance(name: name)
        switch vegetablePreparationForm(name: name) {
        case .leafy:
            return preparationStages(
                name: name,
                six: "Wash thoroughly, remove tough stems, and cook until the leaves collapse. Mince across the fibers and mix into a moist scoopable food; do not offer a wad of loose leaves.",
                nine: "Cook until tender, chop leaves and stems finely across the grain, and mix into a soft dish or omelet. Separate any stringy clump.",
                twelve: "Offer finely chopped cooked leaves in moist food or on a child-size fork. Raw leaves should be very tender, finely cut, and introduced according to chewing skill.",
                eighteen: "Add chopped leaves to family meals, continuing to cook or finely cut thick stems and any leaf that remains fibrous."
            )
        case .flower:
            return preparationStages(
                name: name,
                six: "Steam or roast until the thickest stem crushes easily. Offer a large soft floret with a long handle, or mash the tender flower and stem; remove any woody outer leaf.",
                nine: "Cook until very soft and offer small florets or chopped tender stem. Press firm round flower buds flat and avoid dry crumbly mouthfuls.",
                twelve: "Serve bite-size soft florets and thin pieces of tender stem with a fork. Cook longer if the branch points remain firm.",
                eighteen: "Offer tender florets and stems in family dishes, checking that crisp or roasted edges have not become hard."
            )
        case .compactBud:
            return preparationStages(
                name: name,
                six: "Steam or braise until the dense center crushes easily, then halve or quarter lengthwise and mash or flatten the rounded layers. Do not serve a whole bud.",
                nine: "Cook until very soft and quarter lengthwise into small pieces, pressing each piece so no firm round center remains.",
                twelve: "Offer bite-size soft quarters or chopped leaves with a fork. Continue checking the center, which can stay firm after outer leaves soften.",
                eighteen: "Serve tender halves, quarters, or chopped pieces, avoiding whole round buds and hard roasted outer leaves."
            )
        case .squash:
            return preparationStages(
                name: name,
                six: "\(trim) Roast or steam until the edible flesh collapses under finger pressure, then offer a thick soft crescent or mash on a preloaded spoon.",
                nine: "Serve peeled, fully cooked strips or small soft pieces. Check that no hard rind or flat seed remains and add moisture if the flesh is dry.",
                twelve: "Offer bite-size cooked pieces or mash with a fork. Thin tender skin may be left only when the child can manage it; discard hard rind.",
                eighteen: "Serve soft cooked pieces in family meals, continuing to remove hard rind, stem, and seeds and to moisten dry varieties."
            )
        case .roundKernel:
            return preparationStages(
                name: name,
                six: "Cook until very soft, then mash every kernel or pea so no intact round shape remains. Mix the mash into another moist food or load it onto a spoon.",
                nine: "Cook until soft and flatten each kernel or pea before offering for pincer practice. For corn, a short tender cob section can be used for supervised mouthing while loose kernels stay mashed.",
                twelve: "Serve soft kernels or peas after pressing them flat, or mix them through a moist dish. Avoid hard, dry, or frozen pieces.",
                eighteen: "Progress toward soft whole pieces only as chewing skills become reliable; continue flattening any firm, round kernel or pea."
            )
        case .pod:
            return preparationStages(
                name: name,
                six: "Trim the stem, strings, and pointed end, split the pod lengthwise, and cook until it folds and crushes easily. Offer a long soft half or mash the pod and seeds.",
                nine: "Cook until tender, remove strings, and cut lengthwise into narrow soft strips or small pieces. Flatten any round seed inside.",
                twelve: "Offer tender chopped pod pieces with a fork, continuing to split thick pods and remove tough seams or strings.",
                eighteen: "Serve fully cooked pod pieces in family meals; avoid firm raw pods and continue trimming strings and hard ends."
            )
        case .stalk:
            return preparationStages(
                name: name,
                six: "Trim the woody base and strings, then cook until the thickest part squashes easily. Offer a long soft stalk or mince across the fibers into moist food.",
                nine: "Cook until tender and cut lengthwise or across the fibers into small soft pieces. Peel or discard any tough outer layer.",
                twelve: "Serve tender bite-size pieces with a fork. Raw versions should wait until the child can manage the ingredient's fibers and firmness.",
                eighteen: "Offer cooked or appropriately thin pieces, continuing to remove woody ends, strings, and tough outer layers."
            )
        case .bulb:
            return preparationStages(
                name: name,
                six: "Peel and cook until the layers are completely soft, then finely mince or mash a small amount into another food. Avoid a slippery intact layer or firm raw chunk.",
                nine: "Cook until tender and chop across the layers into small pieces, mixing them through a moist dish rather than offering a loose mouthful.",
                twelve: "Use soft cooked pieces to flavor family food. Very thin raw mince can be explored when tolerated, but large raw pieces remain firm and intense.",
                eighteen: "Serve cooked pieces in family meals and cut raw forms finely according to chewing skill and tolerance."
            )
        case .swollenStem:
            return preparationStages(
                name: name,
                six: "\(trim) Cook the pale interior until it crushes easily, then mash it with moisture or offer a broad soft spear.",
                nine: "Repeat the complete peel and trim, cook until tender, and offer narrow soft sticks or small pieces.",
                twelve: "Serve bite-size cooked pieces or very thin shreds, checking that no fibrous peel remains.",
                eighteen: "Offer tender cooked pieces or very thin raw shreds only when crisp chewing skills are established; never serve a hard cube."
            )
        case .softFlesh:
            return preparationStages(
                name: name,
                six: "\(trim) Cook until soft, then offer a broad spear that squishes easily or mash the edible flesh; avoid small slippery cubes.",
                nine: "Serve ripe or cooked flesh in thin strips or small soft pieces. Flatten round sections and peel away any skin that separates into a tough sheet.",
                twelve: "Offer bite-size soft pieces with a fork or fingers, continuing to remove hard seeds, stem, and tough skin.",
                eighteen: "Serve raw or cooked pieces according to actual firmness, modifying round shapes and removing any tough peel, stem, or seed."
            )
        case .root:
            return preparationStages(
                name: name,
                six: "\(trim) Steam, roast, or boil until the center crushes easily, then offer a thick soft spear or mash; use a finely grated raw form only when the named vegetable is normally eaten raw.",
                nine: "Cook until tender and cut into narrow sticks or small soft pieces. Finely grated raw root can be mixed into moist food when the particular root is eaten raw.",
                twelve: "Serve bite-size cooked pieces or very thin shreds. Continue cooking any crisp variety and avoid firm coin shapes.",
                eighteen: "Progress to thin raw or cooked pieces based on the root's actual hardness and the child's chewing skills, never by age alone."
            )
        case .tuber:
            let extra = tuberSafetyDetail(name: name)
            return preparationStages(
                name: name,
                six: "\(trim) Cook all the way through until the center is soft and no raw firmness remains. \(extra) Mash with moisture or offer a thick soft spear without crisp edges.",
                nine: "Serve fully cooked small soft pieces, strips, or a moist mash. Break up dense sticky clumps and remove tough peel.",
                twelve: "Offer bite-size cooked pieces or a fork-mashed portion. Avoid undercooked centers, dry mouthfuls, and hard fried crusts.",
                eighteen: "Serve fully cooked pieces in family meals, keeping dense flesh moist and following the ingredient's specific peeling and cooking requirements."
            )
        case .fibrousSpecialty:
            return fibrousSpecialtyPreparations(name: name)
        }
    }

    private static func fibrousSpecialtyPreparations(name: String) -> [SolidsPreparationStage] {
        let key = normalized(name)
        if key == "artichoke" {
            return preparationStages(
                name: name,
                six: "Cook until the heart is completely tender, remove the choke and every tough outer leaf, then mash the heart with moisture. If using a leaf for flavor exploration, offer only the soft scraped pulp—not the fibrous leaf itself.",
                nine: "Finely chop or mash the fully cooked heart into moist food. Keep the choke, stem fibers, and whole leaves out of the serving.",
                twelve: "Offer small tender pieces of cooked heart with a fork. Continue removing the fuzzy choke and every tough leaf or stem fiber.",
                eighteen: "Serve tender chopped heart or model scraping soft pulp from a leaf while directly supervising; the fibrous leaf is discarded rather than swallowed."
            )
        }
        if ["bamboo shoot", "lotus root", "water chestnut"].contains(key) {
            return preparationStages(
                name: name,
                six: "Use a properly prepared product, cook thoroughly, then finely grate, purée, or mince it across the fibers into moist food. Do not offer a crisp slice or chunk.",
                nine: "Cook fully and continue grating or mincing into very small pieces mixed through a soft dish; this ingredient may stay crisp even after cooking.",
                twelve: "Offer finely chopped cooked pieces in a moist meal only when each piece is manageable. Avoid round slices and any piece that still snaps or resists chewing.",
                eighteen: "Progress cautiously to very thin, finely cut cooked pieces according to chewing skill; continue avoiding crisp rounds and chunks."
            )
        }
        if key.contains("fern") {
            return preparationStages(
                name: name,
                six: "Clean and cook thoroughly according to fern food-safety guidance, discard the cooking water, then finely mince the tender shoot into moist food. Never serve it raw or lightly cooked.",
                nine: "After thorough cooking, chop across the curled shoot and stem into small soft pieces and recheck for fibrous sections.",
                twelve: "Offer fully cooked finely chopped pieces in a moist dish. Continue excluding raw, pickled-only, or undercooked shoots.",
                eighteen: "Serve thoroughly cooked chopped pieces as part of a meal, removing any stem section that remains fibrous."
            )
        }
        if ["cactus pad", "nopales"].contains(key) {
            return preparationStages(
                name: name,
                six: "Remove every spine and hair-like glochid plus the tough perimeter and stem end. Cook until the de-spined pad is tender, then mince across the fibers or offer a long soft strip.",
                nine: "After another spine check, cook fully and cut the tender pad across its fibers into narrow strips or small soft pieces.",
                twelve: "Offer finely chopped tender pad in a moist dish, discarding any section that remains stringy.",
                eighteen: "Serve fully cooked tender pieces only after confirming that no spine, glochid, tough edge, or firm end remains."
            )
        }
        if key == "hearts of palm" {
            return preparationStages(
                name: name,
                six: "Use only the tender inner cylinder, cook it until soft, then mince across the fibers into moist food; discard every fibrous outer layer and firm end.",
                nine: "Cook until tender and cut the inner palm lengthwise into narrow soft strips or very small pieces that break apart easily.",
                twelve: "Offer finely chopped tender pieces in a moist dish, mincing any section that remains stringy.",
                eighteen: "Serve tender cooked inner palm cut across the fibers, continuing to discard firm ends and fibrous outer layers."
            )
        }
        preconditionFailure("Missing fibrous-specialty preparation for \(name)")
    }

    private static func tuberSafetyDetail(name: String) -> String {
        switch normalized(name) {
        case "cassava", "yucca root":
            return "Never serve it raw; peel and cook it properly because raw or improperly processed cassava contains naturally occurring cyanogenic compounds."
        case "malanga", "taro":
            return "Never serve it raw; thorough cooking reduces naturally occurring calcium oxalate crystals that can irritate the mouth and throat."
        case "potato":
            return "Cut away every sprout, green area, and damaged section, and do not use a potato that tastes bitter."
        case "sweet potato", "yam":
            return "Cook the dense flesh completely and add moisture if it becomes dry or sticky."
        default:
            preconditionFailure("Missing tuber safety detail for \(name)")
        }
    }

    private static func plantProteinPreparations(name: String) -> [SolidsPreparationStage] {
        switch plantProteinPreparationForm(name: name) {
        case .wholePulse:
            return preparationStages(
                name: name,
                six: "Cook until the center mashes easily, remove any debris, then mash or blend with liquid. Crush every bean or pea so it no longer retains a firm round shape.",
                nine: "Offer soft beans or pulses flattened one by one, mashed on a preloaded spoon, or formed into a tender patty. Remove any skin that separates and stays tough.",
                twelve: "Serve very soft pieces in a moist dish, flattening larger or firmer beans. Avoid dry handfuls and undercooked centers.",
                eighteen: "Progress toward soft whole pulses according to chewing skill, continuing to mash or flatten any firm round piece and keeping the dish moist."
            )
        case .softTofu:
            return preparationStages(
                name: name,
                six: "Use a plain pasteurized product, scoop it directly onto a preloaded spoon, or mash it into another food. Its custard texture does not need to become a strip.",
                nine: "Offer soft spoonfuls or small scoopable pieces for finger and utensil practice. Drain excess liquid but do not make the tofu dry.",
                twelve: "Serve by spoon or as very soft bite-size scoops mixed into a meal. Check sauces and seasonings for sodium and allergens.",
                eighteen: "Use as a spoon food, dip base, or soft component of family meals, keeping the product refrigerated and plainly seasoned."
            )
        case .firmTofu:
            return preparationStages(
                name: name,
                six: "Choose a plain soft or firm block that compresses easily. Cut into a wide strip for grasping or crumble and moisten it; avoid a browned rubbery crust.",
                nine: "Offer small soft pieces, crumbles, or narrow strips. Cooked tofu should remain tender enough to mash between fingers.",
                twelve: "Serve bite-size tender pieces with a fork or fingers, cutting away any tough fried edge and checking added sauce for sodium.",
                eighteen: "Offer tender cubes, strips, or crumbles in family meals; adjust any chewy skin or dense baked piece."
            )
        case .fermentedCake:
            let exactPreparation = formedPlantProteinPreparation(name: name)
            return preparationStages(
                name: name,
                six: exactPreparation,
                nine: "\(exactPreparation) Offer the prepared protein as tender crumbles, a thin strip, or a soft patty suited to pincer practice.",
                twelve: "\(exactPreparation) Offer small moist pieces with a fork or fingers.",
                eighteen: "\(exactPreparation) Use tender pieces in family meals and continue removing browned or chewy edges."
            )
        case .spread:
            let exactPreparation = plantProteinSpreadPreparation(name: name)
            return preparationStages(
                name: name,
                six: exactPreparation,
                nine: "\(exactPreparation) A thin layer on soft food can support pincer-grasp practice.",
                twelve: "\(exactPreparation) It can be offered as a loose dip or sauce with a child-size utensil.",
                eighteen: "\(exactPreparation) Keep the portion loose enough that it does not form a sticky mouthful."
            )
        case .seasoning:
            let exactPreparation = plantProteinSeasoningPreparation(name: name)
            return preparationStages(
                name: name,
                six: exactPreparation,
                nine: "\(exactPreparation) Avoid other salty ingredients in the child's portion.",
                twelve: "\(exactPreparation) Set aside the child's lightly seasoned portion before seasoning the family dish further.",
                eighteen: "\(exactPreparation) Balance it with unsalted ingredients."
            )
        case .sprout:
            return preparationStages(
                name: name,
                six: "Cook thoroughly until the stem is tender, then mince across its length and mix into moist food. Do not serve raw sprouts to a young child.",
                nine: "Cook fully and chop into short soft pieces so no long stringy stem or firm seed head remains.",
                twelve: "Offer fully cooked chopped sprouts in a moist dish, continuing to avoid raw or lightly cooked sprouts.",
                eighteen: "Use thoroughly cooked sprouts cut into manageable lengths in family meals."
            )
        }
    }

    private static func meatPreparations(name: String) -> [SolidsPreparationStage] {
        switch meatPreparationForm(name: name) {
        case .organ:
            return preparationStages(
                name: name,
                six: "Cook fully while keeping the center tender, then purée or finely mince a small portion with liquid. Remove membrane, ducts, and any firm connective tissue.",
                nine: "Serve finely chopped tender pieces mixed into moist food or spread a thin layer of cooked mince. Avoid dry crumbly chunks.",
                twelve: "Offer small soft pieces as one component of a varied meal. Keep portions modest because organ meat has concentrated nutrients.",
                eighteen: "Serve tender chopped pieces occasionally as part of family meals, continuing to remove membrane and tough tissue."
            )
        case .ground:
            return preparationStages(
                name: name,
                six: "Cook completely, then form a wide soft patty or mix fine crumbles with sauce so they hold moisture. Avoid a dry, rubbery meatball.",
                nine: "Offer moist crumbles, a tender strip of patty, or a very soft meatball broken into small pieces. Check the center and remove any hard crust.",
                twelve: "Serve small moist pieces with a fork or fingers. Packaged ground products may add sodium or allergens, so review the recipe.",
                eighteen: "Use tender patties, crumbles, or small pieces in family meals, adding moisture whenever the meat becomes dry."
            )
        case .boneIn:
            return preparationStages(
                name: name,
                six: "Cook slowly until the meat shreds with little pressure. Remove every loose bone, bone chip, skin, cartilage, and gristle, then offer moist shreds or a large tender strip of meat only.",
                nine: "Serve soft shreds or small tender pieces cut across the grain. Recheck the plated portion for bone and hard connective tissue.",
                twelve: "Offer bite-size moist meat with a fork. Do not hand over a small, splintering, or brittle bone as a teether.",
                eighteen: "Serve tender meat removed from the bone, continuing to exclude bone fragments, tough skin, cartilage, and gristle."
            )
        case .tenderCut:
            return preparationStages(
                name: name,
                six: "Cook completely with a moist method and use a boneless portion. If the cut was cooked on the bone, take the meat off and inspect it again. Finely mince with liquid or offer a large tender strip cut across the grain, removing any gristle or tough connective tissue.",
                nine: "Serve moist shreds, thin tender strips, or small pieces cut across the grain. Recheck any meat cooked on the bone before plating, and add sauce if the meat begins to dry out.",
                twelve: "Offer small tender pieces with a fork or fingers. Avoid dry cubes and browned hard edges.",
                eighteen: "Adapt the family portion into moist pieces the child can chew, continuing to cut across the grain and remove tough tissue."
            )
        }
    }

    private static func seafoodPreparations(name: String) -> [SolidsPreparationStage] {
        switch seafoodPreparationForm(name: name) {
        case .crustacean:
            return preparationStages(
                name: name,
                six: "Cook fully, remove every shell, tail, and vein as applicable, then mince the flesh very finely into moist food. Do not serve a whole curled piece.",
                nine: "Serve finely minced or flattened tender flesh in a soft patty or sauce. Recheck for shell and avoid rubbery chunks.",
                twelve: "Offer small thin pieces that tear easily, with every shell and tail removed. Crustacean shellfish is a major allergen.",
                eighteen: "Serve tender chopped pieces in family meals, continuing to remove shell and modify any firm curled or rubbery shape."
            )
        case .bivalve:
            return preparationStages(
                name: name,
                six: "Cook fully until safely done, remove the flesh from its shell, inspect for shell fragments, and mince very finely into a moist food.",
                nine: "Serve finely chopped cooked flesh mixed through a soft dish. Do not offer a whole chewy mollusk.",
                twelve: "Offer tiny tender pieces in a moist meal, checking every serving for grit, shell, and rubbery texture.",
                eighteen: "Serve fully cooked chopped flesh, continuing to discard shell and cut any chewy piece smaller across its fibers."
            )
        case .cephalopod:
            return preparationStages(
                name: name,
                six: "Cook fully until tender, remove beak or other inedible parts, and mince extremely finely into moist food. Rings and tentacle pieces are not early serving shapes.",
                nine: "Finely mince tender cooked flesh across the fibers and mix it into a soft dish. Avoid rubbery rings or long tentacles.",
                twelve: "Offer very small tender chopped pieces with sauce, checking that each piece tears easily.",
                eighteen: "Serve thoroughly cooked pieces cut across the fibers, continuing to avoid chewy rings and oversized tentacles."
            )
        case .smallFish:
            return preparationStages(
                name: name,
                six: "Cook fully or choose an appropriate cooked canned product, then open each fish and inspect closely for bones. Mash the flesh and moisten it; check cured products for high sodium.",
                nine: "Offer soft flakes or a tender patty after another careful bone check. Break up skin if it forms a tough sheet.",
                twelve: "Serve small moist flakes with a fork or fingers, checking canned or cured versions for sodium and every portion for bones.",
                eighteen: "Use soft flakes in family meals and keep inspecting small whole fish for bones even when processing has softened them."
            )
        case .fillet:
            let mercury = normalized(name) == "swordfish"
                ? "Do not serve; choose a lower-mercury fish instead."
                : "Check current FDA/EPA advice for the exact species."
            return preparationStages(
                name: name,
                six: "\(mercury) Cook fully, separate the fillet into soft moist flakes, and inspect each flake carefully for bones before mashing or offering a soft patty.",
                nine: "Serve soft flakes or small pieces that separate with light pressure. Recheck for pin bones and remove skin if it is tough.",
                twelve: "Offer bite-size moist flakes with a fork or fingers, continuing to check every portion for bones and species-specific fish advice.",
                eighteen: "Serve tender cooked pieces in family meals, removing bones and tough skin and avoiding dry or heavily salted preparations."
            )
        }
    }

    private static func eggPreparations(name: String) -> [SolidsPreparationStage] {
        if normalized(name) == "egg yolk" {
            return preparationStages(
                name: name,
                six: "Cook the yolk fully, then mash it with water, breast milk, formula, or another familiar moist food so it is not dry or crumbly. Offer it on a preloaded spoon.",
                nine: "Mash or finely crumble the fully cooked yolk into a moist food. Keep the mixture soft and avoid a dry ball of yolk.",
                twelve: "Mix fully cooked yolk into a moist family dish or offer it mashed by spoon. Check the complete dish for other allergens.",
                eighteen: "Serve fully cooked yolk within family meals, keeping it moist and following the family's established egg-allergen plan."
            )
        }
        return preparationStages(
            name: name,
            six: "Cook the white and yolk until safely done while keeping the texture tender. Mash with water or yogurt, grate a hard-cooked egg into food, or cut a soft omelet into two-finger-wide strips.",
            nine: "Serve fully cooked soft strips, grated egg, or small tender pieces. Add moisture if the yolk is dry and avoid rubbery browned edges.",
            twelve: "Offer chopped fully cooked egg or soft fork-size pieces. Check mixed egg dishes for milk, wheat, soy, or other allergens.",
            eighteen: "Serve fully cooked egg in family meals, keeping pieces tender and continuing the family's established allergen plan."
        )
    }

    private static func preparedFoodPreparations(name: String) -> [SolidsPreparationStage] {
        let profile = preparedFoodEditorialProfile(name: name)
        switch preparedFoodPreparationForm(name: name) {
        case .soupOrStew:
            return preparationStages(
                name: name,
                six: "\(profile.preparation) Offer the cooled result on a preloaded spoon rather than as thin hot broth.",
                nine: "\(profile.preparation) Serve it thick and lukewarm on a preloaded spoon for self-feeding practice.",
                twelve: "\(profile.preparation) Offer a cooled child-size portion from a shallow bowl with a child-size spoon.",
                eighteen: "\(profile.preparation) Keep the child's serving modest in sodium and suited to the child's established chewing and spoon skills."
            )
        case .patty:
            return preparationStages(
                name: name,
                six: "\(profile.preparation) Offer a wide soft strip that compresses easily or mash the tender center.",
                nine: "\(profile.preparation) Cut the tender result into narrow strips or small soft pieces for pincer-grasp practice.",
                twelve: "\(profile.preparation) Offer bite-size soft pieces with a fork or fingers.",
                eighteen: "\(profile.preparation) Serve a tender child-size portion cut for the child's established chewing skill."
            )
        case .spoonable:
            return preparationStages(
                name: name,
                six: "\(profile.preparation) Offer the finished food on a preloaded spoon.",
                nine: "\(profile.preparation) Serve a slightly thicker scoopable portion on a preloaded spoon for self-feeding practice.",
                twelve: "\(profile.preparation) Offer a child-size portion in a small bowl with a child-size spoon.",
                eighteen: "\(profile.preparation) Keep the child-size portion scoopable and suited to established utensil skills."
            )
        case .handheld:
            return preparationStages(
                name: name,
                six: "\(profile.preparation) Offer one wide soft strip only when it tears easily under light pressure.",
                nine: "\(profile.preparation) Cut the prepared food into narrow strips or small soft pieces for pincer-grasp practice.",
                twelve: "\(profile.preparation) Offer a manageable handheld piece and model taking one bite at a time.",
                eighteen: "\(profile.preparation) Serve a child-size handheld portion cut for the child's established biting and chewing skills."
            )
        case .pastaOrRice:
            return preparationStages(
                name: name,
                six: "\(profile.preparation) Mash or press the finished dish into a loose scoopable clump.",
                nine: "\(profile.preparation) Serve a soft moist portion for hand or preloaded-spoon practice.",
                twelve: "\(profile.preparation) Offer a child-size portion with a spoon or fork and break up any dense clump before serving.",
                eighteen: "\(profile.preparation) Serve a moist child-size portion suited to the child's established utensil and chewing skills."
            )
        case .mixedDish:
            return preparationStages(
                name: name,
                six: "\(profile.preparation) Mash the result into a moist texture or offer one broad soft component at a time.",
                nine: "\(profile.preparation) Offer small soft pieces or a scoopable portion for hand or spoon practice.",
                twelve: "\(profile.preparation) Serve a cooled child-size portion with a spoon, fork, or fingers.",
                eighteen: "\(profile.preparation) Serve a child-size portion suited to the child's established chewing and utensil skills."
            )
        case .sweetener:
            return [
                SolidsPreparationStage(minimumAgeMonths: 12, title: "12+ months", instructions: "\(name): only after the first birthday, mix a small amount into food rather than offering it from a spoon or container."),
                SolidsPreparationStage(minimumAgeMonths: 18, title: "18+ months", instructions: "\(name): use sparingly as an added sweetener within a balanced meal and continue normal tooth-brushing routines.")
            ]
        }
    }

    fileprivate enum ScoopablePreparationKind: Equatable {
        case porridge
        case smoothDairy
        case spread
    }

    fileprivate enum DairyPreparationForm: Equatable {
        case milkIngredient
        case pourableCultured
        case spoonableDairy
        case softSpread
        case crumblyCheese
        case firmCheese
        case paneer
    }

    fileprivate static func dairyPreparationForm(name: String) -> DairyPreparationForm {
        switch normalized(name) {
        case "buttermilk in food", "pasteurized milk in food":
            return .milkIngredient
        case "kefir":
            return .pourableCultured
        case "cottage cheese", "greek yogurt", "labneh", "mascarpone", "plain whole-milk yogurt", "ricotta", "skyr", "sour cream", "whole-milk yogurt":
            return .spoonableDairy
        case "cream cheese":
            return .softSpread
        case "feta cheese", "goat cheese", "queso fresco":
            return .crumblyCheese
        case "cheddar cheese", "colby cheese", "fontina cheese", "gouda cheese", "gruyere cheese", "havarti cheese", "monterey jack cheese", "mozzarella cheese", "parmesan cheese", "provolone cheese", "romano cheese", "swiss cheese":
            return .firmCheese
        case "paneer":
            return .paneer
        default:
            preconditionFailure("Missing dairy preparation form for \(name)")
        }
    }

    fileprivate static func dairySpecificPreparation(name: String) -> String {
        switch dairyPreparationForm(name: name) {
        case .milkIngredient:
            return "Use pasteurized \(name.lowercased()) only within cooked or spoonable food before 12 months; it must not replace breast milk or infant formula as the main drink."
        case .pourableCultured:
            return "Choose plain pasteurized unsweetened kefir and mix it into food or offer a small spoon-fed amount; before 12 months, do not use it as the child's main milk drink."
        case .spoonableDairy:
            if normalized(name) == "cottage cheese" {
                return "Choose pasteurized cottage cheese, mash large curds, add moisture if they are dry, and offer it by spoon without hard toppings."
            }
            return "Choose pasteurized unsweetened \(name.lowercased()), loosen it if thick or pasty, and offer it by spoon or mixed into food without hard toppings."
        case .softSpread:
            return "Choose pasteurized cream cheese, loosen it when dense, and serve only a very thin layer or a small amount mixed through moist food; do not offer a sticky spoonful."
        case .crumblyCheese:
            return "Choose pasteurized \(name.lowercased()), check sodium, and crumble it finely into moist food; do not offer a dry lump or firm cube."
        case .firmCheese:
            if ["parmesan cheese", "romano cheese"].contains(normalized(name)) {
                return "Choose pasteurized \(name.lowercased()), check sodium, and finely grate a small amount through moist food; do not offer a hard shard, rind, or firm cube."
            }
            if normalized(name) == "mozzarella cheese" {
                return "Choose pasteurized mozzarella, finely shred or slice it paper-thin, and mix melted cheese through food so it does not form a rubbery cube or long stringy clump."
            }
            return "Choose pasteurized \(name.lowercased()), check sodium and firmness, and finely grate, melt into food, or slice it paper-thin; do not offer a firm cube or rubbery slab."
        case .paneer:
            return "Choose pasteurized paneer, cook it until tender, then crumble or mash it into moist food; paneer does not melt, so do not offer a firm cube."
        }
    }

    fileprivate static func scoopablePreparationKind(
        name: String,
        category: SolidsFoodCategory
    ) -> ScoopablePreparationKind? {
        let key = normalized(name)
        if key == "puffed rice cereal" { return nil }
        if ["cereal", "porridge", "oatmeal", "grits", "polenta", "cream of rice", "farina"].contains(where: key.contains) {
            return .porridge
        }
        if key.hasSuffix(" butter") || key.contains("tahini") || key.contains("hummus") || key.contains("bean dip") || key.contains("refried bean") || key.contains("peanut sauce") {
            return .spread
        }
        if category == .dairy {
            switch dairyPreparationForm(name: name) {
            case .pourableCultured, .spoonableDairy:
                return .smoothDairy
            case .softSpread:
                return .spread
            case .milkIngredient, .crumblyCheese, .firmCheese, .paneer:
                return nil
            }
        }
        return nil
    }

    private static func scoopablePreparations(
        name: String,
        category: SolidsFoodCategory
    ) -> [SolidsPreparationStage]? {
        switch scoopablePreparationKind(name: name, category: category) {
        case .porridge:
            return preparationStages(
                name: name,
                six: "Cook until very soft and moist, thinning dry or sticky cereal as needed. Offer a thick scoopable texture on a preloaded spoon rather than a dry mouthful.",
                nine: "Serve as a thick, soft cereal and let the child practice with a preloaded spoon. Break up firm lumps and add moisture before serving.",
                twelve: "Offer in a small bowl for spoon practice. Keep it moist and check temperature carefully before serving.",
                eighteen: "Serve as a spoonable cereal with soft mix-ins. Avoid hard toppings and dense sticky spoonfuls."
            )
        case .smoothDairy:
            let exactPreparation = dairySpecificPreparation(name: name)
            return preparationStages(
                name: name,
                six: "\(exactPreparation) Use a preloaded spoon or stir it into another food.",
                nine: "\(exactPreparation) Let the child practice with a preloaded spoon.",
                twelve: "\(exactPreparation) Serve a child-size amount in a small bowl with a spoon.",
                eighteen: "\(exactPreparation) It can also be mixed into family meals."
            )
        case .spread:
            if category == .dairy {
                let exactPreparation = dairySpecificPreparation(name: name)
                return preparationStages(
                    name: name,
                    six: exactPreparation,
                    nine: "\(exactPreparation) A thin layer on soft food can support pincer-grasp practice.",
                    twelve: "\(exactPreparation) It can also be mixed into a soft family dish.",
                    eighteen: "\(exactPreparation) Continue avoiding a dense sticky spoonful."
                )
            }
            return preparationStages(
                name: name,
                six: "Thin it with warm water or mix a small amount into a familiar moist food. Never offer a thick sticky spoonful.",
                nine: "Spread a very thin layer on soft food or stir it into a scoopable dish. Keep the texture loose, not gluey or clumped.",
                twelve: "Use as a thin spread, sauce, or stirred-in ingredient. Avoid a dense spoonful or a sticky lump.",
                eighteen: "Continue serving as a thin spread or sauce and adjust thickness so it does not form a sticky mouthful."
            )
        case nil:
            return nil
        }
    }

    fileprivate enum GrainPreparationForm {
        case bread
        case pasta
        case puffedCereal
        case softGrain
    }

    fileprivate static func grainPreparationForm(name: String) -> GrainPreparationForm {
        switch normalized(name) {
        case "bread", "corn tortilla", "cornbread", "multigrain bread", "rye bread", "toast", "whole-wheat bread", "whole-wheat toast":
            return .bread
        case "angel hair pasta", "buckwheat noodle", "orzo", "pasta", "rice noodle", "udon noodle", "wheat noodle", "whole-grain pasta":
            return .pasta
        case "puffed rice cereal":
            return .puffedCereal
        case "amaranth", "arborio rice", "barley", "barley cereal", "basmati rice", "black rice", "bran cereal", "brown rice", "buckwheat", "bulgur", "cassava flour porridge", "cornmeal", "couscous", "cream of rice", "einkorn", "farina", "farro", "fonio", "freekeh", "grits", "hominy", "infant barley cereal", "infant multigrain cereal", "infant oatmeal", "infant rice cereal", "jasmine rice", "kamut", "kasha", "millet", "oat bran", "oatmeal", "pearl barley", "polenta", "quinoa", "red rice", "rice", "rice porridge", "rye", "semolina", "sorghum", "spelt", "steel-cut oats", "teff", "wheat berries", "wheat cereal", "white rice", "whole-wheat couscous", "wild rice":
            return .softGrain
        default:
            preconditionFailure("Missing grain preparation form for \(name)")
        }
    }

    private static func grainPreparations(name: String) -> [SolidsPreparationStage] {
        switch grainPreparationForm(name: name) {
        case .bread:
            return preparationStages(
                name: name,
                six: "Use a soft, low-sodium option and lightly toast or moisten it so it does not form a gummy ball. Cut into a wide two-finger strip and add only a thin moist topping.",
                nine: "Cut into narrow strips or small bite-size pieces and keep the texture moist. Avoid dense compressed bread and thick sticky toppings.",
                twelve: "Offer manageable pieces for biting and chewing, with a soft topping when helpful. Watch for bread that becomes gummy in the mouth.",
                eighteen: "Serve strips, small pieces, or a soft sandwich cut to the child's chewing skills. Avoid dense balls of bread and hard crusts."
            )
        case .pasta:
            return preparationStages(
                name: name,
                six: "Cook past al dente until very soft. Offer a large easy-to-hold shape or cut long strands, coating lightly with sauce or oil so the pasta stays moist.",
                nine: "Cook until soft, then cut long strands or large shapes into small manageable pieces for pincer grasp. Keep pieces slippery-soft rather than chewy.",
                twelve: "Offer soft bite-size shapes or short-cut strands with a child-size fork. Avoid firm, undercooked, or very chewy pasta.",
                eighteen: "Serve soft family pasta with long strands cut as needed and any hard, round, or tough add-ins modified separately."
            )
        case .puffedCereal:
            return preparationStages(
                name: name,
                six: "Crush and moisten the cereal into a soft spoonable texture. Do not offer dry hard pieces to a new eater.",
                nine: "Choose an unsweetened puff that dissolves easily, test it yourself, and offer one piece at a time while the child is seated upright.",
                twelve: "Offer a small amount of easily dissolving cereal for finger-food practice, avoiding hard clusters and large dry mouthfuls.",
                eighteen: "Serve an unsweetened easily dissolving cereal in a seated meal or snack, not while the child is moving."
            )
        case .softGrain:
            return preparationStages(
                name: name,
                six: "Cook in plenty of liquid until each grain is very soft. Mash or press into a moist scoopable clump and offer on a preloaded spoon; do not serve loose, dry grains.",
                nine: "Serve very soft grains as moist clumps that can be picked up or scooped. Add sauce or another soft food if the grains are dry or separate.",
                twelve: "Offer soft moist grains with a child-size spoon or fork. Break up sticky dense clumps and avoid dry mouthfuls.",
                eighteen: "Serve soft grains as part of family meals, adding moisture and separating any dense sticky clump before serving."
            )
        }
    }

    private static func cheesePreparations(name: String) -> [SolidsPreparationStage] {
        let exactPreparation = dairySpecificPreparation(name: name)
        let form = dairyPreparationForm(name: name)

        if form == .paneer {
            return preparationStages(
                name: name,
                six: exactPreparation,
                nine: "\(exactPreparation) Offer fine crumbles or a thin tender strip that mashes easily between fingers.",
                twelve: "\(exactPreparation) Serve small soft crumbles or very thin tender pieces in a moist dish.",
                eighteen: "\(exactPreparation) Size the tender pieces to the child's established chewing skill."
            )
        }

        if form == .crumblyCheese {
            return preparationStages(
                name: name,
                six: exactPreparation,
                nine: "\(exactPreparation) Press fine crumbles onto a soft finger food for pincer practice.",
                twelve: "\(exactPreparation) Serve small soft crumbles as part of a meal.",
                eighteen: "\(exactPreparation) Size the crumbles to the child's established chewing skill."
            )
        }

        return preparationStages(
            name: name,
            six: exactPreparation,
            nine: "\(exactPreparation) Use a finely prepared amount in moist food or on a soft finger food.",
            twelve: "\(exactPreparation) Offer the named safe form for fork or finger practice.",
            eighteen: "\(exactPreparation) Size the prepared form to the child's established chewing skill."
        )
    }

    private static func milkIngredientPreparations(name: String) -> [SolidsPreparationStage] {
        preparationStages(
            name: name,
            six: "Use only a pasteurized product as a small ingredient in cooked food, porridge, or another spoonable dish. Do not offer it as the main drink before 12 months.",
            nine: "Continue mixing a modest amount into food or using it in cooking. Keep breast milk or infant formula as the main milk source before the first birthday.",
            twelve: "After 12 months, it can remain an ingredient; discuss the child's overall milk choice with their clinician and avoid letting dairy drinks displace varied food.",
            eighteen: "Use in family cooking and meals, choosing pasteurized products and keeping added sugar modest."
        )
    }

    private static func nutAndSeedPreparations(name: String) -> [SolidsPreparationStage] {
        let key = normalized(name)
        let exactPreparation = nutAndSeedSpecificPreparation(name: name)
        let isSmallSeed = ["chia seed", "flaxseed", "hemp seed", "poppy seed", "pumpkin seed", "sesame seed", "sunflower seed"].contains(key)

        if key.contains("ground") {
            return preparationStages(
                name: name,
                six: exactPreparation,
                nine: "\(exactPreparation) It can also be pressed onto a moist surface for pincer-grasp practice.",
                twelve: "\(exactPreparation) It can be dispersed through moist meals or baking.",
                eighteen: "\(exactPreparation) Continue checking every batch for coarse pieces."
            )
        }

        if isSmallSeed {
            return preparationStages(
                name: name,
                six: exactPreparation,
                nine: "\(exactPreparation) Keep the prepared seed dispersed rather than in a dry or dense clump.",
                twelve: "\(exactPreparation) It can be incorporated into moist meals or baking.",
                eighteen: "\(exactPreparation) Continue avoiding a loose dry mouthful."
            )
        }

        return preparationStages(
            name: name,
            six: exactPreparation,
            nine: "\(exactPreparation) The prepared form can be mixed into moist food or pressed onto a soft surface.",
            twelve: "\(exactPreparation) It can be incorporated into moist meals or baking.",
            eighteen: "\(exactPreparation) Whole nuts and hard pieces remain excluded for a young toddler."
        )
    }

    /// Exact usable form for every nut and seed label in the catalog.
    fileprivate static func nutAndSeedSpecificPreparation(name: String) -> String {
        switch normalized(name) {
        case "almond butter", "cashew butter", "coconut butter", "hazelnut butter", "macadamia nut butter", "peanut butter", "pecan butter", "pistachio butter", "sunflower seed butter", "walnut butter":
            return "Choose a smooth product with no crunchy pieces, serve it well thinned into moist food or in a very thin layer, and never offer a thick spoonful."
        case "tahini":
            return "Choose smooth tahini, stir separated oil back in, serve it well thinned into moist food or in a very thin layer, and never offer a thick spoonful."
        case "ground almond", "ground cashew", "ground hazelnut", "ground pecan", "ground pistachio", "ground walnut":
            return "Inspect the ground meal for coarse or hard fragments, then mix a small amount completely through moist food; never offer a dry spoonful."
        case "chia seed":
            return "Grind chia seed or hydrate it completely until every seed is suspended in a loose gel, then mix a small amount through moist food; do not offer dry chia or a dense gel clump."
        case "flaxseed":
            return "Use finely ground flaxseed mixed completely through moist food; do not offer whole dry seeds or a dry spoonful of flax meal."
        case "hemp seed":
            return "Use shelled hemp hearts that are finely crushed when needed and mix them completely through moist food; do not offer a loose dry spoonful."
        case "poppy seed":
            return "Use only a small culinary amount of finely ground poppy seed mixed through moist food or cooked into a soft dish; do not offer loose dry seeds."
        case "pumpkin seed", "sesame seed", "sunflower seed":
            return "Grind the seed to a smooth powder or paste and mix it completely through moist food; do not offer whole seeds, hard fragments, or a dry spoonful."
        case "chestnut":
            return "Remove the shell and inner skin, cook the chestnut until soft, then mash it with moisture or grind it finely; do not offer a whole chestnut or firm chunk."
        case "almond", "brazil nut", "cashew", "hazelnut", "macadamia nut", "peanut", "pecan", "pine nut", "pistachio", "walnut":
            return "Grind the nut to a fine powder and mix it completely through moist food, or use its smooth butter thinned well; never offer the whole nut or a hard piece."
        default:
            preconditionFailure("Missing nut-or-seed preparation for \(name)")
        }
    }

    fileprivate enum FlavorPreparationForm {
        case leafyHerb
        case fibrousAromatic
        case groundSpice
        case bayLeaf
    }

    fileprivate static func flavorSpecificPreparation(name: String) -> String {
        switch normalized(name) {
        case "allspice", "black pepper", "nutmeg", "paprika", "turmeric":
            return "Use only a small pinch of the finely ground spice mixed evenly through moist food; leave no dry powder pocket or whole hard piece."
        case "anise", "caraway", "coriander", "cumin", "fenugreek":
            return "Use a small pinch of finely ground seed mixed through moist food; do not leave a whole seed in the child's serving."
        case "cardamom":
            return "Use a small pinch of ground cardamom, or infuse with a pod and remove the entire pod plus every hard seed before serving."
        case "cinnamon":
            return "Use a small pinch of ground cinnamon mixed through moist food, or infuse with a stick and remove the whole stick before serving."
        case "clove":
            return "Use only a tiny pinch of ground clove, or infuse with a whole clove and count and remove every hard bud before serving."
        case "garlic powder":
            return "Use a small pinch of plain garlic powder mixed completely through moist food; choose a product without added salt and leave no dry clump."
        case "saffron":
            return "Steep one or two saffron threads in cooking liquid for flavor and remove any intact thread before serving; do not offer a dry pinch."
        case "vanilla":
            return "Use a small culinary amount of alcohol-free vanilla flavoring or seeds scraped from a pod; never leave a pod piece in the serving."
        case "za'atar herb blend":
            return "Use a small pinch of a finely ground salt-free blend mixed through moist food; check the label for sesame and leave no coarse herb stem or hard spice fragment."
        case "bay leaf flavor":
            return "Use one whole bay leaf only to infuse a cooked dish, then count and remove the stiff leaf before plating the child's portion."
        case "galangal", "ginger":
            return "Peel the root and finely grate or pound a small amount into cooked moist food, removing any woody strand or chunk."
        case "lemongrass":
            return "Bruise a trimmed stalk to infuse the dish, then remove every fibrous stalk section before serving; do not mince coarse rings into the child's portion."
        case "basil", "celery leaf", "chervil", "chive", "cilantro", "dill", "fennel frond", "lemon balm", "marjoram", "mint", "parsley", "spearmint", "tarragon":
            return "Wash the leaves, remove firm stems, mince a small amount finely, and mix it through moist food so it cannot form a loose leafy clump."
        case "curry leaf", "oregano", "rosemary", "sage", "thyme":
            return "Remove the leaves from every woody stem, chop or crumble a small amount finely into cooked moist food, and leave no stiff leaf or stem piece."
        default:
            preconditionFailure("Missing herb-or-flavor preparation for \(name)")
        }
    }

    fileprivate static func flavorPreparationForm(name: String) -> FlavorPreparationForm {
        switch normalized(name) {
        case "bay leaf flavor":
            return .bayLeaf
        case "galangal", "ginger", "lemongrass":
            return .fibrousAromatic
        case "basil", "celery leaf", "chervil", "chive", "cilantro", "curry leaf", "dill", "fennel frond", "lemon balm", "marjoram", "mint", "oregano", "parsley", "rosemary", "sage", "spearmint", "tarragon", "thyme":
            return .leafyHerb
        case "allspice", "anise", "black pepper", "caraway", "cardamom", "cinnamon", "clove", "coriander", "cumin", "fenugreek", "garlic powder", "nutmeg", "paprika", "saffron", "turmeric", "vanilla", "za'atar herb blend":
            return .groundSpice
        default:
            preconditionFailure("Missing herb-or-flavor form for \(name)")
        }
    }

    private static func flavorPreparations(name: String) -> [SolidsPreparationStage] {
        let exactPreparation = flavorSpecificPreparation(name: name)
        switch flavorPreparationForm(name: name) {
        case .bayLeaf:
            return preparationStages(
                name: name,
                six: "\(exactPreparation) Use only the infused flavor in a familiar cooked food.",
                nine: "\(exactPreparation) Plate the child's portion only after the leaf count is reconciled.",
                twelve: "\(exactPreparation) The family dish may be shared after the leaf is removed.",
                eighteen: "\(exactPreparation) Continue counting leaves whenever more than one is used."
            )
        case .fibrousAromatic:
            return preparationStages(
                name: name,
                six: "\(exactPreparation) Mix the prepared flavoring evenly into one familiar moist food.",
                nine: "\(exactPreparation) Use it in a soft dish the child can scoop or pick up.",
                twelve: "\(exactPreparation) Add it to a child-size portion of the family meal.",
                eighteen: "\(exactPreparation) Keep the amount culinary and suited to the child's taste."
            )
        case .leafyHerb:
            return preparationStages(
                name: name,
                six: "\(exactPreparation) Mix it evenly into one familiar moist food.",
                nine: "\(exactPreparation) Use it in a soft dish the child can scoop or pick up.",
                twelve: "\(exactPreparation) Add it to a child-size portion of the family meal.",
                eighteen: "\(exactPreparation) Keep the amount culinary and suited to the child's taste."
            )
        case .groundSpice:
            return preparationStages(
                name: name,
                six: "\(exactPreparation) Introduce the flavor in one familiar moist food.",
                nine: "\(exactPreparation) Distribute it through a soft dish rather than dusting the surface.",
                twelve: "\(exactPreparation) Season the child's portion lightly before stronger family seasoning is added.",
                eighteen: "\(exactPreparation) Keep the amount culinary and suited to the child's taste."
            )
        }
    }

    private static func sourceURLs(
        name: String,
        category: SolidsFoodCategory,
        hasAllergens: Bool
    ) -> [URL] {
        let query = name.addingPercentEncoding(withAllowedCharacters: .urlQueryAllowed) ?? name
        let usda = URL(string: "https://fdc.nal.usda.gov/fdc-app.html#/food-search?query=\(query)")
            ?? SolidsSourceLibrary.foodDataCentral
        var sources = [
            usda,
            SolidsSourceLibrary.cdcIntroduction,
            SolidsSourceLibrary.cdcChoking,
            SolidsSourceLibrary.aapStartingSolids,
            SolidsSourceLibrary.nhsFoodSafety
        ]
        if normalized(name) == "acai" {
            sources.insert(contentsOf: [
                SolidsSourceLibrary.nccihAcai,
                SolidsSourceLibrary.datePalmFruitAllergy,
                SolidsSourceLibrary.heartOfPalmAnaphylaxis,
                SolidsSourceLibrary.whoComplementaryFeeding,
                SolidsSourceLibrary.espghanSugarPosition,
                SolidsSourceLibrary.aapFruitJuice
            ], at: 0)
        }
        if category == .fruit { sources.append(SolidsSourceLibrary.aapFruitJuice) }
        if category == .fruit || category == .vegetable || normalized(name).contains("sprout") {
            sources.append(SolidsSourceLibrary.fdaProduceSafety)
        }
        if hasAllergens {
            sources += [SolidsSourceLibrary.fdaAllergens, SolidsSourceLibrary.aapAllergenIntroduction]
        }
        if category == .seafood {
            sources.append(SolidsSourceLibrary.fdaFishAdvice)
        }
        var seen = Set<URL>()
        return sources.filter { seen.insert($0).inserted }
    }

    private static func chokingGuidance(name: String, category: SolidsFoodCategory) -> String {
        let key = normalized(name)
        if key == "acai" {
            return "Fresh açaí berries are small and round and contain a large hard seed. Use unsweetened prepared pulp, purée, or powder mixed into a moist food instead of serving a whole fresh berry."
        }
        if ["cactus pear", "prickly pear"].contains(key) {
            return "Spines and hair-like glochids can remain on the outer skin. Remove them and the entire peel before preparing the ripe flesh, then mash or cut it into a soft manageable form and remove any unexpectedly hard seed."
        }
        if key.contains("sausage") || key.contains("hot dog") {
            return "Cut \(name.lowercased()) lengthwise into thin strips and then into small pieces; never serve coin-shaped rounds. Check sodium and casing texture."
        }
        if key.contains("popcorn") {
            return "Popcorn is a hard, irregular choking hazard and is not appropriate for babies or young toddlers. Choose soft cooked corn in a modified shape instead."
        }
        switch category {
        case .fruit:
            let trim = fruitTrimmingGuidance(name: name)
            switch fruitPreparationForm(name: name) {
            case .sauce:
                return "Keep \(name.lowercased()) scoopable rather than watery, and serve it from a bowl or spoon with the pouch cap out of reach."
            case .smallRoundBerry:
                return "A firm whole \(name.lowercased()) can keep a small round airway shape. Cook if needed, then crush or flatten every berry."
            case .aggregateBerry:
                return "\(trim) Use ripe \(name.lowercased()) that collapses easily, then flatten or tear it when the berry does not break down readily."
            case .roundOrSlipperyFruit:
                return "Do not serve \(name.lowercased()) whole and round. \(trim) Then mash or cut the ripe flesh lengthwise."
            case .citrus:
                return "Tough citrus membrane and seeds can be difficult to manage. Remove them and serve the soft juicy pulp rather than an intact membrane-wrapped segment."
            case .firmFruit:
                return "Hard raw \(name.lowercased()) pieces can break into airway-sized chunks. Cook until soft or grate finely after removing the core and seeds."
            case .stoneFruit:
                return "Remove the entire pit from \(name.lowercased()) and use ripe flesh that squashes easily; cook it when firm and avoid slippery round pieces."
            case .melon:
                return "\(trim) Use a broad soft piece of \(name.lowercased()), not a melon ball or small slippery cube."
            case .softFruit:
                return "\(trim) Use only \(name.lowercased()) flesh that squashes easily."
            case .seededPulp:
                return "Serve only the soft pulp of \(name.lowercased()) by spoon and remove any large or unexpectedly hard seed; keep the rind out of reach."
            case .arils:
                return "Intact \(name.lowercased()) arils can remain firm and round. Crush or flatten them rather than offering a handful."
            case .driedStickyFruit:
                return "Whole dried \(name.lowercased()) can form a dense sticky mouthful. Remove the pit, soften thoroughly, and mash or mince it into moist food."
            case .gratedFlesh:
                return "Hard coconut chunks and dry strips can be difficult to chew. Use finely grated flesh or a smooth coconut product mixed into moist food."
            case .cookBeforeServing:
                return "\(trim) Cook \(name.lowercased()) thoroughly and serve only the soft edible portion."
            }
        case .vegetable, .grain, .beanAndPlantProtein, .meat, .seafood, .dairy, .egg, .herbAndFlavor, .preparedFood:
            return safetyNote(name: name, category: category)
        case .nutAndSeed:
            if key.contains("butter") || key == "tahini" {
                return "A thick spoonful of \(name.lowercased()) can stick as one mass. Thin it into moist food or spread only a very thin layer."
            }
            if key.contains("ground") {
                return "Mix \(name.lowercased()) fully into moist food so no hard piece, dry pocket, or dense clump remains."
            }
            return "Whole or chopped \(name.lowercased()) is a choking hazard for babies and young toddlers. Grind it finely into moist food or use a smooth, well-thinned butter."
        }
    }

    private static func ironRichStatus(name: String, category: SolidsFoodCategory) -> Bool {
        let key = normalized(name)
        switch category {
        case .meat, .egg:
            return true
        case .beanAndPlantProtein:
            return ![.seasoning, .sprout].contains(plantProteinPreparationForm(name: name))
        case .seafood:
            return seafoodPreparationForm(name: name) == .bivalve
                || ["sardine", "anchovy", "smelt"].contains(where: key.contains)
        case .grain:
            return key.contains("infant") || key.contains("fortified")
        case .nutAndSeed:
            return ["pumpkin seed", "sesame", "tahini"].contains(where: key.contains)
        case .preparedFood:
            return ["beef", "meat", "bean", "lentil", "tofu"].contains(where: key.contains)
        default:
            return false
        }
    }

    private static func servingVisuals(name: String, category: SolidsFoodCategory) -> [SolidsServingVisual] {
        let key = normalized(name)
        if key == "acai" || key == "applesauce" { return [.spoon, .spoon, .spoon, .spoon] }
        if key == "egg yolk" { return [.spoon, .spoon, .spoon, .spoon] }
        if category == .fruit {
            switch fruitPreparationForm(name: name) {
            case .sauce, .seededPulp:
                return [.spoon, .spoon, .spoon, .spoon]
            case .smallRoundBerry, .aggregateBerry, .roundOrSlipperyFruit, .arils:
                return [.mashed, .flattened, .softPieces, .softPieces]
            case .firmFruit:
                return [.mashed, .shredded, .softPieces, .softPieces]
            case .driedStickyFruit:
                return [.mashed, .thinSpread, .softPieces, .softPieces]
            case .gratedFlesh:
                return [.shredded, .shredded, .shredded, .softPieces]
            case .citrus, .stoneFruit, .melon, .softFruit, .cookBeforeServing:
                return [.mashed, .spear, .softPieces, .softPieces]
            }
        }
        switch scoopablePreparationKind(name: name, category: category) {
        case .porridge, .smoothDairy:
            return [.spoon, .spoon, .spoon, .spoon]
        case .spread:
            return [.spoon, .thinSpread, .thinSpread, .thinSpread]
        case nil:
            break
        }
        if category == .grain {
            if key.contains("bread") || key.contains("toast") || key.contains("tortilla") || key == "cornbread" {
                return [.spear, .softPieces, .softPieces, .softPieces]
            }
            if key.contains("pasta") || key.contains("noodle") || key == "orzo" {
                return [.spear, .softPieces, .softPieces, .softPieces]
            }
            if key.contains("puffed") { return [.mashed, .softPieces, .softPieces, .softPieces] }
            return [.spoon, .spoon, .spoon, .spoon]
        }
        if category == .vegetable {
            switch vegetablePreparationForm(name: name) {
            case .leafy, .bulb, .fibrousSpecialty:
                return [.mashed, .shredded, .softPieces, .softPieces]
            case .roundKernel, .compactBud:
                return [.mashed, .flattened, .softPieces, .softPieces]
            case .flower, .squash, .pod, .stalk, .swollenStem, .softFlesh, .root, .tuber:
                return [.mashed, .spear, .softPieces, .softPieces]
            }
        }
        if category == .beanAndPlantProtein {
            switch plantProteinPreparationForm(name: name) {
            case .wholePulse: return [.mashed, .flattened, .softPieces, .softPieces]
            case .softTofu, .spread, .seasoning: return [.spoon, .spoon, .spoon, .spoon]
            case .firmTofu, .fermentedCake: return [.spear, .softPieces, .softPieces, .softPieces]
            case .sprout: return [.shredded, .shredded, .softPieces, .softPieces]
            }
        }
        if category == .dairy { return [.shredded, .shredded, .softPieces, .softPieces] }
        if category == .egg { return [.mashed, .spear, .softPieces, .softPieces] }
        if category == .nutAndSeed || category == .herbAndFlavor { return [.spoon, .spoon, .spoon, .spoon] }
        if category == .seafood { return [.flakes, .softPieces, .softPieces, .softPieces] }
        if category == .meat { return [.shredded, .spear, .softPieces, .softPieces] }
        if category == .preparedFood {
            switch preparedFoodPreparationForm(name: name) {
            case .soupOrStew, .spoonable, .pastaOrRice, .sweetener:
                return [.spoon, .spoon, .spoon, .spoon]
            case .patty:
                return [.flattened, .softPieces, .softPieces, .softPieces]
            case .handheld:
                return [.spear, .softPieces, .softPieces, .softPieces]
            case .mixedDish:
                return [.mashed, .softPieces, .softPieces, .softPieces]
            }
        }
        if ["grape", "blueberry", "cherry"].contains(where: key.contains) {
            return [.mashed, .flattened, .softPieces, .softPieces]
        }
        return [.mashed, .spear, .softPieces, .softPieces]
    }

    private static func safetyNote(name: String, category: SolidsFoodCategory) -> String {
        let key = normalized(name)
        if key == "acai" {
            return "Use unsweetened commercially prepared pulp, purée, or powder. Do not serve fresh whole açaí berries or hard bowl toppings, and do not add honey before 12 months."
        }
        if key == "honey" {
            return "Do not offer honey before 12 months because of infant botulism risk."
        }
        if key == "swordfish" {
            return "FDA/EPA list swordfish as a choice to avoid for young children because it has among the highest mercury levels. Choose a lower-mercury fish instead."
        }
        if key == "tuna" {
            return "Mercury guidance varies by tuna species. Canned light tuna is a lower-mercury choice; avoid bigeye tuna and check FDA/EPA fish advice for other types."
        }
        if key == "mackerel" {
            return "Mercury guidance varies by mackerel species. Do not use king mackerel for a young child; confirm the exact species against current FDA/EPA fish advice before serving another type."
        }
        if ["cactus pear", "prickly pear"].contains(key) {
            return "Use only fruit with every spine and hair-like glochid removed. Peel away the entire outer skin, clean the work area, and serve only the ripe soft flesh with any unexpectedly hard seed removed."
        }
        if key == "cassava" || key == "yucca root" {
            return "Never serve cassava raw. Peel and cook it properly because raw or improperly processed cassava contains naturally occurring cyanogenic compounds; discard bitter-tasting cassava and its cooking water."
        }
        if key == "taro" {
            return "Never serve taro raw. Peel and cook it thoroughly because raw or undercooked taro contains calcium oxalate crystals that can irritate the mouth and throat."
        }
        if key == "fiddlehead fern" || key == "edible fern" {
            return "Do not serve raw or lightly cooked fern shoots. Clean them carefully and boil or steam them thoroughly according to food-safety guidance before changing the texture for the child."
        }
        if key.contains("sprout") {
            return "Raw and lightly cooked sprouts can carry harmful bacteria. Cook thoroughly until steaming hot, then cool and chop before serving."
        }
        if key.contains("liver") {
            return "Cook liver fully, remove membrane and tough tissue, and serve a modest amount. Liver is concentrated in preformed vitamin A, so it should not be treated as an everyday large portion."
        }
        switch category {
        case .fruit:
            let trim = fruitTrimmingGuidance(name: name)
            switch fruitPreparationForm(name: name) {
            case .sauce:
                return "Choose unsweetened \(name.lowercased()) with no honey before 12 months, and serve it from a bowl or spoon rather than letting the child handle a pouch cap."
            case .smallRoundBerry, .aggregateBerry:
                return "\(trim) Mash, flatten, or cut any \(name.lowercased()) that remains firm or round."
            case .roundOrSlipperyFruit:
                return "\(trim) Never serve \(name.lowercased()) whole and round."
            case .citrus:
                return "Remove peel, seeds, and tough membrane. Offer the pulp rather than a firm membrane-wrapped segment."
            case .firmFruit:
                return "Remove the core and seeds, then cook or finely grate the fruit instead of offering hard raw chunks."
            case .stoneFruit:
                return "Remove the entire pit and use only ripe soft flesh, peeling tough skin or cooking firm fruit when needed."
            case .melon:
                return "\(trim) Avoid melon balls or small slippery cubes."
            case .softFruit:
                return "\(trim) Use only fully ripe soft flesh."
            case .seededPulp:
                return "Keep the rind out of the serving and remove any large or unexpectedly hard seed from the soft pulp."
            case .arils:
                return "Remove rind and membrane, then crush or flatten every firm aril for an early eater."
            case .driedStickyFruit:
                return "Confirm the pit is removed, soften the fruit thoroughly, and do not serve a whole dense, sticky piece."
            case .gratedFlesh:
                return "Use finely grated flesh or a smooth coconut product in moist food; avoid hard chunks and dry chewy strips."
            case .cookBeforeServing:
                return "\(trim) Cook \(name.lowercased()) thoroughly and use only the soft edible portion."
            }
        case .vegetable:
            let trim = vegetableTrimmingGuidance(name: name)
            switch vegetablePreparationForm(name: name) {
            case .leafy:
                return "Wash well, cook until tender, remove tough stems, and chop across fibers so the leaves do not form a stringy clump."
            case .flower:
                return "Cook until the thickest stem and florets crush easily; trim woody leaves and avoid firm loose buds."
            case .compactBud, .roundKernel:
                return "Cook until soft and mash, flatten, halve, or quarter the round piece rather than serving it intact."
            case .squash:
                return "\(trim) Cook the edible flesh until it crushes easily."
            case .pod:
                return "Remove strings and tough seams, cook the pod until soft, and split or chop it."
            case .stalk:
                return "Trim woody ends and strings, cook until tender, and cut across the fibers."
            case .bulb:
                return "Cook until soft and avoid firm raw chunks or large slippery layers."
            case .swollenStem:
                return "\(trim) Cook the pale interior until it crushes easily; do not serve a hard raw cube."
            case .softFlesh:
                return "\(trim) Use soft edible flesh and avoid small slippery cubes."
            case .root:
                return "Cook until the center crushes easily or follow a specifically recommended fine-grated preparation; do not serve hard raw chunks."
            case .tuber:
                return "Cook fully through the center and keep the starchy flesh moist."
            case .fibrousSpecialty:
                return "\(trim) Cook the edible portion thoroughly and discard any section that remains tough."
            }
        case .grain:
            switch grainPreparationForm(name: name) {
            case .bread:
                return "Avoid hard crusts, whole seeds or nuts, and compressed gummy mouthfuls; use a piece that tears easily."
            case .pasta:
                return "Cook past firm, shorten strands or modify large shapes, and keep the pasta moist rather than sticky or rubbery."
            case .puffedCereal:
                return "Use only puffs that dissolve readily and offer a few at a time while the child is seated and supervised."
            case .softGrain:
                return "Cook until no hard center remains, add enough moisture, and break up dense clumps or whole kernels."
            }
        case .beanAndPlantProtein:
            switch plantProteinPreparationForm(name: name) {
            case .wholePulse:
                return "Cook until the center mashes easily, then mash or flatten whole beans and peas for an early eater."
            case .softTofu:
                return "Keep the tofu scoopable and check for firm add-ins or a rubbery surface."
            case .firmTofu:
                return "Use moist strips, crumbles, or soft pieces that compress and break apart easily."
            case .fermentedCake:
                return formedPlantProteinPreparation(name: name)
            case .spread:
                return plantProteinSpreadPreparation(name: name)
            case .seasoning:
                return plantProteinSeasoningPreparation(name: name)
            case .sprout:
                return "Cook sprouts thoroughly until steaming hot, cool them, and chop across the stems before serving."
            }
        case .meat:
            switch meatPreparationForm(name: name) {
            case .organ:
                return "Cook fully, remove membrane and tough ducts, and keep the finished texture soft and moist."
            case .ground:
                return "Cook fully and keep patties, meatballs, or crumbles moist; break apart hard crusts and rubbery pieces."
            case .boneIn:
                return "Cook fully, remove the meat from the bone, and inspect again for loose bone, cartilage, gristle, and tough skin."
            case .tenderCut:
                return "Cook fully and use a boneless portion. If the cut was cooked on the bone, remove the meat and inspect it again; discard any gristle or tough connective tissue, then shred across the grain or mince with moisture."
            }
        case .seafood:
            switch seafoodPreparationForm(name: name) {
            case .crustacean:
                return "Cook fully, remove the entire shell and tail, and mince or flatten any firm curved flesh."
            case .bivalve:
                return "Cook fully, remove every shell fragment, and mince the chewy flesh finely."
            case .cephalopod:
                return "Cook fully until tender and mince very finely; do not serve rings, tentacles, or rubbery chunks."
            case .smallFish:
                return "Check sodium and current fish advice, cook as needed, and inspect every portion carefully for bones."
            case .fillet:
                return "Cook fully, follow current advice for the exact species, and inspect the cooked flakes carefully for fine bones."
            }
        case .dairy:
            return dairySpecificPreparation(name: name)
        case .egg:
            return key == "egg yolk"
                ? "Cook the yolk fully and add moisture so it is not dry or crumbly. Egg is a major food allergen."
                : "Cook the egg fully while keeping it soft rather than rubbery. Egg is a major food allergen."
        case .nutAndSeed:
            return nutAndSeedSpecificPreparation(name: name)
        case .herbAndFlavor:
            return flavorSpecificPreparation(name: name)
        case .preparedFood:
            return preparedFoodEditorialProfile(name: name).preparation
        }
    }

    private static func allergenIDs(name: String, category: SolidsFoodCategory) -> [String] {
        let key = normalized(name)
        if category == .preparedFood {
            let allergens: [SolidsAllergen]
            switch key {
            case "egg fried rice":
                allergens = [.egg]
            case "fish cake", "salmon cake":
                allergens = [.fish]
            case "french toast":
                allergens = [.egg]
            case "macaroni and cheese":
                allergens = [.milk]
            case "peanut sauce":
                allergens = [.peanuts]
            case "quesadilla", "rice pudding", "yogurt parfait":
                allergens = [.milk]
            case "tofu scramble":
                allergens = [.soy]
            case "apple oatmeal", "avocado toast", "baked potato", "bean burger", "bean dip", "beef stew", "broccoli fritter", "chicken soup", "chicken vegetable stew", "chickpea pasta", "corn porridge", "falafel", "fruit smoothie bowl", "gnocchi", "green pea soup", "honey", "lentil soup", "mashed potato", "meat loaf", "millet porridge", "minestrone", "mung dal", "oat pancake", "pasta with tomato sauce", "pumpkin soup", "rice and beans", "risotto", "shepherd's pie", "soft taco", "spinach pancake", "sweet potato fritter", "tomato soup", "turkey chili", "vegetable curry", "vegetable soup", "waffle":
                allergens = []
            default:
                preconditionFailure("Missing confirmed-allergen review for \(name)")
            }
            return allergens.map(\.rawValue).sorted()
        }
        if category == .grain {
            let containsWheat: Bool
            switch key {
            case "angel hair pasta", "bread", "bulgur", "couscous", "einkorn", "farina", "farro", "freekeh", "kamut", "multigrain bread", "orzo", "pasta", "semolina", "spelt", "toast", "udon noodle", "wheat berries", "wheat cereal", "wheat noodle", "whole-grain pasta", "whole-wheat bread", "whole-wheat couscous", "whole-wheat toast":
                containsWheat = true
            case "amaranth", "arborio rice", "barley", "barley cereal", "basmati rice", "black rice", "bran cereal", "brown rice", "buckwheat", "buckwheat noodle", "cassava flour porridge", "corn tortilla", "cornbread", "cornmeal", "cream of rice", "fonio", "grits", "hominy", "infant barley cereal", "infant multigrain cereal", "infant oatmeal", "infant rice cereal", "jasmine rice", "kasha", "millet", "oat bran", "oatmeal", "pearl barley", "polenta", "puffed rice cereal", "quinoa", "red rice", "rice", "rice noodle", "rice porridge", "rye", "rye bread", "sorghum", "steel-cut oats", "teff", "white rice", "wild rice":
                containsWheat = false
            default:
                preconditionFailure("Missing confirmed wheat-allergen review for \(name)")
            }
            return containsWheat ? [SolidsAllergen.wheat.rawValue] : []
        }
        var values: [SolidsAllergen] = []
        if category == .dairy { values.append(.milk) }
        if category == .egg || (category == .preparedFood && key.contains("egg")) { values.append(.egg) }
        if category == .seafood {
            let shellfish = ["shrimp", "prawn", "crab", "lobster", "crayfish", "langoustine"]
            let mollusks = ["clam", "mussel", "oyster", "scallop", "octopus", "squid"]
            if shellfish.contains(where: key.contains) {
                values.append(.crustaceanShellfish)
            } else if !mollusks.contains(where: key.contains) {
                values.append(.fish)
            }
        }
        if key.contains("peanut") { values.append(.peanuts) }
        if category == .nutAndSeed && !key.contains("peanut") && !key.contains("sesame") && !key.contains("sunflower") && !key.contains("pumpkin") && !key.contains("chia") && !key.contains("flax") && !key.contains("hemp") && !key.contains("poppy") && !key.contains("coconut") { values.append(.treeNuts) }
        if key.contains("wheat") || key.contains("bread") || key.contains("toast") || key.contains("pasta") || key.contains("couscous") || key.contains("bulgur") || key.contains("seitan") || key.contains("cracker") || key.contains("noodle") { values.append(.wheat) }
        if key.contains("soy") || key.contains("tofu") || key.contains("tempeh") || key.contains("edamame") || key.contains("miso") { values.append(.soy) }
        if key.contains("sesame") || key.contains("tahini") { values.append(.sesame) }
        return Array(Set(values.map(\.rawValue))).sorted()
    }

    private static func possibleAllergenIDs(name: String, category: SolidsFoodCategory) -> [String] {
        let key = normalized(name)
        if category == .preparedFood {
            let allergens: [SolidsAllergen]
            switch key {
            case "apple oatmeal", "baked potato", "corn porridge", "fruit smoothie bowl", "mashed potato", "pumpkin soup", "risotto", "shepherd's pie", "tomato soup":
                allergens = [.milk]
            case "avocado toast":
                allergens = [.sesame, .wheat]
            case "bean burger":
                allergens = [.egg, .soy, .wheat]
            case "bean dip", "falafel":
                allergens = [.sesame]
            case "beef stew", "chicken soup", "chicken vegetable stew", "green pea soup", "lentil soup", "minestrone", "turkey chili", "vegetable soup":
                allergens = [.wheat]
            case "broccoli fritter", "sweet potato fritter":
                allergens = [.milk, .egg, .wheat]
            case "chickpea pasta":
                allergens = [.egg, .wheat]
            case "egg fried rice":
                allergens = [.sesame, .soy, .wheat]
            case "fish cake", "salmon cake":
                allergens = [.milk, .egg, .wheat]
            case "french toast":
                allergens = [.milk, .wheat]
            case "gnocchi":
                allergens = [.milk, .egg, .wheat]
            case "macaroni and cheese":
                allergens = [.egg, .wheat]
            case "meat loaf":
                allergens = [.milk, .egg, .soy, .wheat]
            case "oat pancake", "spinach pancake":
                allergens = [.milk, .egg, .wheat]
            case "pasta with tomato sauce":
                allergens = [.milk, .egg, .wheat]
            case "peanut sauce":
                allergens = [.sesame, .soy, .wheat]
            case "quesadilla":
                allergens = [.wheat]
            case "rice pudding":
                allergens = [.egg]
            case "soft taco":
                allergens = [.milk, .soy, .wheat]
            case "tofu scramble":
                allergens = [.sesame]
            case "vegetable curry":
                allergens = [.milk, .treeNuts, .peanuts]
            case "yogurt parfait":
                allergens = [.treeNuts, .wheat]
            case "waffle":
                allergens = [.milk, .egg, .soy, .wheat]
            case "honey", "millet porridge", "mung dal", "rice and beans":
                allergens = []
            default:
                preconditionFailure("Missing possible-allergen review for \(name)")
            }
            let confirmed = Set(allergenIDs(name: name, category: category))
            return allergens.map(\.rawValue).filter { !confirmed.contains($0) }.sorted()
        }
        if category == .grain {
            var allergens = [SolidsAllergen]()
            switch grainPreparationForm(name: name) {
            case .bread:
                allergens += [.egg, .milk, .sesame, .soy]
                if ["corn tortilla", "cornbread", "rye bread"].contains(key) {
                    allergens.append(.wheat)
                }
            case .pasta:
                allergens.append(.egg)
                if key == "buckwheat noodle" || key == "rice noodle" {
                    allergens.append(.wheat)
                }
            case .puffedCereal:
                break
            case .softGrain:
                if key.contains("infant") {
                    allergens += [.milk, .soy]
                }
                if key == "infant multigrain cereal" || key == "bran cereal" {
                    allergens.append(.wheat)
                }
            }
            let confirmed = Set(allergenIDs(name: name, category: category))
            return Array(Set(allergens.map(\.rawValue)).subtracting(confirmed)).sorted()
        }
        var values = [SolidsAllergen]()
        if category == .beanAndPlantProtein && key == "hummus" { values += [.sesame] }
        if category == .beanAndPlantProtein && key == "refried bean" { values += [.milk] }
        if category == .beanAndPlantProtein && key == "pea protein patty" { values += [.milk, .egg, .soy, .wheat] }
        if category == .meat && key.contains("meatball") { values += [.milk, .egg, .soy, .wheat] }
        if category == .egg && ["egg omelet", "scrambled egg"].contains(key) { values += [.milk] }
        if category == .herbAndFlavor && key.contains("za'atar") { values += [.sesame] }
        if category == .preparedFood {
            if ["waffle", "pancake", "fritter", "french toast", "fish cake", "salmon cake", "meat loaf", "gnocchi"].contains(where: key.contains) {
                values += [.milk, .egg, .wheat]
            }
            if ["bean burger", "broccoli fritter", "soft taco", "spinach pancake", "sweet potato fritter"].contains(where: key.contains) {
                values += [.egg, .wheat]
            }
            if key.contains("quesadilla") || key.contains("macaroni and cheese") { values += [.milk, .wheat] }
            if key.contains("smoothie") || key.contains("yogurt parfait") || key.contains("rice pudding") { values += [.milk] }
            if key.contains("risotto") || key.contains("shepherd's pie") || key.contains("mashed potato") { values += [.milk] }
            if key.contains("falafel") || key.contains("bean dip") { values += [.sesame] }
        }
        return Array(Set(values.map(\.rawValue)).subtracting(allergenIDs(name: name, category: category))).sorted()
    }

    private static func servingAmountGuidance(
        name: String,
        category: SolidsFoodCategory,
        ageMonths: Int,
        visual: SolidsServingVisual
    ) -> SolidsServingAmountGuidance {
        let key = normalized(name)

        if key == "peanut butter" {
            return SolidsServingAmountGuidance(
                firstServing: "1 tsp smooth peanut butter, thinned into a familiar food. Offer a small taste first, pause about 10 minutes, then continue the prepared amount if no reaction appears.",
                routineServing: "About 2 tsp smooth peanut butter, thinned or spread very thinly. The child does not need to finish it."
            )
        }

        if category == .nutAndSeed {
            let safeForm: String
            if key.contains("butter") || key == "tahini" {
                safeForm = "smooth \(name.lowercased()), well thinned"
            } else if key.contains("ground") {
                safeForm = "\(name.lowercased()) mixed completely into moist food"
            } else if ["chia", "flax", "hemp", "poppy", "pumpkin seed", "sesame", "sunflower seed"].contains(where: key.contains) {
                safeForm = "\(name.lowercased()), finely ground or fully softened as appropriate and mixed into moist food"
            } else {
                safeForm = "\(name.lowercased()), finely ground into moist food"
            }
            return SolidsServingAmountGuidance(
                firstServing: "1 tsp \(safeForm); begin with a small taste.",
                routineServing: "Up to 2 tsp \(safeForm), after it is tolerated."
            )
        }

        if category == .herbAndFlavor {
            if flavorPreparationForm(name: name) == .bayLeaf {
                return SolidsServingAmountGuidance(
                    firstServing: "No leaf in the serving. Infuse the family dish with 1 whole leaf, then remove it before plating the child's portion.",
                    routineServing: "No leaf in the serving. Use only the flavor infused into the food and remove every leaf before serving."
                )
            }
            return SolidsServingAmountGuidance(
                firstServing: "A small pinch mixed evenly through a familiar food.",
                routineServing: "A pinch to ⅛ tsp mixed through the meal, adjusting for flavor."
            )
        }

        if key == "honey" {
            return SolidsServingAmountGuidance(
                firstServing: "After 12 months only: a small drizzle mixed into food.",
                routineServing: "Up to 1 tsp as an occasional added sweetener."
            )
        }

        if category == .egg {
            if key == "egg yolk" {
                return SolidsServingAmountGuidance(
                    firstServing: "1–2 tsp fully cooked yolk mashed into moist food; begin with a small taste.",
                    routineServing: "Up to 1 fully cooked yolk kept moist, after egg is tolerated. The child does not need to finish it."
                )
            }
            return SolidsServingAmountGuidance(
                firstServing: "1–2 tsp fully cooked egg; begin with a small taste.",
                routineServing: "About one-third of a fully cooked egg, after it is tolerated."
            )
        }

        let routineVolume = ageMonths < 9 ? "1–2 tbsp" : "2–4 tbsp"
        let firstServing: String
        let routineServing: String
        switch visual {
        case .spear:
            firstServing = "1 soft prepared piece of \(name.lowercased())."
            routineServing = "1–2 soft prepared pieces of \(name.lowercased()), or about \(routineVolume) when mashed or chopped."
        case .flattened:
            firstServing = "1 soft flattened piece of \(name.lowercased())."
            routineServing = "2–4 soft flattened pieces of \(name.lowercased()), or about \(routineVolume) prepared."
        case .softPieces:
            firstServing = "1–2 soft prepared pieces of \(name.lowercased())."
            routineServing = "About \(routineVolume) of prepared \(name.lowercased()) pieces."
        case .thinSpread:
            firstServing = "1 tsp of \(name.lowercased()) in a very thin layer; begin with a small taste."
            routineServing = "Up to 2 tsp of \(name.lowercased()) spread very thinly, after it is tolerated."
        case .mashed, .shredded, .flakes, .spoon:
            firstServing = "1–2 tsp prepared \(name.lowercased())."
            routineServing = "About \(routineVolume) prepared \(name.lowercased())."
        }

        return SolidsServingAmountGuidance(
            firstServing: firstServing,
            routineServing: routineServing
        )
    }

    private static func ingredientQuantity(for name: String) -> String {
        guard let food = food(named: name) else { return "As needed" }
        switch food.category {
        case .herbAndFlavor:
            return flavorPreparationForm(name: name) == .bayLeaf
                ? "1 leaf for infusion; remove"
                : "Pinch"
        case .nutAndSeed:
            let key = normalized(name)
            return key.contains("butter") || key == "tahini"
                ? "1–2 tsp, thinned"
                : "1–2 tsp, finely ground into moist food"
        case .meat, .seafood, .egg, .beanAndPlantProtein: return "2 tbsp prepared"
        case .dairy: return "2 tbsp"
        default: return "2–4 tbsp prepared"
        }
    }

    private static func substitutions(for name: String) -> [String] {
        guard let food = food(named: name) else { return [] }
        return (foodsByCategory[food.category] ?? []).filter { candidate in
            candidate.category == food.category
                && candidate.id != food.id
                && candidate.minimumAgeMonths <= food.minimumAgeMonths
        }.prefix(3).map(\.name)
    }

    private static func aliases(for name: String) -> [String] {
        switch name {
        case "Garbanzo bean": ["Chickpea"]
        case "Cilantro": ["Coriander leaf"]
        case "Eggplant": ["Aubergine"]
        case "Zucchini": ["Courgette"]
        case "Bell pepper": ["Sweet pepper"]
        case "Arugula": ["Rocket"]
        case "Corn": ["Maize"]
        case "Pollock": ["Pollack"]
        case "Plain whole-milk yogurt": ["Plain full-fat yogurt"]
        default: []
        }
    }

    private static func names(in value: String) -> [String] {
        value.split(separator: ";").map {
            $0.trimmingCharacters(in: .whitespacesAndNewlines)
        }.filter { !$0.isEmpty }
    }

    private static func slug(_ value: String) -> String {
        normalized(value)
            .replacingOccurrences(of: "[^a-z0-9]+", with: "-", options: .regularExpression)
            .trimmingCharacters(in: CharacterSet(charactersIn: "-"))
    }

    private static func normalized(_ value: String) -> String {
        value.folding(options: [.caseInsensitive, .diacriticInsensitive], locale: Locale(identifier: "en_US_POSIX"))
    }

